return {["Sheet1"]={["1"]={["id"]=1,["introText"]=[[塞北一武痴独创的诡异内功，习练至绝顶境界，可将内劲脱离经脉，于皮肤之间流转，与中原内功之道大相径庭，堪称异端。]],["itemId"]=[[duohunmice]],["name"]=[[    HIY夺魂秘册NOR]],["need"]=15,["pic"]=[[Image/UI/StoreUI/shujuan4.png]],["thankText"]=[[YEL满月临弓影，连星入剑端。
