待到浓雾散去，你蓦然发现，手上的珍品券已经变成了一本泛黄的武学秘籍，令你错愕不已。NOR]],["time"]=11,["title"]=[[全篇]]},["103"]={["id"]=103,["introText"]=[[WHT天启帮聚义堂绝学之一，由章作之不断完善。秉承聚义堂一贯传统，凡是认可之人便可将武功传给他，无需受帮中规矩限制。NOR]],["itemId"]=[[yuxianjue]],["name"]=[[HIM羽仙诀NOR]],["need"]=5,["pic"]=[[Image/UI/StoreUI/shujuan5.png]],["thankText"]=[[YEL满月临弓影，连星入剑端。
