你沉吟不语，将珍品券捧于手上，似在心中思索着什么。
须臾间，空中一股浓雾飘散而来，遮蔽了你的视线。
待到浓雾散去，你蓦然发现，手上的珍品券已经变成了一本泛黄的武学秘籍，令你错愕不已。NOR]],["time"]=11,["title"]=[[全篇]]},["104"]={["id"]=104,["introText"]=[[WHT他就是梅大侠。他生得容貌清癯，风骨傲然，一代大侠之态显露无疑。NOR]],["itemId"]=[[mianju1023]],["name"]=[[HIR梅大侠NOR]],["need"]=25,["pic"]=[[Image/UI/AttrUI/mianju/meiniansheng1.png]],["thankText"]=[[YEL你方将珍品券递上，一位小二便从客栈中走出，拱手道：“梅大侠已经离去，不过少侠不必着急，我知道有条小路可助少侠追上梅大侠。”

你照小二所说找到小路，行至一个路口时忽然听见前方传来打斗声，你加紧前往，便见十几个山匪围住了一位身材高大老者。老者虽发须皆白但风骨依旧，立如苍松，势如猛虎，即使被十几个杀人如麻的山匪围困依旧泰然自若。

山匪们群起攻向老者，老者招似猛虎，剑似游龙，转瞬之间山匪便倒下一半。你从老者精妙的剑招回过神来，上前助他击败其余山匪。待山匪皆已倒下，老者收起重剑向你抱拳道谢，得知你是专门来寻他后便邀请你与他同行，你欣然同意。你们一起策马同行，你忽有预感自己将会收获良多。NOR]],["time"]=11,["title"]=[[RED铁骨墨萼NOR]]},["105"]={["id"]=105,["introText"]=[[WHT他就是幽冥教主，传闻他武功极高，曾与唐家唐不平交手三百回合不落下风。他面如冠玉，眉宇间英气十足，不怒自威，举手投足之间散发着一股慵懒之意。传言说其本是女儿身，但对外宣称为男人，以便行走江湖，统治帮派。NOR]],["itemId"]=[[mianju1099]],["name"]=[[HIM幽冥教主NOR]],["need"]=20,["pic"]=[[Image/UI/AttrUI/mianju/youmingjiaozhu1.png]],["thankText"]=[[YEL珍品券刚一递上，蓦然间你只听见一声低沉地耳语：“随我来。”声音如冷冽的寒潭，却让人分辨不出男女。你只觉腰间肋下被人裹挟住，随后身子一轻，整个人竟然腾空而起，向着某个方向凌空飞去。

迷迷糊糊间，你身后之人托着你飘然落地，你睁眼一看，竟来到一座阴森死寂的佛殿之中，殿中左右两侧各站着五尊巨大佛像，正是十殿阎罗王。

“无常善勾恶人命，七宝可避万般劫。既然少侠愿投拜帖于本座，本座便与少侠说一说这十殿阎罗的故事。”冷冽的声音从你背后响起，将每位阎罗的故事娓娓道来。

你虽然觉得有些惊怕，但却沉浸在这些鲜为人知的故事中，直至东方之际白。NOR]],["time"]=11,["title"]=[[MAG十殿阎罗NOR]]},["106"]={["id"]=106,["introText"]=[[WHT他就是牛郎。他生得仪表堂堂，英俊非凡，眼中满是柔情，令人动容。NOR]],["itemId"]=[[mianju1034]],["name"]=[[HIC牛郎NOR]],["need"]=10,["pic"]=[[Image/UI/AttrUI/mianju/niulang.png]],["thankText"]=[[YEL你将珍品券递上，片刻后，一位男子向你走来，他生得仪表堂堂，虽是身着布衣，却依旧是英俊非凡。男子周身喜鹊环绕，手牵一头高大的水牛，走至你面前，拱手道：“久等了，随我来。”

你跟着男子走到一间小院，小院不大但温馨舒适。院子其右种有葡萄，葡萄架下站着一位女子，手拿木篮，盈盈一笑，灼灼其华。男子快步上前接过女子手中木篮，你见两人身影相依，只觉神仙眷侣便应是如此。

女子领你至院中木椅坐下，一只憨状可掬的绣虎猫窝在你的脚边。片刻后，男子端来了一盘甘甜的果子，又沏上了一壶清茶，你与男子闲聊逗猫，好不怡然。黄昏将至，炊烟渺渺，你又品尝了一番女子做的佳肴后，就告辞离开了。NOR]],["time"]=11,["title"]=[[CYN迢迢牵牛星NOR]]},["107"]={["id"]=107,["introText"]=[[WHT她就是龙姑娘。她生得清雅绝俗，秀丽无比，已不再是凡间人物。NOR]],["itemId"]=[[mianju1013]],["name"]=[[YEL龙姑娘NOR]],["need"]=6,["pic"]=[[Image/UI/AttrUI/mianju/xiaolongnv.png]],["thankText"]=[[YEL你将珍品券递上，许久后，沉重的石门缓缓下降，露出石门后的墓穴和一位白衣飘然的女子。女子清雅绝俗，不似凡间人物，她虽还是面若秋霜，但比之曾经要柔和些，她淡淡地道：“许久不见。”

你随女子进到墓穴中，墓穴内依旧是别有洞天，似一方世外桃源般，未曾有何改变。待你坐下，女子道了句“稍等。”后翩然离去，片刻后，女子捧了个石碗走来，与她同来的还有一个英气逼人的男子，男子只有独臂，手上端着一个石盘，石盘中盛着些果子。

石碗中便是蜂王玉露，胜似琼浆玉露，分外甘甜。石盘中是你叫不出名字的果子，入口细腻，清润甘美。墓穴虽清冷，别无乐处，但你们三人畅聊一番武学经历，倒也是其乐融融。NOR]],["time"]=11,["title"]=[[ORA古墓掌门NOR]]},["108"]={["id"]=108,["introText"]=[[WHT这就是黄牛腰佩。小牛皮腰带，正中挂着一块铁牌，牌上刻一黄牛，牌子表面镀金漆，金光耀眼，结实耐用。牌子铸造精细，黄牛栩栩如生。NOR]],["itemId"]=[[eq2020ld01]],["name"]=[[HIY黄牛腰佩NOR]],["need"]=2,["pic"]=[[Image/UI/StoreUI/wuqi.png]],["thankText"]=[[YEL三尺龙泉剑，匣里无人见。
一张落雁弓，百支金花箭。
