待到浓雾散去，你蓦然发现，你的手上竟多了一件宝光四射的装备，而那张珍品券早已不知所踪。NOR]],["time"]=11,["title"]=[[HIW珍品装备NOR]]},["109"]={["id"]=109,["introText"]=[[WHT这就是钦耕御戒。古时一位皇帝感叹天下黎民之苦，于宫中垦地亲耕，后为纪念此举，命工匠打造钦耕戒三枚，此戒便是其中之一。NOR]],["itemId"]=[[eq2020ld02]],["name"]=[[HIC钦耕御戒NOR]],["need"]=2,["pic"]=[[Image/UI/StoreUI/wuqi.png]],["thankText"]=[[YEL三尺龙泉剑，匣里无人见。
