待到浓雾散去，你蓦然发现，手上的珍品券已经变成了一本泛黄的武学秘籍，令你错愕不已。NOR]],["time"]=12,["title"]=[[全篇]]},["116"]={["id"]=116,["introText"]=[[WHT相传，一世名将杨五郎得高僧智光大师点化，遂于五台山挂单出家。皈依之后，五郎长枪换作木棍，将一身名震沙场的杨家枪，演化为六十四点八卦棍，名曰“五郎八卦棍”。NOR]],["itemId"]=[[wulangbaguagunbox1]],["name"]=[[五郎八卦棍]],["need"]=16,["pic"]=[[Image/UI/StoreUI/shujuan3.png]],["thankText"]=[[YEL满月临弓影，连星入剑端。
不学燕丹客，徒歌易水寒。
