待到浓雾散去，你蓦然发现，手上的珍品券已经变成了一本泛黄的武学秘籍，令你错愕不已。NOR]],["time"]=12,["title"]=[[全篇]]},["117"]={["id"]=117,["introText"]=[[WHT由江湖奇人、有“五柳先生”之称的柳安国所创。五柳先生文武双全，儒释道皆通，海内闻名。NOR]],["itemId"]=[[jiugongliuhezhang]],["name"]=[[九宫六合掌]],["need"]=14,["pic"]=[[Image/UI/StoreUI/shujuan4.png]],["thankText"]=[[YEL满月临弓影，连星入剑端。
