不学燕丹客，徒歌易水寒。
你沉吟不语，将珍品券捧于手上，似在心中思索着什么。
须臾间，空中一股浓雾飘散而来，遮蔽了你的视线。
待到浓雾散去，你蓦然发现，手上的珍品券已经变成了一本泛黄的武学秘籍，令你错愕不已。NOR]],["time"]=12,["title"]=[[全篇]]},["119"]={["id"]=119,["introText"]=[[WHT他就是张真人。他生得高大魁梧，须眉俱白。身着武当道服，卓立于大殿之上，正气凛然，宽和从容，颇有仙风道骨之姿，令人大有敬畏之心。NOR]],["itemId"]=[[mianju1135]],["name"]=[[HIB张真人NOR]],["need"]=25,["pic"]=[[Image/UI/AttrUI/mianju/zhangzhenren.png]],["thankText"]=[[YEL你将珍品券递上，一个身着蓝色道袍的小道童自山门走出，恭敬道：“少侠久等了，这边请。”

你随小道童行走在武当山中，一路景色秀美，赏心悦目，你看得专心，不知不觉间就已随小道童走到了崇福岩。只见一块岩石悬空突出，似一只龇牙咧嘴的石虎，威风凛凛，叫人生畏。小道童又领你走到一座殿前，便拱手告退。

你走入殿内，只见一位老者坐于窗前，老者虽须眉俱白但依旧魁梧健壮，身着道袍，颇有仙风道骨之姿。见你到来老者起身邀你入座，随后又给你斟上一盏清茶。老者此时和蔼随和，似家中长辈一般对你嘘寒问暖。

窗外有山石嶙峋，草木欣荣，殿内茶香可口，沁人心脾。你与老者自生活琐事聊到武功道学，直至暮色苍茫你才告辞离开。NOR]],["time"]=12,["title"]=[[BLU太极玄功NOR]]},["120"]={["id"]=120,["introText"]=[[WHT她就是素素。她生得明媚清丽，娇艳绝伦，目光直视远方，饱含决然之色，闭眼时，泪珠滚落，似雨后梨花，凄美断人肠。NOR]],["itemId"]=[[mianju1134]],["name"]=[[HIM素素NOR]],["need"]=15,["pic"]=[[Image/UI/AttrUI/mianju/susu.png]],["thankText"]=[[YEL珍品券刚一送上，便走出一位明媚清丽的女子，她莞尔一笑，道：“少侠来了，里面坐吧。”

你随女子进入小院中坐下，女子为你倒了一杯清茶，又端上了一盘甜果。你们坐在院中聊了片刻，就听见一声孩童的呼喊，你循声望去，便见一位男童抱着一条大鱼跑进院内，一位高大俊朗的男子紧随其后，女子忍俊不禁，起身相迎。一家三口，其乐融融，让你不禁心生艳羡。

小院顿时热闹了起来，男子女子一起在厨中忙碌，你在院中给男童讲述江湖上的奇闻异事和美景美食，一时间小院皆是欢声笑语。

夕阳西斜，晚饭过后你们坐于院中闲聊。谈及师门，男子道他们也将要返回师门，言语间皆是对未来的向往，你也向他们送出祝福。直至月上梢头，你才告辞离开。NOR]],["time"]=12,["title"]=[[MAG至情至性NOR]]},["121"]={["id"]=121,["introText"]=[[WHT她就是玉兔。她生得娇小可爱，玲珑剔透，所见之人无不心生怜爱。NOR]],["itemId"]=[[mianju1042]],["name"]=[[PNK玉兔NOR]],["need"]=10,["pic"]=[[Image/UI/AttrUI/mianju/yuetubai.png]],["thankText"]=[[YEL你将珍品券递上，片刻后自云间走下一位娇小玲珑的女子，她身着华服，头戴半面兔形面具，更显俏皮可爱。她走至你面前，轻笑了两声，声音清脆如铃，悦耳动听，她又说到：“少侠，随我来。”

你欣然同意，一朵白云就自她脚下升起，你小心翼翼地站了上去，白云便腾空而起，向着明月而去，转瞬就来到了一座华美的宫府前，宫门上有一白玉匾额，上刻广寒宫。

你随女子在宫中游览，宫府以水晶为阶，琉璃为瓦，白玉为墙，月光下熠熠生辉。宫里四处仙气渺渺，山石秀丽，奇花争艳，一步一景，一景一境，叫人应接不暇，

忽然你听见殿中传来悦耳仙乐，正欲前往却一脚踏空，你惊呼一声，景色倏然转换，变成了你熟悉的卧房。窗外月色清辉，原来方才只是一场梦罢了。NOR]],["time"]=12,["title"]=[[HIW捣药玉兔NOR]]},["122"]={["id"]=122,["introText"]=[[WHT他就是杨少侠。他生得剑眉入鬓，清癯俊秀，一身素服，手持一柄乌黑长剑，英气逼人。NOR]],["itemId"]=[[mianju1051]],["name"]=[[YEL杨少侠NOR]],["need"]=8,["pic"]=[[Image/UI/AttrUI/mianju/nianqingyangguo.png]],["thankText"]=[[YEL珍品券刚一送上，登时走出一位步履飘逸，清癯俊秀的男子。他手持一柄乌黑长剑，向你说了句：“今日街上有庙会，热闹非凡，不如我们也前去瞧瞧？”

你欣然同意，与男子一同前往。正值华灯初上，月色晴朗，街上人影绰绰，果真是热闹非凡。你们观了祭神歌舞，又看了街边卖艺，走累了便在茶馆歇脚，看了一段皮影戏。随后你们行至河边，只见河面灯火通明，一盏盏水灯随波逐流而去，点点星火照亮了一条长河，宛如一条红色的银河。

男子不知何时离去，待他回来时手中拿有两盏莲花状的水灯。你随男子走到水边，点上灯中的蜡烛，许下心中祈愿，将它放入河中。水灯随着河流飘荡，和别的水灯一起流向远方，或许这样愿望就可以传给神明吧。NOR]],["time"]=12,["title"]=[[ORA杨氏后人NOR]]},["123"]={["id"]=123,["introText"]=[[WHT这就是迎春巾。白绸头巾，其上以精巧女红手法绣制了一幅春归图。NOR]],["itemId"]=[[eq2020cf02]],["name"]=[[HIY迎春巾NOR]],["need"]=2,["pic"]=[[Image/UI/StoreUI/wuqi.png]],["thankText"]=[[YEL三尺龙泉剑，匣里无人见。
