待到浓雾散去，你蓦然发现，你的手上竟多了一件宝光四射的装备，而那张珍品券早已不知所踪。NOR]],["time"]=12,["title"]=[[HIW珍品装备NOR]]},["124"]={["id"]=124,["introText"]=[[WHT这就是阳春服。以江南上等丝绸制成的华服，轻薄贴身。NOR]],["itemId"]=[[eq2020cf03]],["name"]=[[HIY阳春服NOR]],["need"]=2,["pic"]=[[Image/UI/StoreUI/wuqi.png]],["thankText"]=[[YEL三尺龙泉剑，匣里无人见。
