待到浓雾散去，你蓦然发现，手上的珍品券已经变成了一份残页，令你错愕不已。NOR]],["time"]=12,["title"]=[[残页]]},["129"]={["id"]=129,["introText"]=[[WHT此剑法运气之道极为古怪，常逆行真气致自己轻微内伤，趁丹田内真气暴涨乱行之际出手伤人，堪称是一门未伤敌先伤己的剑法。NOR]],["itemId"]=[[tiexueshijian]],["name"]=[[铁血誓剑]],["need"]=20,["pic"]=[[Image/UI/StoreUI/shujuan2.png]],["thankText"]=[[YEL满月临弓影，连星入剑端。
