待到浓雾散去，你蓦然发现，手上的珍品券已经变成了一本泛黄的武学秘籍，令你错愕不已。NOR]],["time"]=13,["title"]=[[全篇]]},["13"]={["id"]=13,["introText"]=[[这是一个千机武盒。盒子上画着许多持刀握剑的小人，每个小人手持兵器摆出不同的姿势，一招一式有板有眼，栩栩如生。]],["itemId"]=[[2020bingqiwuxuecanpian1]],["name"]=[[    HIR千机武盒NOR]],["need"]=1,["pic"]=[[Image/UI/StoreUI/xiangzi1.png]],["thankText"]=[[YEL满月临弓影，连星入剑端。
