你沉吟不语，将武学名录捧于手上，似在心中思索着什么。
须臾间，空中一股浓雾飘散而来，遮蔽了你的视线。
待到浓雾散去，你蓦然发现，手上的武学名录已经变成了一陈旧的宝箱，令你错愕不已。NOR]],["time"]=2,["title"]=[[宝箱]]},["130"]={["id"]=130,["introText"]=[[WHT塞北一武痴独创的诡异内功，习练至绝顶境界，可将内劲脱离经脉，于皮肤之间流转，与中原内功之道大相径庭，堪称异端。NOR]],["itemId"]=[[duohunmice]],["name"]=[[夺魂秘册]],["need"]=16,["pic"]=[[Image/UI/StoreUI/shujuan3.png]],["thankText"]=[[YEL满月临弓影，连星入剑端。
