不学燕丹客，徒歌易水寒。
你沉吟不语，将珍品券捧于手上，似在心中思索着什么。
须臾间，空中一股浓雾飘散而来，遮蔽了你的视线。
待到浓雾散去，你蓦然发现，手上的珍品券已经变成了一本泛黄的武学秘籍，令你错愕不已。NOR]],["time"]=13,["title"]=[[全篇]]},["132"]={["id"]=132,["introText"]=[[WHT她就是余夫人。她神色冷冽、目光如炬，发束金冠，金丝黑纱遮面，看起来让人不可靠近，似乎下一刻就会杀人于无形。NOR]],["itemId"]=[[mianju1085]],["name"]=[[HIB余夫人NOR]],["need"]=25,["pic"]=[[Image/UI/AttrUI/mianju/yufuren.png]],["thankText"]=[[YEL你走近一座气势恢宏的高楼，侍从接过你的珍品券，带你穿过幽深的长廊，每间客房的纸窗上皆映有人影，传出各种听不真切的窃窃声。而尽头的房门则从内打开，穿黑色绸衫的余夫人自屏风后走出，她容貌俏丽，只是眼神冰冷，笑起来也无丝毫暖意，“少侠来此有何事？”你想问她在无间林的往事，或者余志枭的死因，但你接触到她晦暗深沉的目光，只怕这些话问出口要惹来麻烦。

于是你默然无言，略坐片刻起身时，终还是问了一句：“那件事，你可有过后悔？”

她吃吃发笑，眼底有几分疯狂之色：“我用千年寒玉保住志枭尸身不腐，随时都能和我在一起，又有何悔？”

你摇头叹息，走出客房顿觉走廊左右每扇门后面像有贪婪的眼睛在窥视，令你毛骨悚然，不由大步离去。NOR]],["time"]=13,["title"]=[[BLU永夜夫人NOR]]},["133"]={["id"]=133,["introText"]=[[WHT他就是剑神。他生得眉如利剑、面似白雪。眉心中一点剑痕，眼神明亮深邃却暗藏孤寂。剑刃握于手中，剑华流转不息，剑芒吞吐不定。试问何为剑客之心？原是一曲寂寞之情。NOR]],["itemId"]=[[mianju1136]],["name"]=[[HIM剑神NOR]],["need"]=15,["pic"]=[[Image/UI/AttrUI/mianju/jianshen.png]],["thankText"]=[[YEL你递上珍品券，庭院内从鲜花丛深处走出一位穿着雪白长衫、背着乌鞘长剑的男人。

见到你，他如远山冰雪般飘渺的神情，闪过一丝炽热的光芒，“你习武的天赋不错。”

这话虽语气平静，但你能听出里面的欣赏之意。你忍不住提出要和他切磋的要求，他却摇头拒绝，苍白的脸上有着傲视天下的冷漠：“我的剑招只为杀人。”

似不忍心见你的希望落空，他拔出那柄形势古老的漆黑长剑，在你面前演示了他的剑法，快如闪电，剑气寒意飒飒，令盛夏的晴空仿佛飘起凛冬的大雪。

待他的剑回到剑鞘，你才发觉满庭的花丛竟全部凋谢，仔细看原是被汹涌的剑气斩尽。

“凭你习武的天赋，我很期待日后能和你一较高下。”说罢，他几个闪身间跃至房梁上，施展轻功消失在了远方。NOR]],["time"]=13,["title"]=[[CYN落花吹雪NOR]]},["134"]={["id"]=134,["introText"]=[[WHT她就是桃花仙子。她一双似醉非醉桃花眼，眼波流转秋水盈盈，眉间一点殷红更衬肌肤胜雪，手挽红线，含笑脉脉，周身隐隐有花香，似红尘中来，又纤尘不染。NOR]],["itemId"]=[[mianju1068]],["name"]=[[PNK桃花仙子NOR]],["need"]=10,["pic"]=[[Image/UI/AttrUI/mianju/taohuaxian1.png]],["thankText"]=[[YEL你将珍品券递上，自桃花林中走出一位清丽绝俗的女子，她步履轻盈地行至你面前，施礼笑道：“少侠，这边请。”

四周花开漫野，茜粉如霞，恍然间你被她带到一颗巨大的桃树下，此树花枝层叠，连连绵绵看不到边际。

你正暗自称奇，她轻拍桃树干，桃树像被挠痒般颤抖起来，桃花纷纷似雨落了你满身，惹来她掩唇娇笑，“少侠簪花的模样倒是俊俏。”

“好啊，你竟故意捉弄我。”你佯装恼怒，她立马笑着作揖道歉，从树根处挖出一坛酒，“我这坛桃花酿就当是赔礼，送与少侠。”

说着她拍开泥封，一股醇厚的酒香飘逸而出，令你连赞三声，为此她露出得意之色，主动为你斟酒，领你跃至树干上品尝。

此酒似能洗净人间烦恼，你醉卧桃枝上似乎做了一场很美的梦。NOR]],["time"]=13,["title"]=[[HIW七夕情缘NOR]]},["135"]={["id"]=135,["introText"]=[[WHT她就是丁红蝶。她生得娇艳绝伦，犹如带着晨露的带刺玫瑰，一双灵气十足的大眼睛充满了欺骗性，让人以为其人畜无害、从而不知不觉间放下防备之心。NOR]],["itemId"]=[[mianju1066]],["name"]=[[YEL丁红蝶NOR]],["need"]=5,["pic"]=[[Image/UI/AttrUI/mianju/dinghongdie.png]],["thankText"]=[[YEL你走近黑瓦绿栋的寨舍，向侍女递上珍品券，随后被带至教主会客的小厅。

你坐下不久听到一串慌乱的脚步声，有人来禀教主不见了。待厅内的人都出去寻找教主，房间的横梁上忽然跃下一位穿粉衫的少女，正是江湖闻名的丁红蝶。

见你瞧见这幕，她白皙的脸颊染上薄红，凶巴巴道：“你把我的毒蛛吓跑了！”

你哑然失笑，看她眼神有了杀气，你连忙肃容询问是何缘由。

原来她发现梁上有只罕见的毒蛛，但那毒蛛生性警惕，稍有风吹草动便消失得无踪，丁红蝶为捉住它不惜在蛛丝旁苦守了三日，岂料因你的到来将它惊动，让丁红蝶功亏一篑。

你不好意思地向她道歉，说下次寻到厉害的毒虫送给她，她方展颜一笑，这笑容恰似昙花初现、雪化春来，说不出的娇美动人。NOR]],["time"]=13,["title"]=[[HIW江湖三友NOR]]},["136"]={["id"]=136,["introText"]=[[WHT记载着醉八仙棍法武功的书页，此为第一篇。NOR]],["itemId"]=[[shuye12]],["name"]=[[醉八仙棍法残篇之一]],["need"]=3,["pic"]=[[Image/UI/StoreUI/canye.png]],["thankText"]=[[YEL满月临弓影，连星入剑端。
