待到浓雾散去，你蓦然发现，手上的珍品券已经变成了一份残篇，令你错愕不已。NOR]],["time"]=13},["137"]={["id"]=137,["introText"]=[[WHT记载着醉八仙棍法武功的书页，此为第二篇。NOR]],["itemId"]=[[shuye13]],["name"]=[[醉八仙棍法残篇之二]],["need"]=3,["pic"]=[[Image/UI/StoreUI/canye.png]],["thankText"]=[[YEL满月临弓影，连星入剑端。
