待到浓雾散去，你蓦然发现，手上的珍品券已经变成了一本泛黄的武学秘籍，令你错愕不已。NOR]],["time"]=14,["title"]=[[全篇]]},["148"]={["id"]=148,["introText"]=[[WHT她就是貂蝉。她玉骨冰肌，顾盼媚流，一袭鲜红舞衣，凤鸾飞绣，玉珠垂髻，只衬得她面若桃花，于烛曳摇光间尽显风姿灼华。世闻，纵盈光皎月，仙宫美娥，亦不足她倾城一笑。NOR]],["itemId"]=[[mianju1115]],["name"]=[[HIB貂蝉NOR]],["need"]=10,["pic"]=[[Image/UI/AttrUI/mianju/diaochan.png]],["thankText"]=[[YEL你将拜帖递进一座江南宅院的正门，随即被一位垂髫女童引进院内凉亭，见花摇树影间的石桌旁坐着一素手调琴的美人，生得肌白赛雪，一袭红衫似红梅映月，果然是倾城绝色。
传闻当年貂蝉受主家王允所托，为护汉室江山以身作饵周旋于董卓与吕布之间，后来奸臣董卓被灭，吕布亦成三家姓奴令天下人耻笑，不得善终，而貂蝉从此消失，没想到竟是在这隐居。
她许久不接待生人，与你相见时脸颊飞红一片，以袖掩面，露出的美目波光流转。
看着这样一双妩媚动人的眼睛，无论男女皆会受之蛊惑。只听她声音婉转如莺啼，笑言：“若不嫌弃，貂蝉有一曲献给少侠。”
说罢，她双指在琴弦上翩飞，世闻其舞月见羞，原来美人弹琴也如仙宫之乐，令你痴醉不已。NOR]],["time"]=14,["title"]=[[月见羞]]},["149"]={["id"]=149,["introText"]=[[WHT他就是陆千侯。他身姿挺拔如苍松，气势刚健似骄阳，剑眉之下目光如炬，不怒自威，令人不敢与之直视。NOR]],["itemId"]=[[mianju1071]],["name"]=[[YEL陆千侯NOR]],["need"]=15,["pic"]=[[Image/UI/AttrUI/mianju/luqianhou.png]],["thankText"]=[[YEL你的拜帖刚递进陆府，便有崇武卫为你带路，绕过花园的山石，走进一处练兵室，大名鼎鼎的陆统领正身着短打与几位手下切磋，他同时战数人，依然稳居上风。
见到你来，他严肃的脸上露出一丝笑意，招手邀请道：“少侠可有兴趣和我比试？”
你刚点头应允，岂料一道掌风忽然迎面而至，令你险些狼狈摔倒，陆千侯见之笑说：“我这招叫兵不厌诈。”
这一出瞬间点燃你的胜负欲，摆好架势跃入场中央与他交手，你们二人打得威猛生风，掀得近身处连尘埃也不曾瞧见，周围人远远避开，不断为你们叫好。
酣战方休，你受益匪浅，而陆千侯看着你的目光充满欣赏之情，留你用完晚饭后亲自送你出门，直约下次再战。NOR]],["time"]=14,["title"]=[[PNK陆大统领NOR]]},["15"]={["id"]=15,["introText"]=[[这是多年前一位名震江湖的大侠所创的独门气功，运功时以内力激荡周身空气产生震动，功力精深者进可破气攻敌退可驭气闪躲。]],["itemId"]=[[wuhenjinbox2]],["name"]=[[    HIY无痕劲NOR]],["need"]=10,["pic"]=[[Image/UI/StoreUI/shujuan3.png]],["thankText"]=[[YEL满月临弓影，连星入剑端。
不学燕丹客，徒歌易水寒。
你沉吟不语，将珍品券捧于手上，似在心中思索着什么。
须臾间，空中一股浓雾飘散而来，遮蔽了你的视线。
待到浓雾散去，你蓦然发现，手上的珍品券已经变成了一本泛黄的武学秘籍，令你错愕不已。NOR]],["time"]=3,["title"]=[[全篇]]},["150"]={["id"]=150,["introText"]=[[WHT她就是师太。她面似寒霜、不苟言笑，横眉之下眸光清冷，虽双颊微红却不染俗世脂粉，一举一动足显大家风范，无半点媚态，可敬可畏。NOR]],["itemId"]=[[mianju1080]],["name"]=[[HIB师太NOR]],["need"]=6,["pic"]=[[Image/UI/AttrUI/mianju/miejue.png]],["thankText"]=[[YEL据传峨眉山上有一处峰顶终年积雪，风霜如刀刺骨，非常人能往。你递上拜帖，依此凭证进入该地，天地一片白茫的寒气中，一道人影坐在万丈边悬崖边盘腿打坐。
听到脚步声响，她倏然睁开双眼，眸光似两道寒芒向你疾射而来，你立即行礼以晚辈自称，她放缓神色，邀你在此练功，试一试这冰霜险境的威力。
你随即打坐入定，运全身内力抵御寒气入侵，同时抛开杂思保持心如止水，以免不慎坠入悬崖。
你打坐一日，仿佛渡过几年光阴，练功结束后直叹：能面不改色日日这般苦练，前辈实乃意志坚定之人。
你心生佩服，亦有所获，向她答谢后下山，天晚寒意更浓，那道立在山尖风雪里的身影浑然如玉石所铸。NOR]],["time"]=14,["title"]=[[峨眉执剑]]},["151"]={["id"]=151,["introText"]=[[WHT她就是惊鸿燕。她古灵精怪，活泼可人。头上秀发以红绸系成两个髻，身穿黑色劲装，性子颇似男子，身手矫健，常年出没于古墓之中。NOR]],["itemId"]=[[mianju1119]],["name"]=[[PNK惊鸿燕NOR]],["need"]=3,["pic"]=[[Image/UI/AttrUI/mianju/jinghongyan.png]],["thankText"]=[[YEL惊鸿燕忽然现身抽走你的拜帖，施展轻功如兔起鹘落消失在远处，只留下银铃般的笑声，“少侠想找我谈话，等你追上我再说。”
待你将人从某个犄角阴影里揪出，她满脸不可思议，叉腰抱怨道：“你……你为何每次都能轻易找到我。”
想她一个常年出没于古墓之中，靠轻功绝活保身的人，怎么遇到你就像遇到克星呢，干脆不理你好了。
她心里这般想，嘴上不由嘀咕出来，你听见后微微一笑，一边往前走一边道：“哎，本来想请某人去醉香楼吃名厨大餐，看来是没机会咯。”
后面轻快的脚步声跟上来，一只白皙小手拍上你的肩膀，“哼，谁说我不吃，今天吃空你的钱袋！”
你哈哈大笑，她被你笑得羞恼，追着你打，二人嬉笑玩闹，直往醉香楼而去。NOR]],["time"]=14,["title"]=[[江湖三友（三）]]},["152"]={["id"]=152,["introText"]=[[WHT这就是仲秋长靴。这是一双绒布长靴，靴面呈暗青色，内里则缝了一层白色绒布。NOR]],["itemId"]=[[2020zqlq06]],["name"]=[[HIR仲秋长靴NOR]],["need"]=2,["pic"]=[[Image/UI/StoreUI/wuqi.png]],["thankText"]=[[YEL三尺龙泉剑，匣里无人见。
