待到浓雾散去，你蓦然发现，你的手上竟多了一件宝光四射的装备，而那张珍品券早已不知所踪。NOR]],["time"]=14,["title"]=[[HIW珍品装备NOR]]},["153"]={["id"]=153,["introText"]=[[WHT这就是长天腰带。这是一条灰白色的牛皮腰带，以上等小牛皮漂白而成。韧性十足，结实耐用。NOR]],["itemId"]=[[2020zqlq07]],["name"]=[[HIC长天腰带NOR]],["need"]=2,["pic"]=[[Image/UI/StoreUI/wuqi.png]],["thankText"]=[[YEL三尺龙泉剑，匣里无人见。
