待到浓雾散去，你蓦然发现，手上的珍品券已经变成了一本泛黄的武学秘籍，令你错愕不已。NOR]],["time"]=15,["title"]=[[全篇]]},["161"]={["id"]=161,["introText"]=[[WHT耳朵也尖尖，琼鼻也尖尖。灰白色的毛发比绸缎还要柔顺，圆圆的肚皮比坐垫还要柔软，乖巧巧地静坐在花枝下，似要学那猛虎细嗅蔷薇的花香。NOR]],["itemId"]=[[mianju1156]],["name"]=[[PNK狸奴入梦NOR]],["need"]=21,["pic"]=[[Image/UI/AttrUI/mianju/linu1.png]],["thankText"]=[[YEL你将珍品券递上，忽听几声喵喵直叫，低头望去，脚边竟站着一只灰头白肚的猫儿，正对着你的脚踝磨来蹭去，细长的尾巴卷起来，轻轻地拍打在你的腿肚子上，似乎在指引你往里走。
你随着猫儿向巷子里走了十余步，忽而间猫儿一钻便不见了身影，从巷子内缓缓走出一个手捧书卷的俏姑娘，眼波婉转凝望着你，文静而端庄。
你与姑娘从天上到地下，无所不谈，相谈甚欢。一只猫儿引你识得这红颜知音，只觉是缘分，只道是神奇。不知不觉，你们二人在巷子里谈到月上眉梢，夜色渐浓。NOR]],["time"]=15,["title"]=[[YEL狸奴入梦NOR]]},["162"]={["id"]=162,["introText"]=[[WHT他就是幽冥教主，传闻他武功极高，曾与唐家唐不平交手三百回合不落下风。他面如冠玉，眉宇间英气十足，不怒自威，举手投足之间散发着一股慵懒之意。传言说其本是女儿身，但对外宣称为男人，以便行走江湖，统治帮派。NOR]],["itemId"]=[[mianju1099]],["name"]=[[HIM幽冥教主NOR]],["need"]=20,["pic"]=[[Image/UI/AttrUI/mianju/youmingjiaozhu1.png]],["thankText"]=[[YEL珍品券刚一递上，蓦然间你只听见一声低沉地耳语：“随我来。”声音如冷冽的寒潭，却让人分辨不出男女。你只觉腰间肋下被人裹挟住，随后身子一轻，整个人竟然腾空而起，向着某个方向凌空飞去。

迷迷糊糊间，你身后之人托着你飘然落地，你睁眼一看，竟来到一座阴森死寂的佛殿之中，殿中左右两侧各站着五尊巨大佛像，正是十殿阎罗王。

“无常善勾恶人命，七宝可避万般劫。既然少侠愿投拜帖于本座，本座便与少侠说一说这十殿阎罗的故事。”冷冽的声音从你背后响起，将每位阎罗的故事娓娓道来。

你虽然觉得有些惊怕，但却沉浸在这些鲜为人知的故事中，直至东方之际白。NOR]],["time"]=15,["title"]=[[MAG十殿阎罗NOR]]},["163"]={["id"]=163,["introText"]=[[WHT她就是丁香。她秀丽绝俗，身姿丰盈，樱桃小口灵巧端正，双眸清亮，坚毅的眼神中带着一丝勇往直前的锐利，偶尔也会露出狡黠之光，展现清纯活泼一面，叫人心生喜爱，又痴又叹。NOR]],["itemId"]=[[mianju1118]],["name"]=[[MAG丁香NOR]],["need"]=19,["pic"]=[[Image/UI/AttrUI/mianju/dingxiang1.png]],["thankText"]=[[YEL你刚将珍品券递上，便走出一名女弟子，向你作了一揖道：“四师姐让我带你过去，请随我来。”
你与女弟子走到一处山崖边，一位秀丽绝俗，身姿丰盈的女子正在此习武。虽只是基础的招式，但女子不曾有丝毫怠慢，整个人沉稳、坚毅，还带有一丝勇往无前的锐利。你与她一起讨论武学，期间还比试了一番，待日暮时分正准备告辞离开时，女子忽然开口道：“山下镇子的夜市热闹得很，不如一起去逛逛？”
夜市灯火通明，人影攒动，果真热闹非凡。女子换了一套蓝色的衣裙，头戴狐狸面具，手拿一根糖葫芦穿行在摊贩间。双眸清亮如星，樱桃小口未曾停下过，似黄鹂一般，清纯活泼，叫人心生喜爱。NOR]],["time"]=15,["title"]=[[PNK江湖三友NOR]]},["164"]={["id"]=164,["introText"]=[[WHT他就是风流盗帅。他生得灵俊秀美，形神飘逸，手拿折扇，风流倜傥。NOR]],["itemId"]=[[mianju1045]],["name"]=[[HIC风流盗帅NOR]],["need"]=5,["pic"]=[[Image/UI/AttrUI/mianju/chuliuxiang.png]],["thankText"]=[[YEL你将珍品券递上，门前便走出一位手持折扇、英俊潇洒的公子，对你微微一笑，拉着你便往宅子内走去。
公子与你走到一座流水庭院，席地而坐，合起宝扇一抚掌，便有数位绫罗锦织的女子，手中捧着果盘款款走来，将数枚精致的果盘放到你们面前。你二人赏着这美景与蔬果，听着这流水与莺歌，不知不觉便有些乏了。
见你困乏，公子随手提来一盏香炉，将香炉置于身边，也无讲究，与你就地而眠。酣然入梦，一夜好眠，直至第二日天亮，你二人方才悠然而起。NOR]],["time"]=15,["title"]=[[CYN偷心盗帅NOR]]},["165"]={["id"]=165,["introText"]=[[WHT这就是方口尖头履。用绑带缚于脚背和足踝，鞋的前端成尖角形。后端成平直形，周围留有宽边。用织锦或皮革缝制而成。NOR]],["itemId"]=[[20cyqreq6]],["name"]=[[WHT方口尖头履NOR]],["need"]=2,["pic"]=[[Image/UI/StoreUI/wuqi.png]],["thankText"]=[[YEL三尺龙泉剑，匣里无人见。
