须臾间，空中一股浓雾飘散而来，遮蔽了你的视线。
待到浓雾散去，你蓦然发现，手上的珍品券已经变成了一本泛黄的武学秘籍，令你错愕不已。NOR]],["time"]=16,["title"]=[[全篇]]},["175"]={["id"]=175,["introText"]=[[WHT他就是司徒迟。他容貌俊美，一双眼尾上扬的凤眼隐约给人阴寒之感，腰间挂有的骨笛据说用其至亲手骨所造，他右手尾指为断指，兼之一身毒术，让人倍觉诡异邪性。NOR]],["itemId"]=[[mianju1112]],["name"]=[[HIM司徒迟NOR]],["need"]=20,["pic"]=[[Image/UI/AttrUI/mianju/situchi.png]],["thankText"]=[[YEL你递入拜帖，很快有弟子为你带路。

周围草木阴森，鸩阁面传出毒虫悉索的响动，不时穿插几声渗人的惨叫。

司徒迟推开虚掩的门，从暗黑屋子里走到外面的台阶，随意用袖子擦去手上的血迹，双眼眸光清冷，“当初《武穆遗书》一事，有些问题还请少侠告知。”

接下来他句句直言，特别是对任天南的举止揣测颇深，二人显然结怨已久。

你无意卷入他们的纷争，不一会提出告辞，快要走出此地时，你听到后方隐约的笛音，阴邪凄寒中竟带着一些空无的寂寥。
NOR]],["time"]=16,["title"]=[[MAG指骨为笛NOR]]},["176"]={["id"]=176,["introText"]=[[WHT她就是无悔妹妹。她肤嫩如雪，眉眼如画。水蓝色的发饰，淡红色的束带，衬上一头栗色的长发。柔情无限，眼波盈盈，羞红的脸上挂着浅笑，贝齿轻咬着发带，只觉分外可爱。NOR]],["itemId"]=[[mianju1138]],["name"]=[[PNK无悔妹妹NOR]],["need"]=15,["pic"]=[[Image/UI/AttrUI/mianju/buhuimeimei.png]],["thankText"]=[[YEL跛足小鬟接过你的拜帖，嘶声道：“小姐人在前面。”

花园中，一位娉娉袅袅的少女足点花心，穿梭彩蝶间扑蝶，回眸多娇，“少侠快来帮我。”

你施展轻功，将飞舞的蝴蝶赶入蝶网，不知为何，她又将蝴蝶放出，神色黯然地邀你一起坐在石桌边，“爹最近愁眉苦脸，可我却帮不了他什么，也不便出去玩耍。”
你见她面带愁容，便与她说起江湖上的趣事，终于令她露出笑颜，待天色昏暗，你提出告辞，走出一段距离后，似有所感地回头一望，只见她手扶圆供门侧，仍在依依不舍地目送你。NOR]],["time"]=16,["title"]=[[PNK此情无悔NOR]]},["177"]={["id"]=177,["introText"]=[[WHT她就是落英女侠。何彼秾矣，华如桃李。一双脉脉含情的眼眸，一条缀满铜铃的发带，一件艳红明丽的衣裳，好似一位身着嫁衣的女子，正在翘首盼望意中人的到来。NOR]],["itemId"]=[[mianju1137]],["name"]=[[RED落英女侠NOR]],["need"]=14,["pic"]=[[Image/UI/AttrUI/mianju/chaoyingnvxia.png]],["thankText"]=[[YEL你通过拜帖进到终南山山顶，梅林间一红衣女子正在月下用指拭剑。

“久闻少侠大名，可有兴趣和我比划几招？”

你知前辈武功高深，有心见识一番，故而欣然应允。

比试中，她剑影如蛟龙戏水，又有百般变化，你一招刚起，她破解之法顷刻随出，游刃有余，简直毫无破绽。

你越发心惊，但更觉佩服，结束后向前辈郑重施了一礼，她嫣然笑道：“我该好好谢你才是。”

你尚且不解，只听她笑声畅快，“我正在创一套克制全真武功的剑法，遇到几处难点，和你切磋完竟有了些眉目，少侠觉得我这剑法能否大成？”

练一番惊世武功已是难事，何况自创，但你见她眸光烨烨，那般神采飞扬，不由肯定地点头。NOR]],["time"]=16,["title"]=[[MAG古陵深情NOR]]},["178"]={["id"]=178,["introText"]=[[WHT他就是凌云。他气宇轩昂，谦和有礼，为人处世时皆秉公执法，不苟言笑。一身的官服将他紧紧束缚，但这种束缚不过是求仁得仁，他心甘为民，若然揭去铁面，亦是一个普通的江湖人。NOR]],["itemId"]=[[mianju1095]],["name"]=[[HIY凌云NOR]],["need"]=5,["pic"]=[[Image/UI/AttrUI/mianju/linyun.png]],["thankText"]=[[YEL衙门的捕快接下你的拜帖，告知你凌捕头不在，去了附近东街办案。

你走到那里，正瞧见两位公子在路边激烈争持，俱称对方为偷自己玉佩的贼。

大正午天干燥热，行人寥寥，凌云虽是表情冷峻，却极有耐心听他二人自辩。

看到你后，他略有歉意指着旁边茶摊要你稍候片刻，待解决这事，他方带着一身薄汗坐你对面。

你直言常见他追查江湖大案，凌云之名武林人皆知，想不到还会管这些小事。

对此话他面带严肃地摇头：“我等办案皆为百姓，只要百姓有需要，何来大小之分。”

你顿时敬佩之情油然而生，没一会又出现新的案子，他起身告辞，来去匆匆，仿佛风雨难阻。
NOR]],["time"]=16,["title"]=[[HIW铁面无私NOR]]},["179"]={["id"]=179,["introText"]=[[WHT这就是白羽长裤。华丽雪白的长裤，似乎是用白鹅的羽绒制成的。寒风中白羽猎猎，能将冷冽的寒气阻挡在外。NOR]],["itemId"]=[[20ldeq4]],["name"]=[[HIG白羽长裤NOR]],["need"]=2,["pic"]=[[Image/UI/StoreUI/wuqi.png]],["thankText"]=[[YEL三尺龙泉剑，匣里无人见。
一张落雁弓，百支金花箭。
你沉吟不语，将珍品券捧于手上，似在心中思索着什么。
须臾间，空中一股浓雾飘散而来，遮蔽了你的视线。
待到浓雾散去，你蓦然发现，你的手上竟多了一件宝光四射的装备，而那张珍品券早已不知所踪。NOR]],["time"]=16,["title"]=[[HIW珍品装备NOR]]},["18"]={["id"]=18,["introText"]=[[WHT他就是令狐掌门。他长方脸蛋，剑眉薄唇，此时抱剑而立，尽显豪侠之气。NOR]],["itemId"]=[[mianju1047]],["name"]=[[YEL令狐掌门NOR]],["need"]=20,["pic"]=[[Image/UI/AttrUI/mianju/linghuzhangmen.png]],["thankText"]=[[YEL珍品券刚一送上，大门登时被人推开，走出一位步履飘逸，举止潇洒的英俊男子。男子爽朗一笑，向你说了句：“来吧！少侠！”

你随男子进到后院，不料此院竟然建在高山峰顶之上，四周云雾缭绕，劲风猎猎作响，真乃人间仙境。只见男子拔剑一挑，一坛美酒便从架子上一跃而起，钻入你怀中。待你错愕之时，男子出剑再挑，又将一坛美酒挑起，稳稳落到剑尖之上。只听男子爽朗一笑：“少侠，请！”却不知他如何破开泥封，竟舞剑而饮。

剑出游龙，剑尖美酒分毫不差落入男子口中，惹得你拍案叫绝，只得也拍开泥封，二人一醉方休，不知东方之既白。]],["time"]=3,["title"]=[[PNK独孤笑傲NOR]]},["180"]={["id"]=180,["introText"]=[[WHT这就是云雪。乱云低薄暮，急雪舞回风。这条坠链上嵌着一颗白色迷蒙的宝石：似水晶，似琥珀，似浮云，又似飞雪。NOR]],["itemId"]=[[20ldeq5]],["name"]=[[HIG云雪NOR]],["need"]=2,["pic"]=[[Image/UI/StoreUI/wuqi.png]],["thankText"]=[[YEL三尺龙泉剑，匣里无人见。
一张落雁弓，百支金花箭。
你沉吟不语，将珍品券捧于手上，似在心中思索着什么。
