待到浓雾散去，你蓦然发现，你的手上竟多了一件宝光四射的装备，而那张珍品券早已不知所踪。NOR]],["time"]=16,["title"]=[[HIW珍品装备NOR]]},["181"]={["id"]=181,["introText"]=[[WHT这就是飞雪。人生到处知何似，应似飞鸿踏雪泥。这双鞋底部用蓝白色丝线绣着云纹，底薄而柔软，正应了那句踏雪无痕。NOR]],["itemId"]=[[20ldeq6]],["name"]=[[HIG飞雪NOR]],["need"]=2,["pic"]=[[Image/UI/StoreUI/wuqi.png]],["thankText"]=[[YEL三尺龙泉剑，匣里无人见。
