此后更是平定神龙岛，妙取罗刹国，最终携七位美貌妻子，归隐于市。NOR]],["itemId"]=[[mianju1131]],["name"]=[[HIY韦爵爷NOR]],["need"]=15,["pic"]=[[Image/UI/AttrUI/mianju/weijueye.png]],["thankText"]=[[YEL珍品券刚送入不久，便见七位美妇款款走来。七位美妇姿容各异，好似天上的七位仙女，一时间只觉群芳争艳，香气扑鼻。见你略有呆滞，其中一位妇人轻声唤你：“爵爷正在厅内等候多时，少侠莫要让爵爷久等了，快请进来吧。”

你跟着七位美妇走进一间华贵的客厅，客厅内古董字画琳琅满目，而一位奇装异服的男子正坐在上首，你知道，此人便是韦爵爷了。

韦爵爷翘着二郎腿，歪歪斜斜靠在椅子上，嘴角露出坏笑，目视你入座后，拍着扶手问道：“少侠，我的夫人们可是各个貌美如花？”

你大笑三声，与他谈论起江湖中遇到的各个美女佳人，他听得拍手叫好，却被几位夫人醋意大发，一顿粉拳伺候。

一夜尽兴闲谈，聊得你口干舌燥方才告辞离去。NOR]],["time"]=3,["title"]=[[HIW小白龙NOR]]},["190"]={["id"]=190,["introText"]=[[HIW这是一门暗器武学，手法和行功方式自成一家，据说由一位出自南少林的传奇盲僧所创。NOR]],["itemId"]=[[tingfengjing]],["name"]=[[BLU听风经NOR]],["need"]=5,["pic"]=[[Image/UI/StoreUI/shujuan5.png]],["thankText"]=[[YEL满月临弓影，连星入剑端。
不学燕丹客，徒歌易水寒。
你沉吟不语，将珍品券捧于手上，似在心中思索着什么。
须臾间，空中一股浓雾飘散而来，遮蔽了你的视线。
待到浓雾散去，你蓦然发现，手上的珍品券已经变成了一本泛黄的武学秘籍，令你错愕不已。NOR]],["time"]=17,["title"]=[[全篇]]},["191"]={["id"]=191,["introText"]=[[WHT她就是越女青青。身如翠竹，弱质芊芊。长着一张标致的瓜子脸蛋，前额上的乱发被青丝带束起，手持一根莹莹竹棍，瞳孔中散发出令人心惊的幽绿。NOR]],["itemId"]=[[mianju1132]],["name"]=[[RED越女青青NOR]],["need"]=20,["pic"]=[[Image/UI/AttrUI/mianju/yuenv.png]],["thankText"]=[[YEL你拿着拜帖，寻遍山林，终于在山林深处溪边的羊群中，看到了那道青色的身影。

也许是脚步声暴露了你的行踪，青青朝你的方向看来。

你不自主地与她对视，她的双眸青幽却又纯粹，令你沉醉。

一时间你竟忘了来意，半天没有说出一句话来。

她巧然一笑，随即唱起了牧羊的歌谣，手中挥舞着竹棒，赶着羊群朝远方走去。

待你回过神来，她与羊儿们的身影早与你手中的拜帖一般消失不见。

一切恍若梦中，似真似幻。
NOR]],["time"]=17,["title"]=[[MAG越女剑NOR]]},["192"]={["id"]=192,["introText"]=[[WHT她就是素素。明媚清丽，娇艳绝伦，目光直视远方，饱含决然之色，闭眼时，泪珠滚落，似雨后梨花，凄美断人肠。NOR]],["itemId"]=[[mianju1134]],["name"]=[[PNK素素NOR]],["need"]=15,["pic"]=[[Image/UI/AttrUI/mianju/susu.png]],["thankText"]=[[YEL你递上拜帖，登上武当，在解剑岩畔等了许久，方才等到了她。

她双眼通红，眼角犹有泪痕，梨花带雨，娇艳动人。但她此刻似乎心有挂碍，背过身去看向武当山顶。

瞧了她的模样，你心下一阵尴尬，想开口询问缘由却又觉得唐突。

山中幽静，不多时，你听到了一阵啜泣声。

几番考量，你叹了口气，双手抱拳，向素素辞别。

离开之际，背后传来几不可闻的女声，“舍生取义，生死相随。”

回头再看，素素的身影几个起落，消失在武当的幽深山道中。NOR]],["time"]=17,["title"]=[[PNK至情至性NOR]]},["193"]={["id"]=193,["introText"]=[[WHT他就是凌云。眉如利剑、面似白雪。眉心中一点剑痕，眼神明亮深邃却暗藏孤寂。剑刃握于手中，剑华流转不息，剑芒吞吐不定。试问何为剑客之心？原是一曲寂寞之情。NOR]],["itemId"]=[[mianju1136]],["name"]=[[HIM剑神NOR]],["need"]=14,["pic"]=[[Image/UI/AttrUI/mianju/jianshen.png]],["thankText"]=[[YEL你递上拜帖，走进庭院，四下张望，试图找到那个男人。

今天的你似乎运气不错，很快的，你在树下找到了自饮自酌的他。

你毫不客气在他对面坐下，目光灼灼地看向了他。

“今日，不比剑。”他一杯饮尽，缓缓起身，眼神平静似乎又带有一丝落寞。

你正想开口说些什么，却看见他骤然向庭中出剑，寒芒几闪，长剑归鞘。

“我期待日能后与你一较高下。”他不再说话，转身离开。

你望着地上硕大的一个“剑”字刻痕，默然不语。许久，你抓起座上的酒壶一把饮尽，胸中战意如炽。

你下定决心，起身离去。NOR]],["time"]=17,["title"]=[[MAG落花吹雪NOR]]},["194"]={["id"]=194,["introText"]=[[WHT她就是素素。娇俏可人，梳一头双垂髻，簪戴花饰，红裙相衬间，若百花之灵，人言以花为媒，可缔美好姻缘，故她迎奉花神，手持姻缘簿，于一颦一笑间指点着世间姻缘。NOR]],["itemId"]=[[mianju1114]],["name"]=[[HIM红娘NOR]],["need"]=9,["pic"]=[[Image/UI/AttrUI/mianju/hongniang.png]],["thankText"]=[[YEL你站在红娘庄大门前，排队等了许久，方才见到了忙得不可开交的小红娘。

“咦？怎么只有你一个，你的心上人呢？”小红娘见你独身一人，甚是诧异。

你一头黑线，忙不迭将手中的拜帖向小红娘递去。

“原来是这样啊。”小红娘噗嗤一笑，“接下来这半天，你就跟我一起当媒人吧。”你推脱不过，只能答应下来。

半天下来，新郎新娘在你和小红娘的撮合下喜结连理，永结同好，看着他们幸福的模样，你心中似乎掀起了一丝波澜。

离别之际，小红娘悄悄地在你的手上缠了一根红线，“千里姻缘一线牵，你也会像他们一样幸福的。”NOR]],["time"]=17,["title"]=[[HIW如花美眷NOR]]},["195"]={["id"]=195,["introText"]=[[WHT这就是归巢帽。一顶黑色圆帽，上有六条锦带从帽顶散落，各锦带之间均以金丝绣出一只归燕。NOR]],["itemId"]=[[2020zhounian01]],["name"]=[[HIY归巢帽NOR]],["need"]=2,["pic"]=[[Image/UI/StoreUI/wuqi.png]],["thankText"]=[[YEL三尺龙泉剑，匣里无人见。
