你随两位蒙面男子进入偏殿之中，只见殿中站着一位姿容艳丽，秀丽绝伦的女子。女子轻轻一拂手，道了一声：“出去吧。”两位蒙面男子便毕恭毕敬地退出殿外。

见场中除你二人外并无他人，女子掏出一杆碧绿洞箫，放在唇边轻轻吹奏。十指如兰花飞扬，曲调随之而变化，音律传入耳中，刹那间你只觉滔滔江水滚滚而来，忽高忽低，忽快忽慢，片刻后蓦然一收，仿佛天地风雨尽数散去，令你久久不能平息。]],["time"]=3,["title"]=[[YEL日月圣女NOR]]},["200"]={["id"]=200,["introText"]=[[WHT这是一颗天工石,可以用于提升装饰箱的容量。NOR]],["itemId"]=[[tiangongshi1]],["name"]=[[天工石]],["need"]=2,["pic"]=[[Image/UI/StoreUI/zhuzi.png]],["thankText"]=[[YEL赤点朱饰韵味飘远,真才天工赏心悦目。
