待到浓雾散去，你蓦然发现，地上竟摆着一块天工石，令你错愕不已。NOR]],["time"]=17,["title"]=[[HIW珍品道具NOR]]},["201"]={["id"]=201,["introText"]=[[WHT这是散人顶级残页，可开出散人顶级残页。NOR]],["itemId"]=[[sanren8]],["name"]=[[散人顶级残页]],["need"]=1,["pic"]=[[Image/UI/StoreUI/canye.png]],["thankText"]=[[YEL满月临弓影，连星入剑端。
