待到浓雾散去，你蓦然发现，手上的珍品券已经变成了一本泛黄的武学秘籍，令你错愕不已。NOR]],["time"]=18,["title"]=[[全篇]]},["204"]={["id"]=204,["introText"]=[[HIW据说为一双手残废的世外高人所创。那高手不得习掌，遂精研腿法，终成大器。此路腿法以刚猛为主，使用时需以极强内力为辅。NOR]],["itemId"]=[[jiutianxianglongtui]],["name"]=[[BLU九天翔龙腿NOR]],["need"]=18,["pic"]=[[Image/UI/StoreUI/shujuan3.png]],["thankText"]=[[YEL满月临弓影，连星入剑端。
