待到浓雾散去，你蓦然发现，手上的珍品券已经变成了一本泛黄的武学秘籍，令你错愕不已。NOR]],["time"]=18,["title"]=[[全篇]]},["205"]={["id"]=205,["introText"]=[[HIW一种特殊的轻功身法，据说是唐玄宗时一位隐姓埋名的梨园伶人所创。NOR]],["itemId"]=[[huaxuyinbox]],["name"]=[[PNK华胥引NOR]],["need"]=7,["pic"]=[[Image/UI/StoreUI/shujuan4.png]],["thankText"]=[[YEL满月临弓影，连星入剑端。
不学燕丹客，徒歌易水寒。
你沉吟不语，将珍品券捧于手上，似在心中思索着什么。
须臾间，空中一股浓雾飘散而来，遮蔽了你的视线。
待到浓雾散去，你蓦然发现，手上的珍品券已经变成了一本泛黄的武学秘籍，令你错愕不已。NOR]],["time"]=18,["title"]=[[全篇]]},["206"]={["id"]=206,["introText"]=[[WHT他就是赵武德。他生得身形挺拔，左颊一条刀疤，衬得眉目愈发粗犷，怀中抱着的长剑似乎刻满了久经江湖的沧桑之感。NOR]],["itemId"]=[[mianju1083]],["name"]=[[YEL赵武德NOR]],["need"]=24,["pic"]=[[Image/UI/AttrUI/mianju/zhaowude.png]],["thankText"]=[[YEL你将珍品券递上，片刻后出来一位高大威猛，身形挺拔的男子，他左颊一条刀疤，衬得眉目愈发粗犷。男子豪气一笑，叫你随他去。

你随着男子来到一处亭子，这亭子居然建在悬崖边上，涯边凛风呼啸，亭边仅有怪石嶙峋，全然一副萧杀之意。男子不知从何处掏出两壶好酒，将一壶扔予你，自己开了一壶，猛灌了一大口后，向你道：“倒是没想到你会来看我，今日我们不谈其他，只一醉方休！”

你们在涯边亭中开怀畅饮，确是不醉不归，直至繁星满天才有几名小厮前来将你们扶回各自房中休息。NOR]],["time"]=18,["title"]=[[HIR剑底亡魂NOR]]},["207"]={["id"]=207,["introText"]=[[WHT她就是戎装公主。风姿绰约，仪态万方，头束金冠，身披玄甲，本为一朝公主，长枪在手却不让须眉，当真称得上英姿飒爽，绝代风华，有诗云：一别深宫罢红妆，风飞扬，耀荣光。NOR]],["itemId"]=[[mianju1092]],["name"]=[[HIM戎装公主NOR]],["need"]=15,["pic"]=[[Image/UI/AttrUI/mianju/rongzhuanggongzhu.png]],["thankText"]=[[YEL月上梢头，习武场上却仍有一道身影在执着地练习着枪法。

红缨抖动，枪影如龙。你仔细观察了盏茶的时间，发现那人的身形瘦削，脚步虚浮，而且招式衔接略显生疏，显然那人并非勤习武艺也非久经沙场之人。

正在你疑惑之际，场上那人似乎也发现了你的踪迹。

“你还打算看上多久？”声若黄莺，场上之人竟然是个女子。

你走上跟前，递上拜帖，女子接过时，顺手将遮面面具揭下。眉目如画，却有雍容气度，你忽而想起坊间所传的公主入伍一事。

“女子就不可以上战场吗？”她似乎猜出了你心中所想，也不待你回答，便一枪向你刺来。只是枪速稍缓，明显给了你反应的时间。你心下明悟，当下运起兵器，与她斗作一团。NOR]],["time"]=18,["title"]=[[MAG戎装公主NOR]]},["208"]={["id"]=208,["introText"]=[[WHT他就是神教教主。他风华绝代，烟视媚行，慵懒雍容中又有几分伟男子的英气，让人一见难忘。NOR]],["itemId"]=[[mianju1053]],["name"]=[[RED神教教主NOR]],["need"]=9,["pic"]=[[Image/UI/AttrUI/mianju/dongfangbubai.png]],["thankText"]=[[YEL你将珍品券递上，片刻后走出两位长袖青衫，黑纱蒙面的男子，向你拱手道：“教主有请！”

你随两位蒙面男子进入殿内，殿内宝座上正坐有一人，那人一身红衣，风华绝代，慵懒雍容之中又带有几分飒爽英姿，叫人一见难忘。他无需言语，只一抬眼，两位蒙面男子便心领神会的带你入座，端上美酒佳肴后就自行退下。

那人斜躺于宝座上，左手拿着一个绣花绷架，右手持着一枚绣花针，手指灵巧的运针引线。炎炎夏日，蚊虫纷扰，就在你们闲聊之间，飞来了一只苍蝇嗡嗡地扰人。你还未有所反应，只见银光一闪，那苍蝇便被一枚绣花针钉在柱上。转眼望去，他仍在穿针引线，似乎从未变过，你不由得赞叹其武功之高绝。NOR]],["time"]=18,["title"]=[[YEL神教教主NOR]]},["209"]={["id"]=209,["introText"]=[[WHT她就是姑射龙女。生得清丽秀雅，白衣飘然，手持一柄乌黑长剑，风姿绝代。NOR]],["itemId"]=[[mianju1050]],["name"]=[[BLU姑射龙女NOR]],["need"]=8,["pic"]=[[Image/UI/AttrUI/mianju/nianqinglongnv.png]],["thankText"]=[[YEL终南山下，古陵幽深。

白繁霜执着你的拜帖，领着你朝古陵深处走去。古陵本就清幽，深处更是带上几分阴冷，与外界大相径庭。你略感不适之余，也不禁心生好奇，到底会是什么样的人才能久居于此。

很快，你便得到了你想要的答案。她一身缟素，容颜绝美，但神色清冷尤胜这古陵。她柳眉微蹙，似乎另有心事，只是与你匆匆会面，便又让白繁霜领着你离开了她的居所。

白繁霜深谙龙姑娘的脾性，向你告罪后，便领着你在古墓中四处游玩起来。寒潭钓鱼、采蜂蜜、捉麻雀，游玩下来倒也别有一番趣味。NOR]],["time"]=18,["title"]=[[PNK古陵传人NOR]]},["21"]={["id"]=21,["introText"]=[[WHT她就是龙女侠。她清丽秀雅，白衣飘然，手持一柄乌黑长剑，风姿绝代。NOR]],["itemId"]=[[mianju1050]],["name"]=[[HIB龙女侠NOR]],["need"]=6,["pic"]=[[Image/UI/AttrUI/mianju/nianqinglongnv.png]],["thankText"]=[[YEL你将珍品券递上，许久后，沉重的石门缓缓下降，露出石门后的墓穴和一位白衣飘然的女子。女子面若秋霜，淡淡地道：“这里原本是不欢迎外人的。”

你随白衣女子进到墓穴之中，发现墓穴内别有洞天，房间器物一应俱全，好似一方世外桃源。待你坐下，白衣女子说了声“稍等。”后翩然离去，片刻后，只见女子捧了一个石碗走来，碗中盛有清水。你接过石碗，将清水一饮而尽，只觉饮下去的是琼浆玉露，分外甘甜。白衣女子轻笑道：“此乃蜂王玉露。”你方才如梦初醒。

墓穴冷清，别无其他乐处，你二人如君子之交淡如水，浅谈一番武学经历，你便告辞离开。]],["time"]=3,["title"]=[[MAG古墓传人NOR]]},["210"]={["id"]=210,["introText"]=[[WHT这就是青棉蟒袍。一件华贵的官袍，以藏青色棉布为面料。官袍款式为圆领马蹄袖，上有过肩蟒纹和海水纹。蟒纹张牙舞爪，配上藏青底色，更显沉稳富丽。NOR]],["itemId"]=[[20xylqeq1]],["name"]=[[HIC青棉蟒袍NOR]],["need"]=2,["pic"]=[[Image/UI/StoreUI/wuqi.png]],["thankText"]=[[YEL三尺龙泉剑，匣里无人见。
