待到浓雾散去，你蓦然发现，手上的珍品券已经变成了一本泛黄的武学秘籍，令你错愕不已。NOR]],["time"]=19,["title"]=[[全篇]]},["221"]={["id"]=221,["introText"]=[[HIW她就是神使清秋。乌云秀发，杏脸桃腮。眉如春山浅淡，眼若秋波婉转；酥胸纤腰，盛臀修腿，胜似海棠醉日，梨花带雨。一轮明月映娇颜，两只蝴蝶轻似舞。假以时日，此身容便可祸国殃民。NOR]],["itemId"]=[[mianju1146]],["name"]=[[RED神使清秋NOR]],["need"]=24,["pic"]=[[Image/UI/AttrUI/mianju/shengshiqingqiu.png]],["thankText"]=[[YEL你方将珍品券递上，便有一位娇俏可人的女子自门后小跑而出，她拉起你的手向一条小径走去，边走边笑道：“殿里有什么好玩的，我带你去一个好地方。”
女子带着你左拐右绕，忽然间一片花海闯入你的眼帘。这里是一处山谷，谷中花开漫野，你们一走进花海就惊起几只闪着幽幽蓝光的蝴蝶。蝴蝶翩跹起舞，女子也随它们一齐起舞。她着一身淡紫长裙，颇具异域风采，舞姿娥娜，美撼凡尘。若此处是仙境，那她应是仙女，回眸一笑胜星华。
你们于花海中席地而坐，观星赏月，谈天论地，说遍天下事，不知时间流转，直至重光教徒寻来将你们带回。NOR]],["time"]=19,["title"]=[[MAG重光之女NOR]]},["222"]={["id"]=222,["introText"]=[[HIW她就是李魔头。美目流盼，冷傲无情。青丝中藏几缕银发，桃唇上抹一点绛红，左手携一杆拂尘，右掌凝聚真气，暗藏杀机，似是要将无边恨意宣泄而出。NOR]],["itemId"]=[[mianju1133]],["name"]=[[PNK李魔头NOR]],["need"]=15,["pic"]=[[Image/UI/AttrUI/mianju/limochou.png]],["thankText"]=[[YEL农家中，道姑左手怀抱婴孩，低声哼着童谣，右手中的拂尘轻轻挥动驱赶着蚊虫，似乎正在哄怀中的婴孩入眠。你有些错愕，那道姑分明就是江湖中凶名赫赫的“赤练女魔”，可此时却是一番慈爱模样。
似乎察觉到你来了，李魔头猛地抬头，柳眉横竖。她正欲开口说话时，你连忙递上珍宝券，简单地向她说明了来意。“惊醒了孩子你便死”，李魔头眉头缓缓舒平，轻声说了一句后，便低下头继续哼着童谣哄婴孩睡觉，不再搭理你。
    你看着眼前温柔的道姑和睡熟的婴孩，不禁想道，或许这样温柔的李魔头才是真正的她吧？NOR]],["time"]=19,["title"]=[[PNK赤练女魔NOR]]},["223"]={["id"]=223,["introText"]=[[HIW她就是貂蝉。玉骨冰肌，顾盼媚流，一袭鲜红舞衣，凤鸾飞绣，玉珠垂髻，只衬得她面若桃花，于烛曳摇光间尽显风姿灼华。世闻，纵盈光皎月，仙宫美娥，亦不足她倾城一笑。NOR]],["itemId"]=[[mianju1115]],["name"]=[[HIM貂蝉NOR]],["need"]=10,["pic"]=[[Image/UI/AttrUI/mianju/diaochan.png]],["thankText"]=[[YEL你将拜帖递进一座江南宅院的正门，随即被一位垂髫女童引进院内凉亭，见花摇树影间的石桌旁坐着一素手调琴的美人，生得肌白赛雪，一袭红衫似红梅映月，果然是倾城绝色。
传闻当年貂蝉受主家王允所托，为护汉室江山以身作饵周旋于董卓与吕布之间，后来奸臣董卓被灭，吕布亦成三家姓奴令天下人耻笑，不得善终，而貂蝉从此消失，没想到竟是在这隐居。
她许久不接待生人，与你相见时脸颊飞红一片，以袖掩面，露出的美目波光流转。
看着这样一双妩媚动人的眼睛，无论男女皆会受之蛊惑。只听她声音婉转如莺啼，笑言：“若不嫌弃，貂蝉有一曲献给少侠。”
说罢，她双指在琴弦上翩飞，世闻其舞月见羞，原来美人弹琴也如仙宫之乐，令你痴醉不已。NOR]],["time"]=19,["title"]=[[MAG月见羞NOR]]},["224"]={["id"]=224,["introText"]=[[HIW他就是黄师傅。身躯凛凛，相貌堂堂。一双眼睛射寒星，两弯剑眉如刷漆。气宇轩昂，大红的舞狮头肩上扛。从容不迫，将脑后束起的一根长辫咬在口中。NOR]],["itemId"]=[[mianju1130]],["name"]=[[HIM黄师傅NOR]],["need"]=17,["pic"]=[[Image/UI/AttrUI/mianju/huangshifu.png]],["thankText"]=[[YEL珍品券送入不久后，走出一位身着黄布衣的男子，拱手道：“黄师傅正在做准备，请少侠稍等。”
你方与男子聊了两句，前边突然开始敲锣打鼓，人群也喧闹了起来。你随着人群往前方走去，便见着一位气宇轩昂的男子，扛着大红的舞狮头随着鼓点起舞。时喜时醉，时惊时怒，在木桩上灵巧跃动，表演得形神合一，生动活泼。
一场舞狮结束，你只觉意犹未尽，正巧此时黄布衣的男子替黄师傅来邀你至武馆中一叙，你欣然同意。武馆中，黄师傅早已命人备好茶水，你们畅谈古今，相谈甚欢，竟忘了时间，待回过神来已是华灯初上，你才依依不舍地告辞离去。NOR]],["time"]=19,["title"]=[[HIW醒狮飞鸿NOR]]},["225"]={["id"]=225,["introText"]=[[WHT这就是粽叶帽。粽叶常用芦苇叶，而这顶小帽就是用新鲜的翠绿芦苇叶编织而成，样式极为别致。NOR]],["itemId"]=[[eq2020dwfd01]],["name"]=[[HIG粽叶帽NOR]],["need"]=2,["pic"]=[[Image/UI/StoreUI/wuqi.png]],["thankText"]=[[YEL三尺龙泉剑，匣里无人见。
