待到浓雾散去，你蓦然发现，手上的珍品券已经变成了一本泛黄的武学秘籍，令你错愕不已。NOR]],["time"]=20,["title"]=[[全篇]]},["238"]={["id"]=238,["introText"]=[[WHT他就是胡大侠。面似寒霜，冷傲逼人。一对墨眉有如柳叶般纤细，一双眼眸好似狐狸般狭长，他手握单刀，冰冷的眼神散发出似有若无的杀意，令人胆寒。NOR]],["itemId"]=[[mianju1127]],["name"]=[[胡大侠]],["need"]=25,["pic"]=[[Image/UI/AttrUI/mianju/hufei.png]],["thankText"]=[[YEL寒冬腊月，飞雪纷纷，你根据百晓生的指引独自北上，前往长白山深处去寻找那道侠影。

雪地中，男子舞着手中的长刀，他身形腾挪，刀影翻飞，灵动迅捷，犹如雪狐般机敏。舞至精彩处，你忍不住叫了声“好”，他循声向你望来，或许是你手中的珍宝券，让他冷峻的神色稍稍缓和。只见他身影几下闪动便到了你跟前，他手中黑刀径直向你横削而来，只是出刀的速度比上先前却是慢了几分，你心下了然，拔出长剑向他攻去。

拆招五百余合，不分胜负，你们哈哈一笑罢手停战，拿出酒壶痛饮一番。你醉倒之前，依稀还记得他轻唱的歌谣，“来日大难，口燥舌干。今日相乐，皆当喜欢。”NOR]],["time"]=20,["title"]=[[MAG雪山侠行NOR]]},["239"]={["id"]=239,["introText"]=[[WHT她就是紫衣姑娘。她颜若朝霞，双眸灿烂。眼神总有狡黠之色，眉宇之间似笑非笑。乌溜溜的眼中透着古灵精怪，亦正亦邪的气质，让人难识其本性。NOR]],["itemId"]=[[mianju1129]],["name"]=[[紫衣姑娘]],["need"]=17,["pic"]=[[Image/UI/AttrUI/mianju/ziguniang.png]],["thankText"]=[[YEL你刚将珍品券送上，便听见林间瑟瑟作响，一团漆黑的东西忽地向你袭来，你身形一闪，灵巧躲过。而那团漆黑的东西落在地上瞬时舒展开来，原是一条漆黑的长蛇，蛇头呈三角状，身有手腕粗，吐出的蛇信子红中带黑，你一瞧便知它剧毒无比。
一枚银针忽地扎入蛇身，方要游走的黑蛇扭动了几下便瘫软在地一动不动了。“你躲得倒是挺快。”话音刚落，一位身着松花绿衣裙的女子自花树间钻出，看着你笑道：“我在这捉了一天的蛇，甚是无聊，你陪我至山下转转。”
你点头应好，与她前往山下镇子，市井热闹，摊贩林立，你们好一阵玩耍，直至夜深才告辞分别。NOR]],["time"]=20,["title"]=[[HIR恶紫夺朱NOR]]},["24"]={["id"]=24,["introText"]=[[WHT湘西一带流传的爪法绝学，招数均是狠辣异常，专攻敌方各处要害，阴风凛凛，极难防范。]],["itemId"]=[[yinfengzhuabox1]],["name"]=[[HIW阴风爪NOR]],["need"]=18,["pic"]=[[Image/UI/StoreUI/shujuan2.png]],["thankText"]=[[YEL满月临弓影，连星入剑端。
不学燕丹客，徒歌易水寒。
你沉吟不语，将珍品券捧于手上，似在心中思索着什么。
须臾间，空中一股浓雾飘散而来，遮蔽了你的视线。
待到浓雾散去，你蓦然发现，手上的珍品券已经变成了一本泛黄的武学秘籍，令你错愕不已。NOR]],["time"]=4,["title"]=[[全篇]]},["240"]={["id"]=240,["introText"]=[[HIW她就是灵姑娘。双眸灵动，脉脉含情。相貌似有十六七岁年纪，身形却娇小如十三四岁的小姑娘。在万花的簇拥之下，抬手轻轻折下一枝，细嗅花香，尽显兰心蕙质。NOR]],["itemId"]=[[mianju1128]],["name"]=[[灵姑娘]],["need"]=15,["pic"]=[[Image/UI/AttrUI/mianju/chenglingsu1.png]],["thankText"]=[[YEL自洞庭湖北行三十余里，又穿过山镇，越过深林，你终于来到了庄前。庄内圆屋式样怪异，仿若一座大坟。你心下敬畏，硬着头皮喊门，但过了许久却无人搭理。你也不好硬闯，只能转道庄旁花圃处亭子小歇，静候主人归来。

微风徐徐，你坐在亭中闻着花圃传来的香气，只觉眼皮沉重，昏昏欲睡。“这花圃里的花有古怪！”当你意识到不对的时候，已经太迟，随后便是眼前一黑。

再醒转时，却看见一个双眸灵动的少女手中拿着你的珍宝券，嘴角满是笑意。

    “你的毒已经解了。我还以为是我师兄师姐上门来了，没想到来的人是你。”你心下叹服，随即向她询问了一些辟毒的法子，她也一一向你解答，一来二去，倒也算得上交谈甚欢。NOR]],["time"]=20,["title"]=[[七心海棠]]},["241"]={["id"]=241,["introText"]=[[HIW他就是宝爷。鬼头鬼脑，机灵十足。一身另类的打扮派头十足：头戴一顶老虎帽，鼻上一副西洋镜，脸颊脖子上满是香艳的唇印。虽然颇有些暴发户的俗气，却也显得款式非凡。NOR]],["itemId"]=[[mianju1131]],["name"]=[[宝爷]],["need"]=15,["pic"]=[[Image/UI/AttrUI/mianju/weijueye.png]],["thankText"]=[[YEL“为人不识陈大侠，就称英雄也枉然”，他折扇一收，品了一口香茗，又对着周围的看官继续说道，“陈大侠当年手持长剑，一人对着鳌拜和两百多个士兵......”

“两百多个，一人一口唾沫，姓陈的也被淹死了......”

“就是啊，你会不会说书啊，不会赶紧下台！”

“滚下来！”

......一番起哄后，他被看官们赶到了后院，你也趁着这个机会跟了上去，并将手中的珍宝券递给了他。

“嘻嘻，没想到我躲到了这儿，还能被你找到。算了，你跟我来吧。”他带着你出了后院，穿街过巷，最终进了一个四进四出、富丽堂皇的大宅。随后你也见到了他那七个国色天香、如花似玉的妻子。看着他一副游戏人生的模样，你不得不感慨，或许这才是真正的人生赢家吧。NOR]],["time"]=20,["title"]=[[HIW小白龙NOR]]},["242"]={["id"]=242,["introText"]=[[WHT他就是张真人。他生得高大魁梧，须眉俱白。身着武当道服，卓立于大殿之上，正气凛然，宽和从容，颇有仙风道骨之姿，令人大有敬畏之心。NOR]],["itemId"]=[[mianju1135]],["name"]=[[HIB张真人NOR]],["need"]=24,["pic"]=[[Image/UI/AttrUI/mianju/zhangzhenren.png]],["thankText"]=[[YEL你将珍品券递上，一个身着蓝色道袍的小道童自山门走出，恭敬道：“少侠久等了，这边请。”

你随小道童行走在武当山中，一路景色秀美，赏心悦目，你看得专心，不知不觉间就已随小道童走到了崇福岩。只见一块岩石悬空突出，似一只龇牙咧嘴的石虎，威风凛凛，叫人生畏。小道童又领你走到一座殿前，便拱手告退。

你走入殿内，只见一位老者坐于窗前，老者虽须眉俱白但依旧魁梧健壮，身着道袍，颇有仙风道骨之姿。见你到来老者起身邀你入座，随后又给你斟上一盏清茶。老者此时和蔼随和，似家中长辈一般对你嘘寒问暖。

窗外有山石嶙峋，草木欣荣，殿内茶香可口，沁人心脾。你与老者自生活琐事聊到武功道学，直至暮色苍茫你才告辞离开。NOR]],["time"]=20,["title"]=[[BLU太极玄功NOR]]},["243"]={["id"]=243,["introText"]=[[HIW他就是幻花剑客。眉目疏朗，俊逸非凡。他抱剑立于花树下沉思，似在透过手中的吊坠望见故人，少了些萧杀，多了分落花的忧愁，左肩上绽放的将离让他更添一丝风流。NOR]],["itemId"]=[[mianju1144]],["name"]=[[幻花剑客]],["need"]=20,["pic"]=[[Image/UI/AttrUI/mianju/huanhuajianke.png]],["thankText"]=[[YEL樱花树下，他端详着手中的吊坠，似乎在思念着故人。也许是听到你的脚步声，他猛然回头，手默默的按住刀柄，神情由怀念转为肃杀。你连忙递上手中的珍宝券，见此他的神色才稍微缓和，只是始终一语不发。

也许是环境使然，你也没有开口询问的欲望，你与他便这么静默对视了半盏茶时间。他对着你默默地点了点头，随后从树下土地中挖出两坛酒，将其中一坛丢给了你，然后自顾自的喝了起来。喝罢，便独自离开。

忽而大风吹过，樱花散落，风中传来一阵异乡的歌谣，浪漫却又忧伤，跟他给你的酒一般滋味。NOR]],["time"]=20,["title"]=[[花影随行]]},["244"]={["id"]=244,["introText"]=[[HIW他就是骑士莱恩。眼眸深邃，鼻梁高挺。他一身钢铁重甲，碧绿的眼睛，金黄的头发，棱角分明的面容显得刚毅不屈。身后的士兵引吭高歌，胸前的徽记烨烨生辉。NOR]],["itemId"]=[[mianju1145]],["name"]=[[骑士莱恩]],["need"]=23,["pic"]=[[Image/UI/AttrUI/mianju/fengbaoqishilaien.png]],["thankText"]=[[YEL你递上拜帖，被仆人们引到古堡深处。见到他时，你有点错愕，眼前的男子身穿异国礼服，尽显雍容华贵，与你印象中那个一身铁甲的身形确实相差太大。莱恩被你错愕的表情逗得开怀一笑，随后便拉着你去到了庭院小歇。

伴着夕阳的余晖，莱恩与你坐在太阳伞下，品尝着他家乡的甜点与红茶。不得不说，异乡的食物确实别有风味，让你心生喜欢。

“来中原那么久，难得有人来我这儿做客。我很喜欢中原，这里很美，很有活力。”莱恩又细品了一口红茶，继续道，“但这里的人们缺乏信仰，我希望重光的光辉有一天能照射到中原各地。”

    “愿重光赐予你祝福。”NOR]],["time"]=20,["title"]=[[风暴神使]]},["245"]={["id"]=245,["introText"]=[[HIW他就是任老魔头。狂傲不羁，桀骜不驯。一头黑发，一袭青衫，一只独眼，更显其傲视群雄之姿。而他伤眼上的铁护，和他掌心磅礴的吸力，似要宣告这天地间只有他一人。NOR]],["itemId"]=[[mianju1143]],["name"]=[[任老魔头]],["need"]=15,["pic"]=[[Image/UI/AttrUI/mianju/renjiaozhu.png]],["thankText"]=[[YEL教徒接过你手中的拜帖，领着你穿过崖间小道，向着山顶的大殿走去。约莫走了半个时辰，你远远地看到了在大殿上圣教主。

还未走近，教众忽而齐声高叫：“圣教主千秋万载，一统江湖！千秋万载，一统江湖！”你被吓了一跳，隐隐觉得有几分怪异，但身为客人终究要讲几分礼数，便执弟子礼远远地向圣教主行礼。

“不必多礼”，他似乎心情大好，“几十年不见天日，刚报了旧仇，便来了新友，不错不错！来人，上酒！”觥筹交错，你们相谈甚欢，他也指点了你一些武学上的问题，你自觉此行收获颇多。

    下得崖来，山间又传出“千秋万载，一统江湖”、“文成武德，仁义英明”的吹捧之语。你皱了皱眉，转身离去，不再回头。NOR]],["time"]=20,["title"]=[[天下任行]]},["246"]={["id"]=246,["introText"]=[[WHT她就是落英女侠。何彼秾矣，华如桃李。一双脉脉含情的眼眸，一条缀满铜铃的发带，一件艳红明丽的衣裳，好似一位身着嫁衣的女子，正在翘首盼望意中人的到来。NOR]],["itemId"]=[[mianju1137]],["name"]=[[RED落英女侠NOR]],["need"]=15,["pic"]=[[Image/UI/AttrUI/mianju/chaoyingnvxia.png]],["thankText"]=[[YEL你通过拜帖进到终南山山顶，梅林间一红衣女子正在月下用指拭剑。

“久闻少侠大名，可有兴趣和我比划几招？”

你知前辈武功高深，有心见识一番，故而欣然应允。

比试中，她剑影如蛟龙戏水，又有百般变化，你一招刚起，她破解之法顷刻随出，游刃有余，简直毫无破绽。

你越发心惊，但更觉佩服，结束后向前辈郑重施了一礼，她嫣然笑道：“我该好好谢你才是。”

你尚且不解，只听她笑声畅快，“我正在创一套克制全真武功的剑法，遇到几处难点，和你切磋完竟有了些眉目，少侠觉得我这剑法能否大成？”

练一番惊世武功已是难事，何况自创，但你见她眸光烨烨，那般神采飞扬，不由肯定地点头。NOR]],["time"]=20,["title"]=[[MAG古陵深情NOR]]},["247"]={["id"]=247,["introText"]=[[HIW他就是神使劳伦斯。发棕微卷，眉目深邃，一双如琥珀般剔透晶莹的双眼闪烁着摄人心魄的光芒。身着便服时，是个狡诈冷酷的商人，身披铠甲时，亦是号令三军的统帅。NOR]],["itemId"]=[[mianju1147]],["name"]=[[神使劳伦斯]],["need"]=22,["pic"]=[[Image/UI/AttrUI/mianju/zuoshenshi.png]],["thankText"]=[[YEL你将拜帖递上，片刻后出来二位金发美姬，对你盈盈一拜，笑道：“神使有请！”

你随之走进一幢西式小楼，只见大厅内富丽堂皇，壁炉设于墙边，钟表挂于墙上，一张长达数丈的餐桌立于大厅中央，上面摆满各种漆器银皿。

劳伦斯坐于上首，对你轻轻点头，示意你入座，随后两掌一拍，只见数位金发美姬鱼贯而入，将手上的菜肴端放在餐桌上。你与劳伦斯二人拿起银制刀叉，将盘子里的牛排切成块状，送入口中，牛肉入口即化，这种西方独特的烹制手法，令你大开眼界。

餐毕，劳伦斯手捧餐巾轻轻擦拭着嘴角，对你说道：“虽然我们共进晚餐，但终究道路不同，也许彼此仍是敌人。是敌是友，谁对谁错，这都不重要了。愿重光赐予你祝福。”NOR]],["time"]=20,["title"]=[[BLU重光左使NOR]]},["248"]={["id"]=248,["introText"]=[[HIW他就是夜叉。满口獠牙，凶神恶煞。一对犄角盘在头顶，怒发如针，双目如神。稍一吐息，浓烈的白雾便从口鼻中滚出，当真是煞星下凡。NOR]],["itemId"]=[[mianju1151]],["name"]=[[夜叉]],["need"]=20,["pic"]=[[Image/UI/AttrUI/mianju/yecha1lv.png]],["thankText"]=[[YEL你躺在床上，只觉浑身乏力，眼皮沉重......

你一人行走在路上，身边不知从哪冒出了一团团迷雾，霎时间，四周被迷雾围绕。你却丝毫不觉得奇怪，仍是朝前走去。

不知道走了多久，身前出现了奇怪的光景。似绿火飞舞，似繁花盛开，似有歌女在耳畔浅吟低唱，又似听到了金戈铁马兵器相击。待你回过神来，眼前多了一个满口獠牙、凶神恶煞的夜叉。

出奇的，你并不害怕，反而向眼前的夜叉伸了伸手，夜叉愣了一愣，随后哈哈大笑起来，只是那声音如破锣，着实有些骇人。随后的事情，你记不真切，似乎你与夜叉喝酒聊天，又似乎你与夜叉打了一架......

鸡鸣声起，你忽而惊醒，竟是出了一身冷汗，而床头的珍宝券却早已不翼而飞了......NOR]],["time"]=20,["title"]=[[夜叉降临]]},["249"]={["id"]=249,["introText"]=[[HIW他就是夜半书生。白面无须，弱不禁风。一介文弱书生，于书屋中耕读到夜半，为何......竟感觉有些胆寒心颤。NOR]],["itemId"]=[[mianju1152]],["name"]=[[夜半书生]],["need"]=15,["pic"]=[[Image/UI/AttrUI/mianju/shutong.png]],["thankText"]=[[YEL你躺在床上，只觉浑身乏力，眼皮沉重......

你一人行走在路上，身边不知从哪冒出了一团团迷雾，霎时间，四周被迷雾围绕。你却丝毫不觉得奇怪，仍是朝前走去。

不经意间，你走到了一座院落前，耳畔竟传来夜读之声。“有朋自远方来，不亦乐乎？”你闻言心下大喜，便推门而入，却见一个文弱书生对着烛台捧书耕读，甚是用功。

他对你突然闯入，也不愠怒，却向你问了一些书籍上的问题。虽说他问的问题已有点久远，但你搜肠刮肚之下，还是一一应答而出。随后的事情，你记不真切，依稀只记得他说了一句，“没想到已经过了好几百年了”。

忽而鸡鸣声起，你头痛欲裂，带你缓过来的时候，床头的珍宝券却早已不翼而飞了......NOR]],["time"]=20,["title"]=[[夜半书生]]},["25"]={["id"]=25,["introText"]=[[WHT这是凌霄道长所创的一门内功心法。凌霄道长的武功路数十分神秘，江湖传言他出自龙虎山。]],["itemId"]=[[lingxiaoxinfa1]],["name"]=[[HIC凌霄心法NOR]],["need"]=15,["pic"]=[[Image/UI/StoreUI/shujuan3.png]],["thankText"]=[[YEL满月临弓影，连星入剑端。
不学燕丹客，徒歌易水寒。
你沉吟不语，将珍品券捧于手上，似在心中思索着什么。
须臾间，空中一股浓雾飘散而来，遮蔽了你的视线。
待到浓雾散去，你蓦然发现，手上的珍品券已经变成了一本泛黄的武学秘籍，令你错愕不已。NOR]],["time"]=4,["title"]=[[全篇]]},["250"]={["id"]=250,["introText"]=[[HIW他就是林少侠。眉清目秀，丰神如玉。白日里温雅谦逊，淡然沉静，抱剑而立只道是个文弱的美少年。而不知何故，一到夜里竟满身疮痍，面目疯狂而绝望，叫人望而生畏。NOR]],["itemId"]=[[mianju1154]],["name"]=[[林少侠]],["need"]=15,["pic"]=[[Image/UI/AttrUI/mianju/linshaoxia1.png]],["thankText"]=[[YEL西湖湖畔，你寻觅许久，终于是见到了他。

与往常的丰神如玉不同，此时，他双眼处蒙着红纱，浑身血污，右手死死攥着宝剑，不时向四周挥舞着，显得有些癫狂。

你向他表明来由，并将珍宝券远远地丢在他的跟前，一番警惕地摸索过后，他似乎对你暂时打消了敌意。

他与你谈起这些年来的经历，从救人被灭门，到拜师被骗秘籍，从练功报仇，到最终双目被毁。你听了他的故事，心中既怜又恨，但却不知道该如何开口，最终也只是选择了微微一叹。

临别之际，你还是问出了心中的疑惑，“你对得起岳小妹吗？”

他如遭雷击，却始终缄默。

你摇了摇头，转身便走，不再留恋。NOR]],["time"]=20,["title"]=[[夜里悲狂]]},["251"]={["id"]=251,["introText"]=[[HIW他就是拳霸。筋肉虬结，眼神凌厉。太阳穴高高隆起，颧骨和下巴勾勒出坚毅的线条，心如猛虎，动如脱兔，伟岸的身躯似是钢浇铁铸，一双缠满绷带的铁拳无人可以匹敌。NOR]],["itemId"]=[[mianju1155]],["name"]=[[拳霸]],["need"]=15,["pic"]=[[Image/UI/AttrUI/mianju/quanba.png]],["thankText"]=[[YEL月影下，竹林中，传来破空之声。

你循声而至，眼前的男子果然就是你要找寻的拳霸。你趁着他练拳歇息的片刻，递上珍宝券，向他表明了来意。他虽然对你的到来略感惊异，却没有多说什么，反而拉着你陪他一起练拳。

拳来脚往，切磋之中，你发现他的招式路数与中原拳脚大不相同。比起中原精妙的拳招，他的路数更为简单，招式大开大合，威力足可劈石断碑，每一招虽然少了虚实变化，但胜在拳势刚猛，叫对手退无可退、让无可让。这一次切磋确实让你受益颇多。NOR]],["time"]=20,["title"]=[[拳霸天下]]},["252"]={["id"]=252,["introText"]=[[WHT耳朵也尖尖，琼鼻也尖尖。灰白色的毛发比绸缎还要柔顺，圆圆的肚皮比坐垫还要柔软，乖巧巧地静坐在花枝下，似要学那猛虎细嗅蔷薇的花香。NOR]],["itemId"]=[[mianju1156]],["name"]=[[PNK狸奴入梦NOR]],["need"]=21,["pic"]=[[Image/UI/AttrUI/mianju/linu1.png]],["thankText"]=[[YEL你将珍品券递上，忽听几声喵喵直叫，低头望去，脚边竟站着一只灰头白肚的猫儿，正对着你的脚踝磨来蹭去，细长的尾巴卷起来，轻轻地拍打在你的腿肚子上，似乎在指引你往里走。
你随着猫儿向巷子里走了十余步，忽而间猫儿一钻便不见了身影，从巷子内缓缓走出一个手捧书卷的俏姑娘，眼波婉转凝望着你，文静而端庄。
你与姑娘从天上到地下，无所不谈，相谈甚欢。一只猫儿引你识得这红颜知音，只觉是缘分，只道是神奇。不知不觉，你们二人在巷子里谈到月上眉梢，夜色渐浓。NOR]],["time"]=20,["title"]=[[YEL狸奴入梦NOR]]},["253"]={["id"]=253,["introText"]=[[HIW她就是奎丽尔。金发碧眼，轻盼曼顾。那美丽的头发披散在身上，像一股金色的瀑布．波浪起伏，金光闪闪。来自大秦的红绸穿过锁骨，盖过细腰，勾勒出惊心动魄的美艳弧线。NOR]],["itemId"]=[[mianju1157]],["name"]=[[奎丽尔]],["need"]=20,["pic"]=[[Image/UI/AttrUI/mianju/kuilier.png]],["thankText"]=[[YEL尽管早已做好了心理准备，但是在她脱去黑袍，展现真身时，你双颊通红，心还是忍不住跳慢了一拍。

金发碧眼，曼妙无双，她对你浅笑的刹那，你下意识地想起了一句诗，“回眸一笑百媚生，六宫粉黛无颜色。”

“嘻嘻，我们那边的女子很多都是我这样的穿着。你用不着那么惊奇。”也许是夜晚时分身边的人并不多，又或许是她突然兴起，她径直挽起你的手向秦淮河畔走去，“秦淮河的风景很美，我真的很喜欢。”说罢，她对着你又是浅浅一笑。
你们挑了个能观赏江景小亭，便坐下举杯相饮。

晚风吹拂，秦淮河上流光溢彩，画舫相连灯火通明，耳畔传来歌女清唱，才子吟诵，酒客痛饮之声，身边的少女脸带微笑沉浸其中。你看着眼前的景象只觉似醉非醉，却不愿醒来。NOR]],["time"]=20,["title"]=[[大秦少女]]},["254"]={["id"]=254,["introText"]=[[WHT这就是长相思。山水一程千帐灯，风雪一更无此声。纵豪情万丈，侠肝义胆，唯“长相思”三字，情生，则不敢道也。故不闻琴音，亦可叫人摧心肝。NOR]],["itemId"]=[[eq2020qxbc01]],["name"]=[[RED长相思NOR]],["need"]=3,["pic"]=[[Image/UI/StoreUI/wuqi.png]],["thankText"]=[[YEL三尺龙泉剑，匣里无人见。
一张落雁弓，百支金花箭。
你沉吟不语，将珍品券捧于手上，似在心中思索着什么。
须臾间，空中一股浓雾飘散而来，遮蔽了你的视线。
待到浓雾散去，你蓦然发现，你的手上竟多了一件宝光四射的装备，而那张珍品券早已不知所踪。NOR]],["time"]=20,["title"]=[[HIW珍品装备NOR]]},["255"]={["id"]=255,["introText"]=[[WHT这就是苦海知崖。知崖而不悔，则苦海无边。叶传泽所打造的传世之剑，据闻这两柄剑均以人血入剑，故剑刃暗泛猩红，出鞘见血，隐有怨愤。NOR]],["itemId"]=[[eq2020cp08]],["name"]=[[RED苦海知崖NOR]],["need"]=3,["pic"]=[[Image/UI/StoreUI/wuqi.png]],["thankText"]=[[YEL三尺龙泉剑，匣里无人见。
