不学燕丹客，徒歌易水寒。
你沉吟不语，将珍品券捧于手上，似在心中思索着什么。
须臾间，空中一股浓雾飘散而来，遮蔽了你的视线。
待到浓雾散去，你蓦然发现，手上的珍品券已经变成了一本泛黄的武学秘籍，令你错愕不已。NOR]],["time"]=21,["title"]=[[全篇]]},["269"]={["id"]=269,["introText"]=[[HIW白云城主所创之剑法，如青天白云无瑕无垢，剑招变化随心所欲，天下无双的剑法。NOR]],["itemId"]=[[feixianjianfa]],["name"]=[[飞仙剑法]],["need"]=6,["pic"]=[[Image/UI/StoreUI/shujuan5.png]],["thankText"]=[[YEL满月临弓影，连星入剑端。
不学燕丹客，徒歌易水寒。
你沉吟不语，将珍品券捧于手上，似在心中思索着什么。
须臾间，空中一股浓雾飘散而来，遮蔽了你的视线。
待到浓雾散去，你蓦然发现，手上的珍品券已经变成了一本泛黄的武学秘籍，令你错愕不已。NOR]],["time"]=21,["title"]=[[全篇]]},["27"]={["id"]=27,["introText"]=[[WHT她就是狄水清，江湖上传闻她是峨眉叛徒，与柳玄风同为一伙。她一身青衫，容貌甚美，因幼时一段坎坷的经历，致使她变得冷漠寡言，唯独信任依赖于情人韩一枫。她行踪不定，其背后势力复杂难明，因她的存在，武林常起波澜。]],["itemId"]=[[mianju1078]],["name"]=[[HIY狄水清NOR]],["need"]=25,["pic"]=[[Image/UI/AttrUI/mianju/dishuiqing.png]],["thankText"]=[[YEL你将珍品券递上，忽听见里面打斗叱喝之声，你正感疑惑时，一阵风夹裹着几张薄纸吹落至你脚边。

你粗略看见上面的“门派秘典”四字，狄水清已从竹林中走出，打斗声也随之停止，原来刚才是她在演练武功。

见你对这些纸张并无抢夺之意，她目光复杂，将薄纸拾起后，颔首请你进屋。

一番拜访结束，你回想起今日与她共处的时光，恍然发现她对你倒比从前话多了那么一点。]],["time"]=4,["title"]=[[HIC冰兰霜华NOR]]},["270"]={["id"]=270,["introText"]=[[HIW她就是天竞门主。婀娜多姿，盈盈妙目，顾盼间眼波流转。面上常带着花旦妆，更衬得人颜色艳丽，娇媚无双。NOR]],["itemId"]=[[mianju1111]],["name"]=[[YEL天竞门主NOR]],["need"]=25,["pic"]=[[Image/UI/AttrUI/mianju/tianjingmenzhu1.png]],["thankText"]=[[YEL你将珍品券递上，在戏楼门口热情地招呼着客人的小二立刻向你拱手道：“少侠，雅阁已为您备好，请随我来。”
你跟着小二走到二楼的一间雅阁，此间比大厅清净些，从楼台望去，能将戏台尽收眼底。你很快就被台上的戏吸引了去，连小二何时离开都不知。台上的旦角声音婉转动人，身形婀娜多姿，眉眼顾盼间便将你带入戏中人，一曲唱罢也久久不能回神。
几场戏后，小二再次前来带你走至戏院的后花园，园中有一青衣女子在小心擦拭着长琴。与戏台上的艳丽、娇媚相比，女子此时素雅、清冷了许多，就好似她们不是同一人。女子的声音依旧婉转动听，你们一起畅聊戏曲、音律，这一晚相谈甚欢。NOR]],["time"]=21,["title"]=[[GRN粉黛英姿NOR]]},["271"]={["id"]=271,["introText"]=[[HIW她就是朱姑娘。清雅秀丽，楚楚动人。少女盈盈十六七岁年华，身穿花红，肌肤雪白，眼底似有泪痕。眉毛微蹙，令人暗生情愫，如泣如诉，直叫人牵肠挂肚。NOR]],["itemId"]=[[mianju1126]],["name"]=[[GRN朱姑娘NOR]],["need"]=15,["pic"]=[[Image/UI/AttrUI/mianju/azhu.png]],["thankText"]=[[YEL接过珍宝帖之时，她双目含泪，满面凄苦，似乎遇上了什么难事。你心有不忍，转而向她问询之时，她却闪烁其词。你方才想起，这些时日她跟丐帮的那位英雄人物逃亡天下闹得江湖皆知，眼下情景可能就是跟那位英雄有关，便试探地问了一句，“是因为萧英雄吗？”
“不，大哥他对我很好，是我......我不能再陪着他了。”一语说罢，似乎耗尽了她全部的气力，不管你再如何安慰，她始终是黯然垂首不发一言。你陪她静默良久，最终选择告辞离去。
出门之际，你依稀听到了她的低语，“只能下辈子再陪你塞上牧牛放羊了。”NOR]],["time"]=21,["title"]=[[BLU朱颜碧玉NOR]]},["272"]={["id"]=272,["introText"]=[[HIW她就是无悔妹妹。肤嫩如雪，眉眼如画。水蓝色的发饰，淡红色的束带，衬上一头栗色的长发。柔情无限，眼波盈盈，羞红的脸上挂着浅笑，贝齿轻咬着发带，只觉分外可爱。NOR]],["itemId"]=[[mianju1138]],["name"]=[[PNK无悔妹妹NOR]],["need"]=14,["pic"]=[[Image/UI/AttrUI/mianju/buhuimeimei.png]],["thankText"]=[[YEL珍品券刚一递上，便见一位肤嫩如雪、娇小玲珑的女子步履轻快地走出来。她巧笑倩兮，美目盼兮，声音清脆的道：“少侠快随我来。”
女子将你引入一座偏院，你在一石凳上坐好，便拿出准备好的杏脯送予女子。女子笑逐颜开，吃着杏脯又道：“少侠与我讲些江湖上的趣事和笑话吧，我要转述给殷六哥解闷。”
你与女子讲起江湖上的趣闻，女子听得开心，时不时抚掌欢笑。转眼之间，日落梢头，你便告辞离开。NOR]],["time"]=21,["title"]=[[PNK此情无悔NOR]]},["273"]={["id"]=273,["introText"]=[[HIW她就是山鬼。袅娜旖旎，乌羽作冠，赤羽霓裳。飘飘然，宛若山间精魅；寂寂兮，犹比巫山神女，匆匆一瞥，使人怅忘难归，犹在梦中。NOR]],["itemId"]=[[mianju1109]],["name"]=[[RED山鬼NOR]],["need"]=5,["pic"]=[[Image/UI/AttrUI/mianju/shangui.png]],["thankText"]=[[YEL你将珍品券递上，片刻后，幽篁林出现一只毛色斑斓的花狸，颈间带有一串草织花环。花狸对着你轻咛示意。
你随花狸进入林中，走入一处山间洞穴，却见其中另有天地。神树擎天，溪水潺潺，仙雾渺渺，恍如仙境。一位清丽绝俗的女子立于神树前，向你微微颔首，淡淡地道：“这里不常有人来。”
待你入座，女子端上一盘鲜果，你浅尝一口，只觉果肉细腻、回甘无穷。女子又拿出一精致小鼓，随后轻语诵吟，击鼓和音。女子的歌声悦耳，曲调悠扬，你不由得闭眼聆听，刹那间你好似卧于云中，世间再无何事能将你牵绊，无拘无束地游于天地间。NOR]],["time"]=21,["title"]=[[HIB岁宴华予NOR]]},["274"]={["id"]=274,["introText"]=[[HIW她就是钟姑娘。脸如朝霞，目比秋水，肤如凝脂，笑靥如花，容貌明媚照人，吹气如兰，越看越美，令人舍不得移目。NOR]],["itemId"]=[[mianju1030]],["name"]=[[HIB钟姑娘NOR]],["need"]=4,["pic"]=[[Image/UI/AttrUI/mianju/zhongling.png]],["thankText"]=[[YEL也许是今天运气不错，递上拜帖之后，谷中丫鬟很快地领着你穿过树林小径，来到了后院，你突然想起谷主恶名，心中不免有些害怕，便偷偷地留意四周。这时，背后传来一阵银铃般的笑声，“今天我爹不在谷里，你不用那么害怕。”你闻言心中稍宽，转头望去，却见少女一身粉衫，笑靥如花，你看得痴了。
她噗嗤一笑，“呆子！对了，我娘早上刚炒了些瓜子，你要不要吃些？”你其实什么也没听清，只是下意识的点了点头，将她放在你手上的东西一把丢进嘴里，然后迅速地又吐了出来。口中的辛涩让你清醒过来。
“哈哈哈，哪有你这样吃瓜子的。算了，既然你吃不惯这瓜子，那就陪我一起抓些蛇吧，不然貂儿可得饿着肚子了。”你欣然点头，与她抓了一下午的蛇。
NOR]],["time"]=21,["title"]=[[MAG钟灵毓秀NOR]]},["275"]={["id"]=275,["introText"]=[[WHT这就是穷奇。假托《山海经》中异兽之名所铸的兵刃之一。铸造之人喜读异兽怪谈，又有炼制神兵之技，遂铸了一套兵刃，聊慰平生。NOR]],["itemId"]=[[eq2020xslb11]],["name"]=[[HIR穷奇NOR]],["need"]=3,["pic"]=[[Image/UI/StoreUI/wuqi.png]],["thankText"]=[[YEL三尺龙泉剑，匣里无人见。
