待到浓雾散去，你蓦然发现，手上的珍品券已经变成了一本泛黄的武学秘籍，令你错愕不已。NOR]],["time"]=22,["title"]=[[全篇]]},["29"]={["id"]=29,["introText"]=[[WHT他就是灶王，是被玉皇大帝派遣到人间考察一家善恶之职的官。每逢年末，他都要回天庭禀报这一年里家家户户的善恶记载。到了年初，又会重回人间，继续掌管人们的饮食。NOR]],["itemId"]=[[mianju1076]],["name"]=[[HIY灶王NOR]],["need"]=10,["pic"]=[[Image/UI/AttrUI/mianju/zaowang.png]],["thankText"]=[[YEL你将珍品券递上，忽然四周浓雾弥漫，一位青衣童子从雾中走出，向你道：“少侠请随我来！”

你跟在他后面，不多时走进一间凉亭，灶神端坐在石桌的另一侧，邀你入席，“小友既然能来此地，说明与我缘分不浅，你且尝尝这些菜肴的味道。”

你刚坐下，浓雾竟化作云团将整个凉亭托在半空，而下方则是万家灯火。

桌上的菜肴不断在变幻，好似百姓家中的供品在轮流上桌。

你对此一边惊叹，一边与灶神闲谈，直到天亮，才重回地面离去。NOR]],["time"]=4,["title"]=[[HIR灶神星君NOR]]},["290"]={["id"]=290,["introText"]=[[HIW容貌清癯，风骨傲然，一代大侠之态显露无疑。NOR]],["itemId"]=[[mianju1023]],["name"]=[[HIR梅大侠NOR]],["need"]=25,["pic"]=[[Image/UI/AttrUI/mianju/meiniansheng1.png]],["thankText"]=[[YEL你方将珍品券递上，一位小二便从客栈中走出，拱手道：“梅大侠已经离去，不过少侠不必着急，我知道有条小路可助少侠追上梅大侠。”
你照小二所说找到小路，行至一个路口时忽然听见前方传来打斗声，你加紧前往，便见十几个山匪围住了一位身材高大老者。老者虽发须皆白但风骨依旧，立如苍松，势如猛虎，即使被十几个杀人如麻的山匪围困依旧泰然自若。
山匪们群起攻向老者，老者招似猛虎，剑似游龙，转瞬之间山匪便倒下一半。你从老者精妙的剑招回过神来，上前助他击败其余山匪。待山匪皆已倒下，老者收起重剑向你抱拳道谢，得知你是专门来寻他后便邀请你与他同行，你欣然同意。你们一起策马同行，你忽有预感自己将会收获良多。NOR]],["time"]=22,["title"]=[[BLU铁骨雪萼NOR]]},["291"]={["id"]=291,["introText"]=[[HIW身形魁伟，狂傲不羁，长须过肩，手持逍遥扇，一头飘逸银发随风飘扬。NOR]],["itemId"]=[[mianju1019]],["name"]=[[GRN丁老仙NOR]],["need"]=20,["pic"]=[[Image/UI/AttrUI/mianju/dingchunqiu.png]],["thankText"]=[[YEL 你将拜帖递上，两扇造型古朴的青铜大门被人推开，一众星宿弟子出门迎接，拱手抱拳，齐齐对你道一声：“少侠，老仙有请！”
一众弟子将你带到大殿内，左右手站成两排，躬身齐唱：“名宿毒仙，法驾中原，神通广大，法力无边！”你见上首坐着位灰发老者，气度非凡，似是神仙人物。老者坐定，大手一挥，两旁弟子立即噤若寒蝉。老者笑声洪浑，对你笑道：“哈哈哈！少侠特来拜访，老夫为你备了碗仙汤，包你喝了长生不老，日月同辉！”
你端过汤来，汤汁黑稠，腥臭无比。你硬着头皮，在众人的注视下一饮而尽，随后一股寒热从你腹部直上头皮，令你昏厥了过去……NOR]],["time"]=22,["title"]=[[HIB名宿毒仙NOR]]},["292"]={["id"]=292,["introText"]=[[HIW娇小可爱，玲珑剔透，所见之人无不心生怜爱。NOR]],["itemId"]=[[mianju1042]],["name"]=[[PNK玉兔NOR]],["need"]=10,["pic"]=[[Image/UI/AttrUI/mianju/yuetubai.png]],["thankText"]=[[YEL你将珍品券递上，片刻后自云间走下一位娇小玲珑的女子，她身着华服，头戴半面兔形面具，更显俏皮可爱。她走至你面前，轻笑了两声，声音清脆如铃，悦耳动听，她又说到：“少侠，随我来。”
你欣然同意，一朵白云就自她脚下升起，你小心翼翼地站了上去，白云便腾空而起，向着明月而去，转瞬就来到了一座华美的宫府前，宫门上有一白玉匾额，上刻广寒宫。
你随女子在宫中游览，宫府以水晶为阶，琉璃为瓦，白玉为墙，月光下熠熠生辉。宫里四处仙气渺渺，山石秀丽，奇花争艳，一步一景，一景一境，叫人应接不暇，
忽然你听见殿中传来悦耳仙乐，正欲前往却一脚踏空，你惊呼一声，景色倏然转换，变成了你熟悉的卧房。窗外月色清辉，原来方才只是一场梦罢了。NOR]],["time"]=22,["title"]=[[GRN捣药玉兔NOR]]},["293"]={["id"]=293,["introText"]=[[HIW风华绝代，烟视媚行，慵懒雍容中又有几分伟男子的英气，让人一见难忘。NOR]],["itemId"]=[[mianju1053]],["name"]=[[RED神教教主NOR]],["need"]=9,["pic"]=[[Image/UI/AttrUI/mianju/dongfangbubai.png]],["thankText"]=[[YEL你将珍品券递上，片刻后走出两位长袖青衫，黑纱蒙面的男子，向你拱手道：“教主有请！”
你随两位蒙面男子进入殿内，殿内宝座上正坐有一人，那人一身红衣，风华绝代，慵懒雍容之中又带有几分飒爽英姿，叫人一见难忘。他无需言语，只一抬眼，两位蒙面男子便心领神会的带你入座，端上美酒佳肴后就自行退下。
那人斜躺于宝座上，左手拿着一个绣花绷架，右手持着一枚绣花针，手指灵巧的运针引线。炎炎夏日，蚊虫纷扰，就在你们闲聊之间，飞来了一只苍蝇嗡嗡地扰人。你还未有所反应，只见银光一闪，那苍蝇便被一枚绣花针钉在柱上。转眼望去，他仍在穿针引线，似乎从未变过，你不由得赞叹其武功之高绝。NOR]],["time"]=22,["title"]=[[YEL神教教主NOR]]},["294"]={["id"]=294,["introText"]=[[HIW脸长面方，颏下微有须，颇有些豪放不羁的气质，此时正抱着个烧鸡，吃得正香。NOR]],["itemId"]=[[mianju1058]],["name"]=[[YEL老叫花NOR]],["need"]=7,["pic"]=[[Image/UI/AttrUI/mianju/hongqigong.png]],["thankText"]=[[YEL你递上珍品券，便见有一身着干净粗布衣的老者向你走来，老者豪迈一笑，向你说：“少侠，跟我来。”
你随老者绕过茅草屋向树林中走去，谈笑间，走到了一处流水潺潺的小溪边。老者招呼你在一块方石坐下，方石前是早已架好的柴堆。老者走向溪边，手中木棍挥舞间击起水花朵朵，几条河鱼就自水花中跃出落于地上。老者满意收棍，拾起河鱼手法熟练的处理好驾于火堆上。
诱人的香气飘出，待鱼肉焦黄，老者取下一条烤鱼给你，你迫不及待的咬了一口，鱼肉焦香，鲜美不已。老者又递予你一坛酒，你们开怀畅饮，不知时间流度。NOR]],["time"]=22,["title"]=[[MAG丐帮帮主NOR]]},["295"]={["id"]=295,["introText"]=[[HIW一黑一白的一对铁环，双环内嵌磁石，施展之时互为吸引，极富变化。若将内力灌注其中，磁力更盛，威力亦强。NOR]],["itemId"]=[[eq2020cz01]],["name"]=[[HIR乾坤双月环NOR]],["need"]=3,["pic"]=[[Image/UI/StoreUI/wuqi.png]],["thankText"]=[[YEL三尺龙泉剑，匣里无人见。
一张落雁弓，百支金花箭。
你沉吟不语，将珍品券捧于手上，似在心中思索着什么。
须臾间，空中一股浓雾飘散而来，遮蔽了你的视线。
待到浓雾散去，你蓦然发现，你的手上竟多了一件宝光四射的装备，而那张珍品券早已不知所踪。NOR]],["time"]=22,["title"]=[[HIW珍品装备NOR]]},["296"]={["id"]=296,["introText"]=[[HIW以昆仑山万年雪窟中的寒铁所铸造的长剑，长两尺三寸，锋利无比，每次出鞘都会散发出丝丝凉气。置剑于水中，可在水中凝出一层薄冰，故名凝水剑。NOR]],["itemId"]=[[eq2020cz02]],["name"]=[[HIC凝水剑NOR]],["need"]=3,["pic"]=[[Image/UI/StoreUI/wuqi.png]],["thankText"]=[[YEL三尺龙泉剑，匣里无人见。
