待到浓雾散去，你蓦然发现，你的手上竟多了一件宝光四射的装备，而那张珍品券早已不知所踪。NOR]],["time"]=22,["title"]=[[HIW珍品装备NOR]]},["3"]={["id"]=3,["introText"]=[[这是一套古老的刀法，由昔年一位异人于戊戌年所创，因而得名。戊者，草木繁盛也，戌者，万物灭尽也。]],["itemId"]=[[wuxudaofa]],["name"]=[[    HIY戊戌刀法NOR]],["need"]=10,["pic"]=[[Image/UI/StoreUI/shujuan1.png]],["thankText"]=[[YEL满月临弓影，连星入剑端。
