须臾间，空中一股浓雾飘散而来，遮蔽了你的视线。
待到浓雾散去，你蓦然发现，手上的武学名录已经变成了一本泛黄的武学秘籍，令你错愕不已。NOR]],["time"]=1,["title"]=[[全篇]]},["30"]={["id"]=30,["introText"]=[[WHT她就是山鬼。她长身玉立，美撼凡尘，乌羽作冠，赤羽霓裳，宛如山间精魅，不似人间凡物，令人一见难忘。NOR]],["itemId"]=[[mianju1109]],["name"]=[[RED山鬼NOR]],["need"]=5,["pic"]=[[Image/UI/AttrUI/mianju/shangui.png]],["thankText"]=[[YEL你将珍品券递上，片刻后，幽篁林出现一只毛色斑斓的花狸，颈间带有一串草织花环。花狸对着你轻咛示意。

你随花狸进入林中，走入一处山间洞穴，却见其中另有天地。神树擎天，溪水潺潺，仙雾渺渺，恍如仙境。一位清丽绝俗的女子立于神树前，向你微微颔首，淡淡地道：“这里不常有人来。”

待你入座，女子端上一盘鲜果，你浅尝一口，只觉果肉细腻、回甘无穷。女子又拿出一精致小鼓，随后轻语诵吟，击鼓和音。女子的歌声悦耳，曲调悠扬，你不由得闭眼聆听，刹那间你好似卧于云中，世间再无何事能将你牵绊，无拘无束地游于天地间。NOR]],["time"]=4,["title"]=[[HIB岁宴华予NOR]]},["300"]={["id"]=300,["introText"]=[[HIW假托《山海经》中异兽之名所铸的兵刃之一。铸造之人喜读异兽怪谈，又有炼制神兵之技，遂铸了一套兵刃，聊慰平生。NOR]],["itemId"]=[[eq2020xslb02]],["name"]=[[HIC孰湖NOR]],["need"]=3,["pic"]=[[Image/UI/StoreUI/wuqi.png]],["thankText"]=[[YEL三尺龙泉剑，匣里无人见。
