不学燕丹客，徒歌易水寒。
你沉吟不语，将珍品券捧于手上，似在心中思索着什么。
须臾间，空中一股浓雾飘散而来，遮蔽了你的视线。
待到浓雾散去，你蓦然发现，手上的珍品券已经变成了一本泛黄的武学秘籍，令你错愕不已。NOR]],["time"]=23,["title"]=[[全篇]]},["311"]={["id"]=311,["introText"]=[[WHT他生得身形挺拔，左颊一条刀疤，衬得眉目愈发粗犷，怀中抱着的长剑似乎刻满了久经江湖的沧桑之感。NOR]],["itemId"]=[[mianju1083]],["name"]=[[YEL赵武德NOR]],["need"]=23,["pic"]=[[Image/UI/AttrUI/mianju/zhaowude.png]],["thankText"]=[[YEL你将珍品券递上，片刻后出来一位高大威猛，身形挺拔的男子，他左颊一条刀疤，衬得眉目愈发粗犷。男子豪气一笑，叫你随他去。

你随着男子来到一处亭子，这亭子居然建在悬崖边上，涯边凛风呼啸，亭边仅有怪石嶙峋，全然一副萧杀之意。男子不知从何处掏出两壶好酒，将一壶扔予你，自己开了一壶，猛灌了一大口后，向你道：“倒是没想到你会来看我，今日我们不谈其他，只一醉方休！”

你们在涯边亭中开怀畅饮，确是不醉不归，直至繁星满天才有几名小厮前来将你们扶回各自房中休息。NOR]],["time"]=23,["title"]=[[HIR剑底亡魂NOR]]},["312"]={["id"]=312,["introText"]=[[WHT十分好看，甚至太好看了。看起来风尘仆仆，眼中有忧郁，笑里有阳光，是你永远得不到的那个浪子。NOR]],["itemId"]=[[mianju1063]],["name"]=[[HIB边城浪客NOR]],["need"]=16,["pic"]=[[Image/UI/AttrUI/mianju/yekai.png]],["thankText"]=[[YEL山衔阳辉云海乘，松盘石影浪客行。

你行走于高山云海之间，忽闻远处林影之下有人在呼喊：“少侠！少侠！此般美景为何急于赶路？何不坐下来与在下小酌几杯，将此美景尽收眼中呀！”

闻声望去，你见一位侠客正坐于树阴之中，此人背靠巨石，一只手将酒杯高举向着你慢慢摇晃。

走进观瞧，你发现此人眼中略带忧郁，但露出的笑容却堪比背后的暖阳。

你与此人席地而坐，浊酒而谈，良久日落云海，你与此人辞别，临别之际，你询问此人家住何方，此人却只是一饮杯中酒，潇洒踏步漫入云间。随着此人身影淡去，一句：“天下之大，美景如画，何须定所，自浪天涯。”从云海间传出，听闻你欣然一笑转身离去。NOR]],["time"]=23,["title"]=[[BLU天涯浪客NOR]]},["313"]={["id"]=313,["introText"]=[[WHT黑发如丝，眸色碧蓝，明艳不可方物，虽看似娇弱，但心性极高。有情者，无怨无悔，无情者，恩怨分明。因紫衫如花，胜如凌波，遂博得江湖美称，冠绝天下。NOR]],["itemId"]=[[mianju1096]],["name"]=[[RED明教圣女NOR]],["need"]=20,["pic"]=[[Image/UI/AttrUI/mianju/mingjiaoshengnv.png]],["thankText"]=[[YEL你将珍品卷递上，一位身着青纱绸罗的侍女推门而出：“少侠久等了，请随我来，圣女在里面等候。”侍女说罢，便欠身在一旁等待着你踏入院门。

你一路跟着侍女绕过院中花园，来到一处优雅僻静的亭台之中。亭台帷幔环绕，微风轻拂引得帷幔之下的领导发出清脆悦耳的响声。

帷幔之中，秀白的石桌旁端坐着一位身着华丽轻纱的曼妙女子。轻柔的薄纱遮面，女子俏丽的容颜若隐若现，千秋无绝色，悦目是佳人。

你落座于圣女面前，身旁的侍女将你二人的空杯斟满，伴随着浓郁的酒香你二人在此如仙境般的美景中谈笑风生。夜半时分，你辞别圣女，虽有一丝不舍，但今日的拜访却零珠片玉，如梦如幻。NOR]],["time"]=23,["title"]=[[PNK水龙吟NOR]]},["314"]={["id"]=314,["introText"]=[[WHT传闻他武功极高，曾与唐家唐不平交手三百回合不落下风。他面如冠玉，眉宇间英气十足，不怒自威，举手投足之间散发着一股慵懒之意。传言说其本是女儿身，但对外宣称为男人，以便行走江湖，统治帮派。NOR]],["itemId"]=[[mianju1099]],["name"]=[[HIM幽冥教主NOR]],["need"]=21,["pic"]=[[Image/UI/AttrUI/mianju/youmingjiaozhu1.png]],["thankText"]=[[YEL珍品券刚一递上，蓦然间你只听见一声低沉地耳语：“随我来。”声音如冷冽的寒潭，却让人分辨不出男女。你只觉腰间肋下被人裹挟住，随后身子一轻，整个人竟然腾空而起，向着某个方向凌空飞去。

迷迷糊糊间，你身后之人托着你飘然落地，你睁眼一看，竟来到一座阴森死寂的佛殿之中，殿中左右两侧各站着五尊巨大佛像，正是十殿阎罗王。

“无常善勾恶人命，七宝可避万般劫。既然少侠愿投拜帖于本座，本座便与少侠说一说这十殿阎罗的故事。”冷冽的声音从你背后响起，将每位阎罗的故事娓娓道来。

你虽然觉得有些惊怕，但却沉浸在这些鲜为人知的故事中，直至东方之际白。NOR]],["time"]=23,["title"]=[[MAG十殿阎罗NOR]]},["315"]={["id"]=315,["introText"]=[[WHT“词牌造物”之一。坊间传闻，词牌系列是干将莫邪技艺大成后的第一套作品，匠心独运浑然天成，有着巨大的收藏价值。NOR]],["itemId"]=[[eq2020cp17]],["name"]=[[HIC惜奴娇NOR]],["need"]=3,["pic"]=[[Image/UI/StoreUI/wuqi.png]],["thankText"]=[[YEL三尺龙泉剑，匣里无人见。
