待到浓雾散去，你蓦然发现，手上的珍品券已经变成了一本泛黄的武学秘籍，令你错愕不已。NOR]],["time"]=24,["title"]=[[全篇]]},["33"]={["id"]=33,["introText"]=[[WHT相传，此身法由赤练仙子根据天罗地网势所创，后流传于江湖。施展起来宛若赤蛇渡水，百转千回。NOR]],["itemId"]=[[chilianlingbobox1]],["name"]=[[RED赤练凌波NOR]],["need"]=15,["pic"]=[[Image/UI/StoreUI/shujuan2.png]],["thankText"]=[[YEL满月临弓影，连星入剑端。
不学燕丹客，徒歌易水寒。
你沉吟不语，将珍品券捧于手上，似在心中思索着什么。
须臾间，空中一股浓雾飘散而来，遮蔽了你的视线。
待到浓雾散去，你蓦然发现，手上的珍品券已经变成了一本泛黄的武学秘籍，令你错愕不已。NOR]],["time"]=5,["title"]=[[全篇]]},["330"]={["id"]=330,["introText"]=[[WHT须发浓密，和蔼可亲，是民间传说的土地之神，每年播种之际，百姓都会设坛祭祀，以求今年风调雨顺]],["itemId"]=[[mianju1102]],["name"]=[[HIY社神NOR]],["need"]=15,["pic"]=[[Image/UI/AttrUI/mianju/sheshen.png]],["thankText"]=[[YEL你将珍品券递上，随后便被浓雾环绕，下一刻，一幢华丽宏伟的建筑慢慢浮现。周围环境也渐渐在浓雾之中转变，放眼望去，你此时正处在一片云海之上，阳光穿透地面飘起的云雾，折射出耀眼的五彩之光。

片刻后，门匾刻有“社神府”字样的大门缓缓打开，其中隐隐走出一位须发浓密男人。只见此人面带微笑，将你带入社神府，进入府内你顿时被眼前从未见过的仙境美景所震撼。

你跟随社神在如梦如幻的仙境内神游，而社神则给你讲述了很多传说神话。

许久，你辞别社神，就在你沉醉游历美景之中时，周围的环境渐渐转换。

浓雾渐渐散去，眼前的社神府也慢慢隐匿于云雾之中。不多时，那宛如画卷般的仙境便消失不见，周围的一切也随之恢复如初。NOR]],["time"]=24,["title"]=[[HIR海晏河清NOR]]},["331"]={["id"]=331,["introText"]=[[WHT她就是沐临烟。她生得玉骨冰肌，古人若说起闺阁小姐、大家闺秀总归便是她这般的姿态。她虽能惊艳一堂，却少了与其他美人区分开来的特点。倘若真要说出个什么不同，便是她眼下泪痣，目中情深。但江湖，似乎并不需要这样娇滴滴的美人。NOR]],["itemId"]=[[mianju1094]],["name"]=[[RED沐临烟NOR]],["need"]=6,["pic"]=[[Image/UI/AttrUI/mianju/mulingyan.png]],["thankText"]=[[YEL你将珍品券递上，片刻后走出一位青衣侍女，恭敬道：“小姐有请。”
你随侍女穿过长廊，走到后院的花园中。你一眼便瞧见了那颗树冠红似火的红枫，脑海里不禁冒出那句“停车坐爱枫林晚，霜叶红于二月花。”
更引人注目的是红枫树下的那一抹蓝色身影，一位女子抱琴立于树下，她只略施粉黛，着靛青长裙，纤腰婀娜，宛若仙姝，不减神女。虽似莲花般清雅，但也带有寒梅的傲骨。
你们坐于红枫下，她问起你近况如何？在江湖闯荡可有受伤？又道你是她少有的朋友，随后她弹起一首新学的曲子。琴声婉转，似山泉自幽谷缓缓流淌而来，在你心头萦绕不去。NOR]],["time"]=24,["title"]=[[HIW江湖三友NOR]]},["332"]={["id"]=332,["introText"]=[[WHT浪荡洒脱，不修边幅，不似那些满带金银的富公子。样貌算不得英俊，但明眸清澈，笑意盎然。且既为侠盗，从不多取一毫，乃这盗中清官，两袖空空。NOR]],["itemId"]=[[mianju1097]],["name"]=[[YEL萧侠盗NOR]],["need"]=12,["pic"]=[[Image/UI/AttrUI/mianju/xiaoxiadao.png]],["thankText"]=[[YEL你将珍品券递上，忽感微风阵阵，林间枝叶簌簌，一道侠影由远及近，甚是潇洒。

走近身前，萧侠盗略带轻浮般的说道：“这位少侠，虽不知何由，但对你有着一种似曾相识的感觉，不知少侠可愿陪我在这翠林之中走走。”

你二人来到林中空地之上，一张青苔斑驳的石桌被落叶覆盖，露出灰白一角。

你二人对坐于此，夕阳西下。萧侠盗饮尽壶中最后一口烈酒，伴随着他清唱着的一首悲凉唱词，消失在茵茵竹林之中。你坐在石凳上，回忆着方才听来的有关一对侠侣逍遥江湖的故事。

林中唱词远去，微风轻抚，枝叶簌簌作响。石桌不远处，一把锈迹斑驳的铁剑插在地上，剑柄上，一条鲜艳的红色飘带随风舞动，好似故事中的女侠，曼舞于这软玉般的翠绿之间。NOR]],["time"]=24,["title"]=[[MAG狼心独怆NOR]]},["333"]={["id"]=333,["introText"]=[[WHT略有几分儒雅，但多年身处江湖又给人一种饱经沧桑之感。面色冷峻，杀伐果断，极重仁义却为达目的又不择手段，是个十分矛盾的人物。NOR]],["itemId"]=[[mianju1091]],["name"]=[[HIB任天南NOR]],["need"]=9,["pic"]=[[Image/UI/AttrUI/mianju/rentiannan.png]],["thankText"]=[[YEL你将拜帖递上，山门弟子检阅后将你带入山门。你跟随守门弟子行走于伏龙山曲折的石阶之上，周围众山嶙峋，有种异样的美感。

山门弟子将你带到一座阁楼前，接着对你说道：“少侠，帮主此时就在雅阁之中，你自行进去便可”。山门弟子对你一礼便转身离去。

你推开雅阁大门，见任天南正坐于桌前，杯中清茶飘出淡淡幽香，弥漫在大厅之中。见你来此，任天南示意你落座，随即一旁的弟子将你面前的茶杯斟满。

任天南收起书卷，略带赏识的打量着你，随后便说道：“少侠，今日你拜访我伏龙山，我们便不论江湖之事。”

你与任天南以茶代酒，娓娓而谈。虽各执己见，但也莫衷一是。故而你二人谈论良久，直至傍晚时分，你才辞别离去。NOR]],["time"]=24,["title"]=[[BLU独掌江南NOR]]},["334"]={["id"]=334,["introText"]=[[WHT他就是沈元龙，金钱帮经营酒楼生意的行首。
他本是秀才出身，多年前受老会首之恩，放弃科考，转而报答金钱帮。
有人笑说他不是个商人，但随着金钱帮酒楼生意日益兴盛，再没有人提及过此事。NOR]],["itemId"]=[[mianju1074]],["name"]=[[HIW沈元龙NOR]],["need"]=8,["pic"]=[[Image/UI/AttrUI/mianju/shenyuanlong.png]],["thankText"]=[[YEL你将珍品券递上后，金钱帮的小厮将你迎了进去。
不过一盏茶的功夫，一个略微清瘦的男子半敛着衣袖走了出来，朝你拱手道：“有失远迎。”
你正欲开口，却发现他的衣袖间沾染了点点墨痕，沈元龙顺着你的目光抬袖一看，羞赧笑道：“失礼失礼，匆忙见客连沾了墨痕也不自知。”
江湖传闻中的沈元龙，既是索债催命的恶鬼，亦是乐善好施的贤者，但此刻于你而言，他不过是好客的账房先生，兴许平日里还会吟上几句诗书。
你们随后谈了很多江湖中的趣事，兴尽方归。NOR]],["time"]=24,["title"]=[[RED铁算行首NOR]]},["335"]={["id"]=335,["introText"]=[[WHT眉目如画，虽穿着一身寻常粗布麻衣，却有种卓尔不群、宠辱不惊的气质，玩味地打量着周围，似乎早已世事洞明、曾经沧海。NOR]],["itemId"]=[[mianju1081]],["name"]=[[HIC车夫NOR]],["need"]=7,["pic"]=[[Image/UI/AttrUI/mianju/chefu.png]],["thankText"]=[[YEL你将珍品券递上，随后一阵马蹄和车轮声由远及近，车前一个身穿粗布麻衣，头戴斗笠的中年男子手握缰绳将车马停在你面前。从他卓尔不群的气质不难看出，此人似乎早已世事洞明。

车夫对着你招了招手，略带玩味的说道：“这位少侠，是否有雅兴跟在下一同远行一番？”你思索片刻便登上了马车，随后骏马一声嘶鸣，车轮飞转，你二人此便疾驰而去。

旅途中，你见了许多自然奇景，也感受了一番从不知晓的风土人情。而车夫依旧是宠辱不惊，玩味般的经历着一切，仿若这般对你如此新鲜的事景对他而言早已麻木一般。

辞别车夫，在骏马嘶鸣和车轮急转声中，这位好似曾经沧海的神秘车夫扬长而去，留下一阵洒脱自在的烟尘。NOR]],["time"]=24,["title"]=[[HIM无所不至NOR]]},["336"]={["id"]=336,["introText"]=[[HIW假托《山海经》中异兽之名所铸的兵刃之一。铸造之人喜读异兽怪谈，又有炼制神兵之技，遂铸了一套兵刃，聊慰平生。NOR]],["itemId"]=[[eq2020xslb09]],["name"]=[[HIR虎蛟NOR]],["need"]=3,["pic"]=[[Image/UI/StoreUI/wuqi.png]],["thankText"]=[[YEL三尺龙泉剑，匣里无人见。
一张落雁弓，百支金花箭。
