待到浓雾散去，你蓦然发现，手上的珍品券已经变成了一本泛黄的武学秘籍，令你错愕不已。NOR]],["time"]=25,["title"]=[[全篇]]},["349"]={["id"]=349,["introText"]=[[WHT聘婷秀雅，螓首蛾眉。似手中利剑般凌厉，又似远山般内敛沉稳，让人一见难忘。NOR]],["itemId"]=[[mianju1173]],["name"]=[[YEL白剑枫NOR]],["need"]=20,["pic"]=[[Image/UI/AttrUI/mianju/baijianfeng.png]],["thankText"]=[[YEL你将珍品券递上，片刻后，山门内走出一位峨眉弟子，她拱手施了一礼，轻声道：“师姐在后山习武，请少侠随我来。”
你跟着峨眉弟子走入山门，转转绕绕来到了后山上。一眼便瞧见一蓝衣女子于古松下习剑，一招一式皆清爽凌厉。见你来到，女子收剑入鞘，邀你至一旁的亭子入座。
女子不过花信年华，眉眼间却以带有几分宝相神尼的威仪，让你不由得心生敬佩。你们品茶论道，直至山间染上红光才知时光流逝。见此时已是日落时分，你便告辞离去。NOR]],["time"]=25,["title"]=[[HIW江湖三友（四）NOR]]},["35"]={["id"]=35,["introText"]=[[WHT这是一种暗器武学，据说由一位峨嵋派的高手所创，多年来一直在江湖中小范围流传。NOR]],["itemId"]=[[tiannvsanhuashou]],["name"]=[[PNK天女散花手NOR]],["need"]=6,["pic"]=[[Image/UI/StoreUI/shujuan4.png]],["thankText"]=[[YEL满月临弓影，连星入剑端。
不学燕丹客，徒歌易水寒。
