待到浓雾散去，你蓦然发现，手上的珍品券已经变成了一本泛黄的武学秘籍，令你错愕不已。NOR]],["time"]=5,["title"]=[[全篇]]},["350"]={["id"]=350,["introText"]=[[WHT杏眼桃腮，明眸善睐。脸上总带着温婉的笑意，颇为惹人怜爱。NOR]],["itemId"]=[[mianju1174]],["name"]=[[YEL秋月NOR]],["need"]=19,["pic"]=[[Image/UI/AttrUI/mianju/qiuyuebai.png]],["thankText"]=[[YEL你方将珍品券递上，一个老管家便迎了上来。你随他来到前厅，在那与朱馆主寒暄了一会，正欲告辞离开却见天色忽暗，一副风雨欲来之景。朱馆主叹了口气道：“最近这天总是如此，变化无常。少侠不如在此歇息一晚，待明日天晴再启程改路吧。”
刚进客房便见桌脚边落有一白色帕子，帕上绣着“秋月”二字。秋月是朱府丫鬟，这许是她不小心遗落的。你叫住老管家问起秋月所在，谁知老管家脸色一变，只含糊了两句便离开了。
夜深，后院忽传出一声惊叫，你发觉一人影从窗外跑过。你即刻起身，追着人影来到池边。池边阴凉，只见一娇小女子立于水面。她长发披散，十指尖利，黑仁红瞳，邪气森然。“少侠，可还记得我？”NOR]],["time"]=25,["title"]=[[HIW江湖三友（四）NOR]]},["351"]={["id"]=351,["introText"]=[[WHT平平无奇，普普通通，但周身诡秘的气质却叫人无法忽视，即使身处攘攘闹市、茫茫人海中也能叫人一眼找到。NOR]],["itemId"]=[[mianju1172]],["name"]=[[YEL黑商NOR]],["need"]=18,["pic"]=[[Image/UI/AttrUI/mianju/heishishangren.png]],["thankText"]=[[YEL你将珍品券递上，很快走出一位黑衣小厮，弓腰说道：“少侠往里请。”
你一路走进，发现这住宅与普通富户并无区别，只是缺了些烟火气，似乎不常有人居住。
见到黑商后，他邀你坐下品茶，随即说道：“少侠难得来我府上做客，今日不谈生意，只当与友人叙旧。”
一番闲聊，你二人竟无冷场的时候，直到天亮，你方起身离开。NOR]],["time"]=25,["title"]=[[HIW江湖三友（四）NOR]]},["352"]={["id"]=352,["introText"]=[[WHT普普通通，就像沙漠中的一粒沙子，看似平平无奇，但其钻营吊诡的气质总让人难以忽视，就算是沙子，也是最刺眼的那一粒，茫茫人海中，一眼就看到。NOR]],["itemId"]=[[mianju1065]],["name"]=[[YEL黑市商人NOR]],["need"]=10,["pic"]=[[Image/UI/AttrUI/mianju/heishangbaitian.png]],["thankText"]=[[YEL黑市商人向来踪迹难寻，你只能将珍品券依照江湖传闻置于一家商铺之中。
一日后，有人寻到了你，并送上了一封信函相约你至酒楼一叙。
你等候多时，期间小酌了几杯，只见酒楼外车马往来甚是热闹，再一转头黑市商人已经悄无声息地安坐在你面前。
“让阁下久候实在过意不去，在下自饮一杯聊表歉意。”黑市商人端起酒杯，探入了头上戴着的黑纱斗笠中。
随后菜席满布，你们闲聊江湖，甚是惬意。NOR]],["time"]=25,["title"]=[[HIW江湖三友（三）NOR]]},["353"]={["id"]=353,["introText"]=[[WHT假托《山海经》中异兽之名所铸的兵刃之一。铸造之人喜读异兽怪谈，又有炼制神兵之技，遂铸了一套兵刃，聊慰平生。NOR]],["itemId"]=[[eq2020xslb03]],["name"]=[[HIR鹿蜀NOR]],["need"]=3,["pic"]=[[Image/UI/StoreUI/wuqi.png]],["thankText"]=[[YEL三尺龙泉剑，匣里无人见。
