你随女子来到草原上。草原辽阔，无边无际，雄鹰在蓝空翱翔，牛羊在闲散漫步。见此美景，你心中也不禁涌起壮阔之感。女子牵拉两匹骏马，将一匹骏马的缰绳递给你。女子利落的翻身上马，问到：“少侠敢不敢与我一比？”你自信一笑，也翻身上马，回了句：“有何不敢!”

你们骑着骏马在草原驰骋，如雄鹰在天上展翅翱翔般，自由自在，无拘无束，好似天地间再无何物可以拦住你们的脚步。]],["time"]=5,["title"]=[[RED绚若红玫NOR]]},["360"]={["id"]=360,["introText"]=[[WHT这是一颗天工石,可以用于提升装饰箱的容量。NOR]],["itemId"]=[[tiangongshi1]],["name"]=[[天工石]],["need"]=2,["pic"]=[[Image/UI/StoreUI/zhuzi.png]],["thankText"]=[[YEL赤点朱饰韵味飘远,真才天工赏心悦目。
