待到浓雾散去，你蓦然发现，手上的珍品券已经变成了一本泛黄的武学秘籍，令你错愕不已。NOR]],["time"]=26,["title"]=[[全篇]]},["37"]={["id"]=37,["introText"]=[[WHT他就是杨总管。他生得娇艳，身穿一身枣红色缎面长袍，眼波流转之间，神态竟要比女子还要妩媚三分。]],["itemId"]=[[mianju1098]],["name"]=[[HIR杨总管NOR]],["need"]=15,["pic"]=[[Image/UI/AttrUI/mianju/yangzongguan.png]],["thankText"]=[[YEL你将珍品券递上，片刻后走出两位长袖青衫，黑纱蒙面的男子，向你拱手道：“总管有请！”

你随两位蒙面男子进入殿内，只见殿内早已备好宴席。一个身着枣红色缎面长袍，身形妖娆的男子坐于桌前。男子起身邀你入座，轻轻一挥手，道了句：“上酒吧。”两位蒙面男子毕恭毕敬的端上好酒，为你们斟上。

你与男子推杯交盏间，相谈甚欢。惊风飘白日，光景西驰流，眼看日头西沉，你也只得告辞离去。]],["time"]=5,["title"]=[[YEL天人化生NOR]]},["370"]={["id"]=370,["introText"]=[[WHT江湖上传闻她是峨眉叛徒，与柳玄风同为一伙。她一身青衫，容貌甚美，因幼时一段坎坷的经历，致使她变得冷漠寡言，唯独信任依赖于情人韩一枫。她行踪不定，其背后势力复杂难明，因她的存在，武林常起波澜]],["itemId"]=[[mianju1078]],["name"]=[[HIY狄水清NOR]],["need"]=25,["pic"]=[[Image/UI/AttrUI/mianju/dishuiqing.png]],["thankText"]=[[YEL你将珍品券递上，忽听见里面打斗叱喝之声，你正感疑惑时，一阵风夹裹着几张薄纸吹落至你脚边。

你粗略看见上面的“门派秘典”四字，狄水清已从竹林中走出，打斗声也随之停止，原来刚才是她在演练武功。

见你对这些纸张并无抢夺之意，她目光复杂，将薄纸拾起后，颔首请你进屋。

一番拜访结束，你回想起今日与她共处的时光，恍然发现她对你倒比从前话多了那么一点。]],["time"]=26,["title"]=[[HIC冰兰霜华NOR]]},["371"]={["id"]=371,["introText"]=[[WHT她孤傲清冷，姿容绝代，着一身朱红色的骑士服，持剑而立，如同荆棘丛中的玫瑰，令人着迷又难以接近NOR]],["itemId"]=[[mianju1093]],["name"]=[[YEL卡米尔NOR]],["need"]=15,["pic"]=[[Image/UI/AttrUI/mianju/kamierbaitian.png]],["thankText"]=[[YEL你将珍品券递上，片刻后，大门被人推开，走出一位身着朱红骑士服，步履轻快、清艳脱俗的异国女子。女子莞尔一笑，向你说了句：“少侠，久等。”

你随女子走进后院，发现后院是以玫瑰花丛作墙，院中立有一座白色石亭，此时正值花开之际，院里花香清幽。女子邀你到亭中入座，随后唤仆人端上花茶糕点。花茶清香甘甜，糕点入口即化，细腻甜津，难得尝此异国美食，你不禁多食了些。

女子与你饮茶赏花，畅谈天地。当谈及武学经历之时，你二人兴致所起，在院中比划起来。棋逢对手，将遇良才，你二人放开了手脚，酣畅淋漓的比试了一番。]],["time"]=26,["title"]=[[HIY月光蔷薇NOR]]},["372"]={["id"]=372,["introText"]=[[WHT剑眉星目、气宇轩昂，行如风、站如松，大碗喝酒、大块吃肉，虽出身草莽，却胸有丘壑、心怀天下]],["itemId"]=[[mianju1067]],["name"]=[[章作之]],["need"]=9,["pic"]=[[Image/UI/AttrUI/mianju/zhangzuozhi.png]],["thankText"]=[[YEL大雪纷飞，你落座于一家酒馆歇息。刚踏入酒馆便听二楼传来阵阵爽朗且熟悉的笑声。
你走上二楼，就见章作之正与一个高大的男人比试臂力。见你来此，章作之轻松赢下男人向你走来。
你二人找了一个僻静的角落，美食美酒尽显桌上。看着窗外纷飞的白雪，章作之却突然叹息，你不解便询问为何，章作之只是淡淡一笑：“少侠你可知道在这雪景之中，仍有人食不果腹，衣不蔽体，想章某空有一身本领，但却无可作为，真是...哎...”
酒过三巡，风淡雪息，章作之拿起佩剑，与你告别后潇洒离去，看着远去的章作之，你不禁回想酒桌之上他那一席藏有深意的叹息，你无奈的摇了摇头，饮尽杯中余酒，与那一道蓝影背道而行。NOR]],["time"]=26,["title"]=[[MAG江湖三友（一）NOR]]},["373"]={["id"]=373,["introText"]=[[WHT她容貌绝色，如仙人白玉，秀丽绝伦，明艳绝伦，娇美不可方物NOR]],["itemId"]=[[mianju1029]],["name"]=[[盈姑娘]],["need"]=9,["pic"]=[[Image/UI/AttrUI/mianju/renyingying.png]],["thankText"]=[[YEL你将珍品券递上，片刻后走出两位长袖青衫，黑纱蒙面的男子，向你拱手道：“圣姑有请！”

你随两位蒙面男子进入偏殿之中，只见殿中站着一位姿容艳丽，秀丽绝伦的女子。女子轻轻一拂手，道了一声：“出去吧。”两位蒙面男子便毕恭毕敬地退出殿外。

见场中除你二人外并无他人，女子掏出一杆碧绿洞箫，放在唇边轻轻吹奏。十指如兰花飞扬，曲调随之而变化，音律传入耳中，刹那间你只觉滔滔江水滚滚而来，忽高忽低，忽快忽慢，片刻后蓦然一收，仿佛天地风雨尽数散去，令你久久不能平息。]],["time"]=26,["title"]=[[RED日月圣女NOR]]},["374"]={["id"]=374,["introText"]=[[WHT她面似寒霜、不苟言笑，横眉之下眸光清冷，虽双颊微红却不染俗世脂粉，一举一动足显大家风范，无半点媚态，可敬可畏NOR]],["itemId"]=[[mianju1080]],["name"]=[[HIB师太NOR]],["need"]=6,["pic"]=[[Image/UI/AttrUI/mianju/miejue.png]],["thankText"]=[[YEL据传峨眉山上有一处峰顶终年积雪，风霜如刀刺骨，非常人能往。你递上拜帖，依此凭证进入该地，天地一片白茫的寒气中，一道人影坐在万丈边悬崖边盘腿打坐。
听到脚步声响，她倏然睁开双眼，眸光似两道寒芒向你疾射而来，你立即行礼以晚辈自称，她放缓神色，邀你在此练功，试一试这冰霜险境的威力。
你随即打坐入定，运全身内力抵御寒气入侵，同时抛开杂思保持心如止水，以免不慎坠入悬崖。
你打坐一日，仿佛渡过几年光阴，练功结束后直叹：能面不改色日日这般苦练，前辈实乃意志坚定之人。
你心生佩服，亦有所获，向她答谢后下山，天晚寒意更浓，那道立在山尖风雪里的身影浑然如玉石所铸。NOR]],["time"]=26,["title"]=[[YEL峨眉执剑NOR]]},["375"]={["id"]=375,["introText"]=[[WHT身材甚高，风姿飒爽，英气勃勃，飘逸绝伦]],["itemId"]=[[mianju1043]],["name"]=[[王真人]],["need"]=4,["pic"]=[[Image/UI/AttrUI/mianju/wangchongyang.png]],["thankText"]=[[YEL你将珍品券递上，片刻后门内走出一个道童对你抱拳一礼道：“少侠请进，真人在后山福地等你。”
      你随道童来到后山，此地百花争艳，林中更是莺歌阵阵。一旁山泉顺势而下，升腾的水雾让此地如梦如幻。
      你与王真人在此美景之中彻谈功法大道，良久，茶尽杯空，王真人执剑于手，舞出一套无比精妙的剑法，其剑招玄妙，每一式中都蕴含着无数微妙之变，让你叹为观止，心生敬畏。
就在套剑法最后一式击出之时，落英掌门执剑由你身后飞跃而出，其剑势狠厉剑法精妙，瞬间将王真人这最后一式化解。王真人见落英掌门淡淡一笑，随后专攻为守，化解了落英掌门紧随的几招。这二人亦攻亦守，长剑相接发出清脆之音，好生自在。你见二人兴致正浓便不再打扰转身伴霞而去。NOR]],["time"]=26,["title"]=[[BLU全真祖师NOR]]},["376"]={["id"]=376,["introText"]=[[WHT容貌极美，秀眉入鬓，清雅高华，难以言喻]],["itemId"]=[[mianju1044]],["name"]=[[落英掌门]],["need"]=4,["pic"]=[[Image/UI/AttrUI/mianju/linchaoying.png]],["thankText"]=[[YEL“惟有归于‘无缘’二字，却不知无缘系‘果’而非‘因’。”
你刚将手中的珍品券递上，便听身后传来一个苍老声音，回头看去，却不见其人。随之一旁的院门缓缓推开，落英掌门身着红裳，施施而行。
见你立于门前，落英掌门绝美容颜上显出一抹微笑：“不知少侠今日来此所为何事？今日我邀请王真人来府中商议要事，只怕要让少侠要等上片刻了。”
你与落英掌门相谈于院亭中，不多时门外跑来一个道童，道童将一封书信交予落英掌门后便匆匆离去。拆开书信，落英掌门的神色由失落渐渐转变为愤怒，直到看完书信中的内容，她的脸上尽显无奈。
道童送来书信被她攥握手中，看着园中飘落的秋叶，落英掌门竟有些木讷，口中呢喃：“好一个家国未定，何以为家。”NOR]],["time"]=26,["title"]=[[PNK古陵祖师NOR]]},["377"]={["id"]=377,["introText"]=[[WHT刻着游龙的镀金船桨，桨端有数十个斜棱，挥舞起来虎虎生风，威力十足NOR]],["itemId"]=[[2020duanwu1]],["name"]=[[MAG玉龙桨NOR]],["need"]=3,["pic"]=[[Image/UI/StoreUI/wuqi.png]],["thankText"]=[[YEL三尺龙泉剑，匣里无人见。
一张落雁弓，百支金花箭。
你沉吟不语，将珍品券捧于手上，似在心中思索着什么。
须臾间，空中一股浓雾飘散而来，遮蔽了你的视线。
待到浓雾散去，你蓦然发现，你的手上竟多了一件宝光四射的装备，而那张珍品券早已不知所踪。NOR]],["time"]=26,["title"]=[[HIW珍品装备NOR]]},["378"]={["id"]=378,["introText"]=[[WHT据称是屈原的佩剑。屈原投汨罗江后，楚人从江中打捞出此剑。历经千年，依然极为锋利NOR]],["itemId"]=[[2020duanwu3]],["name"]=[[HIC天问剑NOR]],["need"]=3,["pic"]=[[Image/UI/StoreUI/wuqi.png]],["thankText"]=[[YEL三尺龙泉剑，匣里无人见。
