你随老者绕过茅草屋向树林中走去，谈笑间，走到了一处流水潺潺的小溪边。老者招呼你在一块方石坐下，方石前是早已架好的柴堆。老者走向溪边，手中木棍挥舞间击起水花朵朵，几条河鱼就自水花中跃出落于地上。老者满意收棍，拾起河鱼手法熟练的处理好驾于火堆上。

诱人的香气飘出，待鱼肉焦黄，老者取下一条烤鱼给你，你迫不及待的咬了一口，鱼肉焦香，鲜美不已。老者又递予你一坛酒，你们开怀畅饮，不知时间流度。]],["time"]=5,["title"]=[[GRN丐帮帮主NOR]]},["380"]={["id"]=380,["introText"]=[[WHT制成枣核形状的独门暗器，两端尖中腹鼓。可投掷发射，但据称有一高手将此物藏于口中，以内力吐射，叫人防不胜防NOR]],["itemId"]=[[2020duanwu7]],["name"]=[[HIC枣核钉NOR]],["need"]=3,["pic"]=[[Image/UI/StoreUI/wuqi.png]],["thankText"]=[[YEL三尺龙泉剑，匣里无人见。
