待到浓雾散去，你蓦然发现，手上的珍品券已经变成了一本泛黄的武学秘籍，令你错愕不已。NOR]],["time"]=27,["title"]=[[全篇]]},["391"]={["id"]=391,["introText"]=[[HIW不怒自威，威风凛凛。眼神犀利，散发着一股浓重的杀气。体格精瘦，举手投足之间散发着一股宗师气质NOR]],["itemId"]=[[mianju1105]],["name"]=[[HIY唐不平NOR]],["need"]=16,["pic"]=[[Image/UI/AttrUI/mianju/tangbuping.png]],["thankText"]=[[YEL你将拜帖递上，随后便跟随唐门弟子进入山庄。随着唐门弟子引路，你二人穿行于山庄内，一路上你见到了不少奇珍异草和精妙机关。
     你随唐门弟子来到山庄内一处僻静的庄园，随后弟子告退。你轻敲门环，应声走出一位蕴含风情的女人，她对着你轻笑颔首，将你带入门中。
     庭院内，百花繁茂，竹林翠影。唐不平身穿青灰长衫，手中暗器寒芒利利。在他对面的年轻男子全神贯注看着唐不平的一招一式，而一旁的亭台内，一位如花似玉的妙龄少女拨弄琴弦，古琴声悠扬婉转，悠游自在。
     傍晚时分，唐不平将你送出山庄。夕阳之下，你二人踏步晚霞，可唐不平的脸上尽显惆怅。此刻无话，只因同为置身江湖的你明了此刻唐不平心中的怅惘。NOR]],["time"]=27,["title"]=[[HIC飒沓流星NOR]]},["392"]={["id"]=392,["introText"]=[[HIW清雅秀丽，楚楚动人。少女盈盈十六七岁年华，身穿花红，肌肤雪白，眼底似有泪痕。眉毛微蹙，令人暗生情愫，如泣如诉，直叫人牵肠挂肚NOR]],["itemId"]=[[mianju1126]],["name"]=[[GRN朱姑娘NOR]],["need"]=15,["pic"]=[[Image/UI/AttrUI/mianju/azhu.png]],["thankText"]=[[YEL接过珍宝帖之时，她双目含泪，满面凄苦，似乎遇上了什么难事。你心有不忍，转而向她问询之时，她却闪烁其词。你方才想起，这些时日她跟丐帮的那位英雄人物逃亡天下闹得江湖皆知，眼下情景可能就是跟那位英雄有关，便试探地问了一句，“是因为萧英雄吗？”
“不，大哥他对我很好，是我......我不能再陪着他了。”一语说罢，似乎耗尽了她全部的气力，不管你再如何安慰，她始终是黯然垂首不发一言。你陪她静默良久，最终选择告辞离去。
出门之际，你依稀听到了她的低语，“只能下辈子再陪你塞上牧牛放羊了。”NOR]],["time"]=27,["title"]=[[BLU朱颜碧玉NOR]]},["393"]={["id"]=393,["introText"]=[[HIW面目可怖，一对乌黑的牛角泛着冷光，一双铜铃般的大眼睛，眼神森寒不带一丝情绪，看所有人都像看将死之人一般NOR]],["itemId"]=[[mianju1069]],["name"]=[[HIR牛头NOR]],["need"]=5,["pic"]=[[Image/UI/AttrUI/mianju/niutou.png]],["thankText"]=[[YEL你将拜帖递上，随后酆都幽城城门打开，阴寒之气由内涌出让你不禁打了个冷颤。
     你提着白纸灯笼穿行于街道之间，忽然随着一阵锁链响动，你被撞倒在地。待你回过神来这才发现，面前一个长着牛头身着官服的家伙正满脸焦急的看着你，牛头将你扶到一旁的茶馆，浓茶入喉，刚才焦急不堪的牛头也逐渐缓下心来。
     牛头告诉你自己是忙于追捕逃出的恶鬼这才如此莽撞，而此事和自己那嗜酒如命的搭档有关。如今他喝酒误事，人又不见踪影，当下牛头也不知如何是好。
     听闻你便决定帮助此人捉拿恶鬼，牛头见你愿意帮忙脸上的愁容也少了几分。就在你起身要走出茶馆之时，身边的景物竟然突然开始模糊，随后你迷迷糊糊从桌上醒来，一旁还放着打翻美酒和一副牛头面具。NOR]],["time"]=27,["title"]=[[RED牛头马面NOR]]},["394"]={["id"]=394,["introText"]=[[HIW一头飘逸的鬃毛，瘦长的马脸下是一口白牙，看起来既可怕又带点滑稽，鼻孔里不时喷出的凛冽白气，时刻提醒着生人勿近NOR]],["itemId"]=[[mianju1070]],["name"]=[[YEL马面NOR]],["need"]=5,["pic"]=[[Image/UI/AttrUI/mianju/mamian.png]],["thankText"]=[[YEL你将拜帖递上，随后酆都幽城城门打开，阴寒之气由内涌出让你不禁打了个冷颤。
     走过巷子你发现里面一个烂醉如泥的家伙正呼呼大睡，你不忍好奇将他盖在头上的箩筐拿下这才发现此人竟然长着一个马头。
     马面迷迷糊糊坐起身，嘴里还不断嘟囔。见你正蹲在一旁，马面这才意识到自己的失态略显严肃的询问你身份。
     看着一旁空落落的锁链马面似乎突然想起了什么赶忙询问你是否看见一个青面獠牙的恶鬼，对此你也有些迷茫，马面这才懊悔的告诉你自己本应该带着恶鬼去找牛头交差，但途中垂涎美酒误了正事。
     你决定帮助马面一起寻回恶鬼，正当你二人走出巷口时，你顿感周围景物模糊，随后你便从桌上醒来，一旁被打翻的美酒正散发着勾人的香气。NOR]],["time"]=27,["title"]=[[RED牛头马面NOR]]},["395"]={["id"]=395,["introText"]=[[HIW满脸皱纹，疲惫不堪，穿一身普通的蓝布衫，于人群中再寻常不过，但看上去十分亲切NOR]],["itemId"]=[[mianju1086]],["name"]=[[BLU武馆老管家NOR]],["need"]=8,["pic"]=[[Image/UI/AttrUI/mianju/wuguanlaoguanjia.png]],["thankText"]=[[YEL你将拜帖递上，金牛武馆的门被老管家推开，将你迎入馆中。
     你二人来到后院，只见擂台上两人正在切磋武艺，招招犀利，干净利落。周围的观众爆发出震耳的掌声和叫好声，见一方败退你便兴奋的冲上擂台。
     你一连打败数名挑战者，休息之时，老管家告诉你，今日举办的是比武招亲，最终夺魁的人要迎娶佳人。听到这话你慌了神，方才只顾着切磋比试，根本没有注意到一旁高台上身着红衣的女子。
     新一轮比武开始，你故意露出破绽，最终落败。你暗自庆幸跟随老管家来到偏厅歇息。比武一直持续到傍晚，听老管家说，最终夺魁的人好像是红衣女子爱慕已久的侠客。
     辞别老管家，看着天边的晚霞，你的脑海中竟浮现出一副侠侣浪迹天涯的景象，你淡淡一笑，转身离去。NOR]],["time"]=27,["title"]=[[HIY少侠你好NOR]]},["396"]={["id"]=396,["introText"]=[[WHT这是一根九节鞭，以青色细鞭节连缀而成的九节鞭，可折叠藏于腰间NOR]],["itemId"]=[[eq2020qm01]],["name"]=[[HIG清明柳NOR]],["need"]=3,["pic"]=[[Image/UI/StoreUI/wuqi.png]],["thankText"]=[[YEL三尺龙泉剑，匣里无人见。
