你沉吟不语，将珍品券捧于手上，似在心中思索着什么。
须臾间，空中一股浓雾飘散而来，遮蔽了你的视线。
待到浓雾散去，你蓦然发现，手上的珍品券已经变成了一本泛黄的武学秘籍，令你错愕不已。NOR]],["time"]=28,["title"]=[[全篇]]},["411"]={["id"]=411,["introText"]=[[HIW面似寒霜，冷傲逼人。一对墨眉有如柳叶般纤细，一双眼眸好似狐狸般狭长，手握单刀，飞雪飘飘，冰冷的眼神散发出似有若无的杀意，直令人胆寒。NOR]],["itemId"]=[[mianju1127]],["name"]=[[HIB胡大侠NOR]],["need"]=24,["pic"]=[[Image/UI/AttrUI/mianju/hufei.png]],["thankText"]=[[YEL寒冬腊月，飞雪纷纷，你根据百晓生的指引独自北上，前往长白山深处去寻找那道侠影。

雪地中，男子舞着手中的长刀，他身形腾挪，刀影翻飞，灵动迅捷，犹如雪狐般机敏。舞至精彩处，你忍不住叫了声“好”，他循声向你望来，或许是你手中的珍宝券，让他冷峻的神色稍稍缓和。只见他身影几下闪动便到了你跟前，他手中黑刀径直向你横削而来，只是出刀的速度比上先前却是慢了几分，你心下了然，拔出长剑向他攻去。

拆招五百余合，不分胜负，你们哈哈一笑罢手停战，拿出酒壶痛饮一番。你醉倒之前，依稀还记得他轻唱的歌谣，“来日大难，口燥舌干。今日相乐，皆当喜欢。”NOR]],["time"]=28,["title"]=[[HIW雪山侠行NOR]]},["412"]={["id"]=412,["introText"]=[[HIW双眸灵动，脉脉含情。相貌似有十六七岁年纪，身形却娇小如十三四岁的小姑娘。在万花的簇拥之下，抬手轻轻折下一枝，细嗅花香，尽显兰心蕙质。NOR]],["itemId"]=[[mianju1128]],["name"]=[[HIC灵姑娘NOR]],["need"]=15,["pic"]=[[Image/UI/AttrUI/mianju/chenglingsu1.png]],["thankText"]=[[YEL自洞庭湖北行三十余里，又穿过山镇，越过深林，你终于来到了庄前。庄内圆屋式样怪异，仿若一座大坟。你心下敬畏，硬着头皮喊门，但过了许久却无人搭理。你也不好硬闯，只能转道庄旁花圃处亭子小歇，静候主人归来。

微风徐徐，你坐在亭中闻着花圃传来的香气，只觉眼皮沉重，昏昏欲睡。“这花圃里的花有古怪！”当你意识到不对的时候，已经太迟，随后便是眼前一黑。

再醒转时，却看见一个双眸灵动的少女手中拿着你的珍宝券，嘴角满是笑意。

    “你的毒已经解了。我还以为是我师兄师姐上门来了，没想到来的人是你。”你心下叹服，随即向她询问了一些辟毒的法子，她也一一向你解答，一来二去，倒也算得上交谈甚欢。NOR]],["time"]=28,["title"]=[[PNK七心海棠NOR]]},["413"]={["id"]=413,["introText"]=[[HIW玉骨冰肌，顾盼媚流，一袭鲜红舞衣，凤鸾飞绣，玉珠垂髻，只衬得她面若桃花，于烛曳摇光间尽显风姿灼华。世闻，纵盈光皎月，仙宫美娥，亦不足她倾城一笑。NOR]],["itemId"]=[[mianju1115]],["name"]=[[HIR貂蝉NOR]],["need"]=10,["pic"]=[[Image/UI/AttrUI/mianju/diaochan.png]],["thankText"]=[[YEL你将拜帖递进一座江南宅院的正门，随即被一位垂髫女童引进院内凉亭，见花摇树影间的石桌旁坐着一素手调琴的美人，生得肌白赛雪，一袭红衫似红梅映月，果然是倾城绝色。
传闻当年貂蝉受主家王允所托，为护汉室江山以身作饵周旋于董卓与吕布之间，后来奸臣董卓被灭，吕布亦成三家姓奴令天下人耻笑，不得善终，而貂蝉从此消失，没想到竟是在这隐居。
她许久不接待生人，与你相见时脸颊飞红一片，以袖掩面，露出的美目波光流转。
看着这样一双妩媚动人的眼睛，无论男女皆会受之蛊惑。只听她声音婉转如莺啼，笑言：“若不嫌弃，貂蝉有一曲献给少侠。”
说罢，她双指在琴弦上翩飞，世闻其舞月见羞，原来美人弹琴也如仙宫之乐，令你痴醉不已。NOR]],["time"]=28,["title"]=[[RED月见羞NOR]]},["414"]={["id"]=414,["introText"]=[[HIW脸长面方，颏下微有须，颇有些豪放不羁的气质，此时正抱着个烧鸡，吃得正香。NOR]],["itemId"]=[[mianju1058]],["name"]=[[HIW老叫花NOR]],["need"]=7,["pic"]=[[Image/UI/AttrUI/mianju/hongqigong.png]],["thankText"]=[[YEL你递上珍品券，便见有一身着干净粗布衣的老者向你走来，老者豪迈一笑，向你说：“少侠，跟我来。”

你随老者绕过茅草屋向树林中走去，谈笑间，走到了一处流水潺潺的小溪边。老者招呼你在一块方石坐下，方石前是早已架好的柴堆。老者走向溪边，手中木棍挥舞间击起水花朵朵，几条河鱼就自水花中跃出落于地上。老者满意收棍，拾起河鱼手法熟练的处理好驾于火堆上。

诱人的香气飘出，待鱼肉焦黄，老者取下一条烤鱼给你，你迫不及待的咬了一口，鱼肉焦香，鲜美不已。老者又递予你一坛酒，你们开怀畅饮，不知时间流度。]],["time"]=28,["title"]=[[GRN丐帮帮主NOR]]},["415"]={["id"]=415,["introText"]=[[HIW粉雕玉琢、灵气十足，仿佛集世间各种宠爱于一身，自有一种天不怕、地不怕的洒脱劲，整一个混世小魔头。NOR]],["itemId"]=[[mianju1059]],["name"]=[[HIY宋清秋NOR]],["need"]=5,["pic"]=[[Image/UI/AttrUI/mianju/songqingqiu.png]],["thankText"]=[[YEL你将珍品券递上，随后大门被推开，走出一位身着异域服饰的女眷。此女嫣然一笑：“少侠，久等了，小姐此时正在院亭之中，你随我来便是。”

你跟随女眷穿过前庭楼宇来到后方山脚的亭台，寒酥飘落，腊雪寒梅。亭台中，一位粉雕玉琢宛如寒雪精灵的少女正玩弄着盛开梅花的折枝，见你来此，少女微红的脸上竟露出少有的天真笑容。

你与少女在亭台中相谈良久，此刻，这个昔日的混世魔王好似换了一个人，从她的身上你能感受到一丝惆怅。可能对她而言昔日调皮活泼玩世不恭的态度，正如严冬中盛开的寒梅一般，更能表现出自己强大的内心。但在这些背后，也不过是一个年龄尚小的女孩而已。NOR]],["time"]=28,["title"]=[[YEL重光右神使NOR]]},["416"]={["id"]=416,["introText"]=[[WHT生来如意事事遂，天各一方无可追。鞋身舒适，行万里而不知疲倦，然路可行，世事难追，不可复也。向心而往，一方之地成万丈深渊。NOR]],["itemId"]=[[eq2020cp04]],["name"]=[[RED一方NOR]],["need"]=3,["pic"]=[[Image/UI/StoreUI/wuqi.png]],["thankText"]=[[YEL三尺龙泉剑，匣里无人见。
