待到浓雾散去，你蓦然发现，手上的珍品券已经变成了一本泛黄的武学秘籍，令你错愕不已。NOR]],["time"]=29,["title"]=[[全篇]]},["432"]={["id"]=432,["introText"]=[[WHT她秀丽绝俗，身姿丰盈，樱桃小口灵巧端正，双眸清亮，坚毅的眼神中带着一丝勇往直前的锐利，偶尔也会露出狡黠之光，展现清纯活泼一面，叫人心生喜爱，又痴又叹。NOR]],["itemId"]=[[mianju1118]],["name"]=[[MAG丁香NOR]],["need"]=20,["pic"]=[[Image/UI/AttrUI/mianju/dingxiang1.png]],["thankText"]=[[YEL你刚将珍品券递上，便走出一名天山派的女弟子，向你作了一揖道：“四师姐让我带你过去，请随我来。”
你与女弟子走到一处山崖边，一位秀丽绝俗，身姿丰盈的女子正在此习武。虽只是基础的招式，但女子不曾有丝毫怠慢，整个人沉稳、坚毅，还带有一丝勇往无前的锐利。你与她一起讨论武学，期间还比试了一番，待日暮时分正准备告辞离开时，女子忽然开口道：“山下镇子的夜市热闹得很，不如一起去逛逛？”
夜市灯火通明，人影攒动，果真热闹非凡。女子换了一套蓝色的衣裙，头戴狐狸面具，手拿一根糖葫芦穿行在摊贩间。双眸清亮如星，樱桃小口未曾停下过，似黄鹂一般，清纯活泼，叫人心生喜爱。NOR]],["time"]=29,["title"]=[[PNK江湖三友NOR]]},["433"]={["id"]=433,["introText"]=[[WHT她生得婀娜多姿，盈盈妙目，顾盼间眼波流转。面上常带着花旦妆，更衬得人颜色艳丽，娇媚无双。NOR]],["itemId"]=[[mianju1111]],["name"]=[[YEL天竞门主NOR]],["need"]=25,["pic"]=[[Image/UI/AttrUI/mianju/tianjingmenzhu1.png]],["thankText"]=[[YEL你将珍品券递上，在戏楼门口热情地招呼着客人的小二立刻向你拱手道：“少侠，雅阁已为您备好，请随我来。”
你跟着小二走到二楼的一间雅阁，此间比大厅清净些，从楼台望去，能将戏台尽收眼底。你很快就被台上的戏吸引了去，连小二何时离开都不知。台上的旦角声音婉转动人，身形婀娜多姿，眉眼顾盼间便将你带入戏中人，一曲唱罢也久久不能回神。
几场戏后，小二再次前来带你走至戏院的后花园，园中有一青衣女子在小心擦拭着长琴。与戏台上的艳丽、娇媚相比，女子此时素雅、清冷了许多，就好似她们不是同一人。女子的声音依旧婉转动听，你们一起畅聊戏曲、音律，这一晚相谈甚欢。NOR]],["time"]=29,["title"]=[[GRN粉黛英姿NOR]]},["434"]={["id"]=434,["introText"]=[[WHT他容貌俊美，一双眼尾上扬的凤眼隐约给人阴寒之感，腰间挂有的骨笛据说用其至亲手骨所造，他右手尾指为断指，兼之一身毒术，让人倍觉诡异邪性。NOR]],["itemId"]=[[mianju1112]],["name"]=[[HIM司徒迟NOR]],["need"]=24,["pic"]=[[Image/UI/AttrUI/mianju/situchi.png]],["thankText"]=[[YEL你递入珍品券，很快有弟子为你带路。

周围草木阴森，鸩阁面传出毒虫悉索的响动，不时穿插几声渗人的惨叫。

司徒迟推开虚掩的门，从暗黑屋子里走到外面的台阶，随意用袖子擦去手上的血迹，双眼眸光清冷，“当初《武穆遗书》一事，有些问题还请少侠告知。”

接下来他句句直言，特别是对任天南的举止揣测颇深，二人显然结怨已久。

你无意卷入他们的纷争，不一会提出告辞，快要走出此地时，你听到后方隐约的笛音，阴邪凄寒中竟带着一些空无的寂寥。
NOR]],["time"]=29,["title"]=[[MAG指骨为笛NOR]]},["435"]={["id"]=435,["introText"]=[[WHT脸如朝霞，目比秋水，肤如凝脂，笑靥如花，容貌明媚照人，吹气如兰，越看越美，令人舍不得移目。NOR]],["itemId"]=[[mianju1030]],["name"]=[[HIB钟姑娘NOR]],["need"]=4,["pic"]=[[Image/UI/AttrUI/mianju/zhongling.png]],["thankText"]=[[YEL也许是今天运气不错，递上珍品券之后，谷中丫鬟很快地领着你穿过树林小径，来到了后院，你突然想起谷主恶名，心中不免有些害怕，便偷偷地留意四周。这时，背后传来一阵银铃般的笑声，“今天我爹不在谷里，你不用那么害怕。”你闻言心中稍宽，转头望去，却见少女一身粉衫，笑靥如花，你看得痴了。
她噗嗤一笑，“呆子！对了，我娘早上刚炒了些瓜子，你要不要吃些？”你其实什么也没听清，只是下意识的点了点头，将她放在你手上的东西一把丢进嘴里，然后迅速地又吐了出来。口中的辛涩让你清醒过来。
“哈哈哈，哪有你这样吃瓜子的。算了，既然你吃不惯这瓜子，那就陪我一起抓些蛇吧，不然貂儿可得饿着肚子了。”你欣然点头，与她抓了一下午的蛇。
NOR]],["time"]=29,["title"]=[[MAG钟灵毓秀NOR]]},["436"]={["id"]=436,["introText"]=[[WHT娇小玲珑，楚楚动人，身穿青衣，手拿冰草，笑颜如花NOR]],["itemId"]=[[mianju1031]],["name"]=[[HIC青小婉NOR]],["need"]=4,["pic"]=[[Image/UI/AttrUI/mianju/qingxiaowan.png]],["thankText"]=[[YEL你刚将珍品卷递上，忽闻身后传来轻柔女声：“少侠？”
闻声望去，只见一道倩影亭亭玉立在垂柳之下，小碗身着青衣手挽竹篮，雾髯云鬓，脸上笑含柔情。
你与青小碗穿行于繁华街道，周围行人的目光无不被小婉这般婢婷枭娜的姿态所吸引。你二人来到一所较为清净的宅邸门前，小婉轻叩门扉，不多时管家便拿着一个方盒走出交予小婉，谢别管家你与小婉二人便向着城外离去。
途中小婉捧着竹篮面带微笑，告诉你这户人本是做行商生意的，如今祖母病重，作为药引的冰草又如此难寻，不过好在这户家的老爷是祖母的旧识，答应以最低的价格出售冰草，如此才有了这般取药之行。
临别之际，小婉取出一株冰草，微风轻拂，恍若青衣仙女临凡，风韵柔美惹人怜爱。NOR]],["time"]=29,["title"]=[[PNK纯真少女NOR]]},["437"]={["id"]=437,["introText"]=[[HIW剑眉星目，玉冠锦袍，眼中充满着凶煞之气，一副俯视苍生的姿态，让人倍感压力NOR]],["itemId"]=[[mianju1032]],["name"]=[[HIY柳玄风NOR]],["need"]=6,["pic"]=[[Image/UI/AttrUI/mianju/liuxuanfeng.png]],["thankText"]=[[YEL你将珍品券递上，片刻后一旁的戏楼锣鼓声起，一位身穿华贵侠袍面戴鬼怪面具的优伶由后台走出，口中戏腔尖细悠扬，让人沉醉其中。
“少侠可知这曲中所唱之人是谁？”
你沉醉于戏曲之中，突然被身后一声问话惊醒。寻声望去，面前之人竟身穿与台上优伶相同的衣着，面具之下剑眉星目。
你随柳玄风落座于戏楼二层，见你对此戏兴趣浓厚，柳玄风则按照戏文给你讲述了一段戏中似有似无的故事。戏曲悠扬，戏文跌宕，在柳玄风的讲述下，你逐渐沉浸其中，仿佛你便是那戏文中的孤侠，只身对抗武林。
许久，鸡鸣响起，眼前的戏楼、优伶乃至柳玄风渐渐化为乌有。
看着东方的初阳，你的内心依然沉浸在那一段跌宕澎湃的故事中，久久不能平复。
NOR]],["time"]=29,["title"]=[[YEL命运多舛NOR]]},["438"]={["id"]=438,["introText"]=[[HIW无面无相，手拿蒲扇，十分吓人NOR]],["itemId"]=[[mianju1037]],["name"]=[[BLU无面鬼NOR]],["need"]=4,["pic"]=[[Image/UI/AttrUI/mianju/wumiangui.png]],["thankText"]=[[YEL你将珍品卷递上，霎那间周围阵阵阴风，让你不禁打了几个寒颤。
没走几步，你便发现前方枯树之下有一位红衣女子背对而立，借着月光你竟发现此女竟没有影子。
此番景象着实把你吓得不轻，你欲要转身离去之时，红衣女鬼竟发出阵阵呜咽哭泣之声。幽咽抽泣让这诡异的夜晚显得异常阴森，从女鬼的哭声中你却听出了些许留恋悲凉。
你壮着胆子来到女鬼身后颤声询问，红衣女鬼闻声一怔转过身来，只见她面无五官，一行血泪由眼部流下，格外吓人。
随后无面鬼给你讲述了一段百年之前枯树下发生的凄美爱情，故事中你知晓了无面鬼曲折悲惨的一生。
破晓时分鸡叫天明，无面鬼唱着一曲悲凉词调渐化透明，直至阳光落下消失不见。
此夜，如梦如幻，此闻，可悲可叹。NOR]],["time"]=29,["title"]=[[HIW无面恶灵NOR]]},["439"]={["id"]=439,["introText"]=[[WHT她就是玉兔。她生得娇小可爱，玲珑剔透，所见之人无不心生怜爱。NOR]],["itemId"]=[[mianju1042]],["name"]=[[PNK玉兔NOR]],["need"]=10,["pic"]=[[Image/UI/AttrUI/mianju/yuetubai.png]],["thankText"]=[[YEL你将珍品券递上，片刻后自云间走下一位娇小玲珑的女子，她身着华服，头戴半面兔形面具，更显俏皮可爱。她走至你面前，轻笑了两声，声音清脆如铃，悦耳动听，她又说到：“少侠，随我来。”

你欣然同意，一朵白云就自她脚下升起，你小心翼翼地站了上去，白云便腾空而起，向着明月而去，转瞬就来到了一座华美的宫府前，宫门上有一白玉匾额，上刻广寒宫。

你随女子在宫中游览，宫府以水晶为阶，琉璃为瓦，白玉为墙，月光下熠熠生辉。宫里四处仙气渺渺，山石秀丽，奇花争艳，一步一景，一景一境，叫人应接不暇，

忽然你听见殿中传来悦耳仙乐，正欲前往却一脚踏空，你惊呼一声，景色倏然转换，变成了你熟悉的卧房。窗外月色清辉，原来方才只是一场梦罢了。NOR]],["time"]=29,["title"]=[[HIW捣药玉兔NOR]]},["44"]={["id"]=44,["introText"]=[[WHT此步法施展时人如僵尸一般，一步一纵，诡异异常。]],["itemId"]=[[jiangshibufa1]],["name"]=[[MAG僵尸步法NOR]],["need"]=8,["pic"]=[[Image/UI/StoreUI/shujuan4.png]],["thankText"]=[[YEL满月临弓影，连星入剑端。
