你沉吟不语，将珍品券捧于手上，似在心中思索着什么。
须臾间，空中一股浓雾飘散而来，遮蔽了你的视线。
待到浓雾散去，你蓦然发现，手上的珍品券已经变成了一本泛黄的武学秘籍，令你错愕不已。NOR]],["time"]=6,["title"]=[[全篇]]},["440"]={["id"]=440,["introText"]=[[WHT这是假托“词牌造物”之名而作的一系列饰品之一，据说是在某位贵人授意下、由大内造的宫廷巧匠所制。NOR]],["itemId"]=[[eq2020cp15]],["name"]=[[HIC杏花风NOR]],["need"]=3,["pic"]=[[Image/UI/StoreUI/wuqi.png]],["thankText"]=[[YEL三尺龙泉剑，匣里无人见。
