待到浓雾散去，你蓦然发现，手上的珍品券已经变成了一份残页，令你错愕不已。NOR]],["time"]=29,["title"]=[[残页]]},["45"]={["id"]=45,["introText"]=[[WHT他就是赵武德。他生得身形挺拔，左颊一条刀疤，衬得眉目愈发粗犷，怀中抱着的长剑似乎刻满了久经江湖的沧桑之感。]],["itemId"]=[[mianju1083]],["name"]=[[YEL赵武德NOR]],["need"]=25,["pic"]=[[Image/UI/AttrUI/mianju/zhaowude.png]],["thankText"]=[[YEL你将珍品券递上，片刻后出来一位高大威猛，身形挺拔的男子，他左颊一条刀疤，衬得眉目愈发粗犷。男子豪气一笑，叫你随他去。

你随着男子来到一处亭子，这亭子居然建在悬崖边上，涯边凛风呼啸，亭边仅有怪石嶙峋，全然一副萧杀之意。男子不知从何处掏出两壶好酒，将一壶扔予你，自己开了一壶，猛灌了一大口后，向你道：“倒是没想到你会来看我，今日我们不谈其他，只一醉方休！”

你们在涯边亭中开怀畅饮，确是不醉不归，直至繁星满天才有几名小厮前来将你们扶回各自房中休息。]],["time"]=6,["title"]=[[HIR剑底亡魂NOR]]},["450"]={["id"]=450,["introText"]=[[HIW此内功由一青海僧人所创，兼具西域内功和中原内功之长处，施展之时，内劲极为刚猛。NOR]],["itemId"]=[[wangshenggong]],["name"]=[[往生功]],["need"]=25,["pic"]=[[Image/UI/StoreUI/shujuan1.png]],["thankText"]=[[YEL满月临弓影，连星入剑端。
