待到浓雾散去，你蓦然发现，手上的珍品券已经变成了一本泛黄的武学秘籍，令你错愕不已。NOR]],["time"]=30,["title"]=[[全篇]]},["451"]={["id"]=451,["introText"]=[[HIW这是一套古老的刀法，由昔年一位异人于戊戌年所创，因而得名。戊者，草木繁盛也，戌者，万物灭尽也。NOR]],["itemId"]=[[wuxudaofa]],["name"]=[[戊戌刀法]],["need"]=10,["pic"]=[[Image/UI/StoreUI/shujuan2.png]],["thankText"]=[[YEL满月临弓影，连星入剑端。
