待到浓雾散去，你蓦然发现，手上的珍品券已经变成了一本泛黄的武学秘籍，令你错愕不已。NOR]],["time"]=30,["title"]=[[全篇]]},["452"]={["id"]=452,["introText"]=[[HIW相传，此身法由魔女赤练根据漫天飞星所创，后流传于江湖。施展起来宛若赤蛇渡水，百转千回。NOR]],["itemId"]=[[chilianlingbobox1]],["name"]=[[赤练凌波]],["need"]=15,["pic"]=[[Image/UI/StoreUI/shujuan3.png]],["thankText"]=[[YEL满月临弓影，连星入剑端。
