待到浓雾散去，你蓦然发现，手上的珍品券已经变成了一本泛黄的武学秘籍，令你错愕不已。NOR]],["time"]=30,["title"]=[[全篇]]},["453"]={["id"]=453,["introText"]=[[HIW这是江湖中失传已久的烈火鞭法，其招式凌厉，可攻可守，十分厉害。NOR]],["itemId"]=[[yuanxiaoleiji1]],["name"]=[[烈火鞭法]],["need"]=8,["pic"]=[[Image/UI/StoreUI/shujuan4.png]],["thankText"]=[[YEL满月临弓影，连星入剑端。
