待到浓雾散去，你蓦然发现，手上的珍品券已经变成了一本泛黄的武学秘籍，令你错愕不已。NOR]],["time"]=30,["title"]=[[全篇]]},["454"]={["id"]=454,["introText"]=[[HIW天雷破乃是江湖散人穆灵云的独门鞭法，其招威力极大，且声势威猛，宛若天雷一般。NOR]],["itemId"]=[[tianleipo1]],["name"]=[[天雷破]],["need"]=9,["pic"]=[[Image/UI/StoreUI/shujuan5.png]],["thankText"]=[[YEL满月临弓影，连星入剑端。
不学燕丹客，徒歌易水寒。
你沉吟不语，将珍品券捧于手上，似在心中思索着什么。
须臾间，空中一股浓雾飘散而来，遮蔽了你的视线。
待到浓雾散去，你蓦然发现，手上的珍品券已经变成了一本泛黄的武学秘籍，令你错愕不已。NOR]],["time"]=30,["title"]=[[全篇]]},["455"]={["id"]=455,["introText"]=[[WHT眉清目秀，丰神如玉。白日里温雅谦逊，淡然沉静，抱剑而立只道是个文弱的美少年。而不知何故，一到夜里竟满身疮痍，面目疯狂而绝望，叫人望而生畏。NOR]],["itemId"]=[[mianju1154]],["name"]=[[HIC林少侠NOR]],["need"]=17,["pic"]=[[Image/UI/AttrUI/mianju/linshaoxia1.png]],["thankText"]=[[YEL西湖湖畔，你寻觅许久，终于是见到了他。

与往常的丰神如玉不同，此时，他双眼处蒙着红纱，浑身血污，右手死死攥着宝剑，不时向四周挥舞着，显得有些癫狂。

你向他表明来由，并将珍宝券远远地丢在他的跟前，一番警惕地摸索过后，他似乎对你暂时打消了敌意。

他与你谈起这些年来的经历，从救人被灭门，到拜师被骗秘籍，从练功报仇，到最终双目被毁。你听了他的故事，心中既怜又恨，但却不知道该如何开口，最终也只是选择了微微一叹。

临别之际，你还是问出了心中的疑惑，“你对得起岳小妹吗？”

他如遭雷击，却始终缄默。

你摇了摇头，转身便走，不再留恋。NOR]],["time"]=30,["title"]=[[BLU夜里悲狂NOR]]},["456"]={["id"]=456,["introText"]=[[WHT筋肉虬结，眼神凌厉。太阳穴高高隆起，颧骨和下巴勾勒出坚毅的线条，心如猛虎，动如脱兔，伟岸的身躯似是钢浇铁铸，一双缠满绷带的铁拳无人可以匹敌。NOR]],["itemId"]=[[mianju1155]],["name"]=[[HIG拳霸NOR]],["need"]=16,["pic"]=[[Image/UI/AttrUI/mianju/quanba.png]],["thankText"]=[[YEL月影下，竹林中，传来破空之声。

你循声而至，眼前的男子果然就是你要找寻的拳霸。你趁着他练拳歇息的片刻，递上珍宝券，向他表明了来意。他虽然对你的到来略感惊异，却没有多说什么，反而拉着你陪他一起练拳。

拳来脚往，切磋之中，你发现他的招式路数与中原拳脚大不相同。比起中原精妙的拳招，他的路数更为简单，招式大开大合，威力足可劈石断碑，每一招虽然少了虚实变化，但胜在拳势刚猛，叫对手退无可退、让无可让。这一次切磋确实让你受益颇多。NOR]],["time"]=30,["title"]=[[GRN拳霸天下NOR]]},["457"]={["id"]=457,["introText"]=[[WHT他就是剑神。他生得眉如利剑、面似白雪。眉心中一点剑痕，眼神明亮深邃却暗藏孤寂。剑刃握于手中，剑华流转不息，剑芒吞吐不定。试问何为剑客之心？原是一曲寂寞之情。NOR]],["itemId"]=[[mianju1136]],["name"]=[[HIW剑神NOR]],["need"]=15,["pic"]=[[Image/UI/AttrUI/mianju/jianshen.png]],["thankText"]=[[YEL你递上珍品券，庭院内从鲜花丛深处走出一位穿着雪白长衫、背着乌鞘长剑的男人。

见到你，他如远山冰雪般飘渺的神情，闪过一丝炽热的光芒，“你习武的天赋不错。”

这话虽语气平静，但你能听出里面的欣赏之意。你忍不住提出要和他切磋的要求，他却摇头拒绝，苍白的脸上有着傲视天下的冷漠：“我的剑招只为杀人。”

似不忍心见你的希望落空，他拔出那柄形势古老的漆黑长剑，在你面前演示了他的剑法，快如闪电，剑气寒意飒飒，令盛夏的晴空仿佛飘起凛冬的大雪。

待他的剑回到剑鞘，你才发觉满庭的花丛竟全部凋谢，仔细看原是被汹涌的剑气斩尽。

“凭你习武的天赋，我很期待日后能和你一较高下。”说罢，他几个闪身间跃至房梁上，施展轻功消失在了远方。NOR]],["time"]=30,["title"]=[[CYN落花吹雪NOR]]},["458"]={["id"]=458,["introText"]=[[WHT他就是任老魔头。狂傲不羁，桀骜不驯。一头黑发，一袭青衫，一只独眼，更显其傲视群雄之姿。而他伤眼上的铁护，和他掌心磅礴的吸力，似要宣告这天地间只有他一人。NOR]],["itemId"]=[[mianju1143]],["name"]=[[HIR任老魔头NOR]],["need"]=14,["pic"]=[[Image/UI/AttrUI/mianju/renjiaozhu.png]],["thankText"]=[[YEL教徒接过你手中的拜帖，领着你穿过崖间小道，向着山顶的大殿走去。约莫走了半个时辰，你远远地看到了在大殿上圣教主。

还未走近，教众忽而齐声高叫：“圣教主千秋万载，一统江湖！千秋万载，一统江湖！”你被吓了一跳，隐隐觉得有几分怪异，但身为客人终究要讲几分礼数，便执弟子礼远远地向圣教主行礼。

“不必多礼”，他似乎心情大好，“几十年不见天日，刚报了旧仇，便来了新友，不错不错！来人，上酒！”觥筹交错，你们相谈甚欢，他也指点了你一些武学上的问题，你自觉此行收获颇多。

    下得崖来，山间又传出“千秋万载，一统江湖”、“文成武德，仁义英明”的吹捧之语。你皱了皱眉，转身离去，不再回头。NOR]],["time"]=30,["title"]=[[RED天下任行NOR]]},["459"]={["id"]=459,["introText"]=[[WHT端丽清雅、风致嫣然，容貌有如少女一般的明眸皓齿、顾盼生辉，体态却是年轻女孩所没有的丰腴和艳丽，似乎岁月在其身上留下的痕迹都是好的、无害的。NOR]],["itemId"]=[[mianju1075]],["name"]=[[HIY蓉姑娘NOR]],["need"]=12,["pic"]=[[Image/UI/AttrUI/mianju/guofuren.png]],["thankText"]=[[YEL你将拜帖收好，片刻后一辆马车风尘仆仆停在面前。一路摇摇晃晃不知过了多久，马车停稳，你开门而下，迎面袭来阵阵桃花香气，让人沉醉。

你行于盛开的桃花林之中，不多时，踏着满地落花来到一处宅院门前。你轻叩门扉，应声走出一男一女，男子得知你的来意后对你执手一礼道了一句：“伯母在后院花厅之中，我二人身负要事不便耽搁，告辞。”后便匆匆离去。

你绕过宅邸来到花厅，蓉姑娘此时手执宝剑于落花之中翩舞。手中宝剑如灵蛇游龙，闪闪寒芒划过飞花尽数斩断，此景恍如画卷，让人沉醉难舍。

招尽剑合，你二人落座亭台之中共享美酒佳肴。落日时分你辞别蓉姑娘踏上归途，临别之时，蓉姑娘将自酿的桃花美酒相赠，酒香醉人，溢传千里。NOR]],["time"]=30,["title"]=[[YEL贤内助NOR]]},["46"]={["id"]=46,["introText"]=[[WHT她就是朝英女侠。她生得何彼秾矣，华如桃李，一双脉脉含情的眼眸，一件艳红明丽的衣裳，好似一位身着嫁衣的女子，正在翘首盼望意中人的到来。]],["itemId"]=[[mianju1137]],["name"]=[[RED朝英女侠NOR]],["need"]=15,["pic"]=[[Image/UI/AttrUI/mianju/chaoyingnvxia.png]],["thankText"]=[[YEL你将珍品券递上，半晌，沉重的石门缓缓打开，一位素衣女子走出，向你拱手道：“少侠，久等了。”

你随素衣女子来到一个石室门口，素衣女子便自行告退。你进入石室内，只见一位身着艳红明丽衣裳的女子正在附身作画。你上前一瞧，作的是一位英姿飒爽的大侠背立的画。女子画得入神，未察觉你的到来，你也只是噤声观看，只觉这画中大侠似有绝行之意，又有难舍之情。

许久女子才恍然回神，见你已然站了许久，连忙请你入座。古墓清幽，你们只是饮茶座谈，女子问起许多全真与天下事，你都一一作答。待日落西山，你方才告辞离去。]],["time"]=6,["title"]=[[MAG古墓深情NOR]]},["460"]={["id"]=460,["introText"]=[[WHT假托《山海经》中异兽之名所铸的兵刃之一。铸造之人喜读异兽怪谈，又有炼制神兵之技，遂铸了一套兵刃，聊慰平生。NOR]],["itemId"]=[[eq2020xslb07]],["name"]=[[HIR毕方NOR]],["need"]=3,["pic"]=[[Image/UI/StoreUI/wuqi.png]],["thankText"]=[[YEL三尺龙泉剑，匣里无人见。
