他是幽冥教教主的嫡传弟子，生性多疑，倨傲不已，天下间能让他甘愿结交之人少之又少。
他颜如舜华，宛若女子一般，不少江湖高手初见他时只笑他是阴柔之辈，直至剑出血横，方明白他的厉害。NOR]],["itemId"]=[[mianju1084]],["name"]=[[GRN叶妄生NOR]],["need"]=10,["pic"]=[[Image/UI/AttrUI/mianju/yewangsheng.png]],["thankText"]=[[YEL珍品券送入不久后，忽听得一声惨叫，你正欲抬脚入门一探究竟之时，一个人影从层层黑纱帐中走了出来。
叶妄生本就生得阴柔，着一袭暗红玄色敞袍与他所持匕首上沾染的血色正好相衬。
他朝你看了一眼，微闭双目，冷笑一声：“我当是谁......既然来了，请。”
事后，你浑然记不起黑纱帐中的情景，只依稀觉得今日的叶妄生并非如江湖传闻所说的那般冷绝。NOR]],["time"]=6,["title"]=[[PNK三途来客NOR]]},["470"]={["id"]=470,["introText"]=[[HIW传闻此剑法无形无相，缥缈至极，谈笑间便可杀人于无形之中。NOR]],["itemId"]=[[xiaoyaowuxiangjian1]],["name"]=[[逍遥无相剑]],["need"]=13,["pic"]=[[Image/UI/StoreUI/shujuan1.png]],["thankText"]=[[YEL满月临弓影，连星入剑端。
