待到浓雾散去，你蓦然发现，手上的珍品券已经变成了一本泛黄的武学秘籍，令你错愕不已。NOR]],["time"]=31,["title"]=[[全篇]]},["475"]={["id"]=475,["introText"]=[[WHT面如冠玉，剑眉星目，丰神俊朗。他似笑非笑，手中把玩着元宝，不知道此刻他又在想着什么赚钱的门路。NOR]],["itemId"]=[[mianju1159]],["name"]=[[HIY陈撰乾NOR]],["need"]=10,["pic"]=[[Image/UI/AttrUI/mianju/chenzhuanqian1.png]],["thankText"]=[[YEL你将珍品券递上，随后跟随伙计进入店中。你刚落座便听到旁桌陈撰乾与一独眼男人攀谈。

独眼男人取出一物，此物形为卧虎，通体黝黑，是一只纯铁打造的虎雕。但虎眼处残缺，仅有两个空洞。

陈撰乾收起折扇，掂量铁虎随后伸出一指。在二人随后的交谈中，你得知独眼男人想将铁虎高价卖给陈撰乾，而陈撰乾则以铁虎材质和残缺为由给出了极低的价格。

二人交谈半晌，独眼男人最终同意了陈撰乾给出的价格匆匆离去。你见此凑上身来与陈撰乾攀谈，闲聊之中你把玩着手中的铁虎，好奇之下刮了刮铁虎一侧，随着刮动铁虎表面的黑色一点点褪去，露出了耀眼的金色。

你一脸震惊看向陈撰乾，他则是一脸得意的坐在对面慢条斯理品味着杯中浓茶，笑而不语。NOR]],["time"]=31,["title"]=[[YEL生财有方NOR]]},["476"]={["id"]=476,["introText"]=[[WHT云鬓俏颜，香腮如雪，媚眼羞合，丹唇笑分。NOR]],["itemId"]=[[mianju1164]],["name"]=[[HIC金三娘NOR]],["need"]=11,["pic"]=[[Image/UI/AttrUI/mianju/jinsanniang1.png]],["thankText"]=[[YEL你将珍品券递上，随后被店伙计告知三娘外出未归，若有要事可去往河畔寻找。

河畔亭台，三娘身着紫衣，坐在其中。石桌之上，一只通体乌黑的大猫正懒散的晒着太阳，享受着三娘的抚摸。

走进亭台，黑猫瞥了你一眼随后打着哈欠翻了个身不再理你。你二人在亭台中闲聊良久，桌上的黑猫也不知何时被三娘抱在怀中，睡得香甜。

天空逐渐落下淅沥小雨，雨点落在荷叶之上逐渐汇聚。三娘望着天边乌云出神，被你轻拍后眼中忧愁一闪而过，随后依旧是巧笑嫣然。

不多时，开云见日，不知何处响起三声哨响。闻声，三娘嘴角浅笑，起身与你辞别，说罢将怀中黑猫放在桌上转身离开了亭台。三娘走后，黑猫伸了伸懒腰瞥了你一眼，随后扬长而去，不见踪影。NOR]],["time"]=31,["title"]=[[HIW雪青玉铃NOR]]},["477"]={["id"]=477,["introText"]=[[WHT剑眉入鬓，眼底无情。一身青灰的劲装猎猎作响，双臂的缠带和漆黑的乱发随风飘扬。手持利刃，直叫人避其锋芒。心似苍狼，旁观者顿感悲凉。NOR]],["itemId"]=[[mianju1124]],["name"]=[[BLU石少侠NOR]],["need"]=15,["pic"]=[[Image/UI/AttrUI/mianju/shishaoxia.png]],["thankText"]=[[YEL你将珍品券递上，不一会就走出有一位身着青灰色劲装的男子，男子手持利刃，锋芒毕露，向你作揖道：“少侠久等了。”

你随男子走进入一片树林中，林中树木身上遍布剑痕，一看便知男子时常在此练剑。男子邀你在一石凳上坐下，拿出几壶好酒，说道：“早闻少侠爱酒，便叫阿绣买了些来，今日我们便不醉不归！”

你们痛饮美酒，相谈甚欢，又借着月光比试了一番，直至夜色阑珊方才告辞离开。NOR]],["time"]=31,["title"]=[[WHT石上行诗NOR]]},["478"]={["id"]=478,["introText"]=[[WHT仪表堂堂，英俊非凡，眼中满是柔情，令人动容NOR]],["itemId"]=[[mianju1034]],["name"]=[[HIB牛郎NOR]],["need"]=10,["pic"]=[[Image/UI/AttrUI/mianju/niulang.png]],["thankText"]=[[YEL你将珍品券递上，片刻后，一位男子向你走来，他生得仪表堂堂，虽是身着布衣，却依旧是英俊非凡。男子周身喜鹊环绕，手牵一头高大的水牛，走至你面前，拱手道：“久等了，随我来。”

你跟着男子走到一间小院，小院不大但温馨舒适。院子其右种有葡萄，葡萄架下站着一位女子，手拿木篮，盈盈一笑，灼灼其华。男子快步上前接过女子手中木篮，你见两人身影相依，只觉神仙眷侣便应是如此。

女子领你至院中木椅坐下，一只憨状可掬的绣虎猫窝在你的脚边。片刻后，男子端来了一盘甘甜的果子，又沏上了一壶清茶，你与男子闲聊逗猫，好不怡然。黄昏将至，炊烟渺渺，你又品尝了一番女子做的佳肴后，就告辞离开了。NOR]],["time"]=31,["title"]=[[CYN迢迢牵牛星NOR]]},["479"]={["id"]=479,["introText"]=[[WHT沉鱼落雁，飘然若仙，衣着华美，彩带纷飞，眼中噙着泪水，令人动容。NOR]],["itemId"]=[[mianju1035]],["name"]=[[PNK织女NOR]],["need"]=10,["pic"]=[[Image/UI/AttrUI/mianju/zhinv.png]],["thankText"]=[[YEL你将珍品券递上，片刻后，一位飘然若仙，衣着华美的绝美女子向你走来。女子周身喜鹊环绕，彩带纷飞。你惊讶之际，女子牵着你的手踏步鹊桥，片刻后，你二人来到一间小院门口，院落不大但处处充满着温馨舒适之感。

你与女子坐在葡萄架旁闲聊，不多时，院门被推开，一个仪表堂堂，长相英俊的男子走进，他的身后还跟着一头高大水牛。

女子间男子归来起身相迎，此时，憨状可掬的绣虎猫从一旁跑来卧在男子脚旁。

你与男子闲聊逗猫，黄昏已至，夕阳西下。你三人围坐桌旁共享佳肴美酒，直至明月攀上树梢头你才辞别二人离去。NOR]],["time"]=31,["title"]=[[HIW皎皎河汉女NOR]]},["48"]={["id"]=48,["introText"]=[[WHT她就是雩。她生得娉婷秀雅，头戴青冠赤羽，身穿青袍，面上涂了几抹红妆，神情肃穆，在为祈雨仪式准备着。]],["itemId"]=[[mianju1103]],["name"]=[[PNK雩NOR]],["need"]=5,["pic"]=[[Image/UI/AttrUI/mianju/yu.png]],["thankText"]=[[YEL你将珍品券递上，片刻后走出一位青衣女子，青衣女子笑靥如花，向你道：“少侠，请随我来。”

你随青衣女子走进一座高楼，高楼里人声鼎沸，高楼外人头攒动，都是前来参加祈雨仪式的百姓。你随青衣女子走进一间雅座，刚一落座便有人端上了茶水、糕点。青衣女子笑着道：“烦请少侠静候片刻，祈雨仪式即将开始。”

你才饮下一杯清茶，只觉楼外忽然寂然无声，片刻又听见鼓乐震天，抬眼望去原是祈雨仪式开始了。只见一位头戴青冠赤羽，身穿青袍，面上涂了几抹红妆，神情肃穆的女子站在祭坛上诵词起舞，你忽然觉得周边清凉了许多。你静心观看，一场仪式结束，仍觉意犹未尽。]],["time"]=6,["title"]=[[YEL执羽舞器NOR]]},["480"]={["id"]=480,["introText"]=[[WHT据说是汉时徐州某位县令，为了迎合上欲，集全县之力历时三年打造而得的神兵利器，本名征西大将军，后因为过于媚上而改名。NOR]],["itemId"]=[[eq2019june1]],["name"]=[[XGR百里侯NOR]],["need"]=3,["pic"]=[[Image/UI/StoreUI/wuqi.png]],["thankText"]=[[YEL三尺龙泉剑，匣里无人见。
一张落雁弓，百支金花箭。
你沉吟不语，将珍品券捧于手上，似在心中思索着什么。
