待到浓雾散去，你蓦然发现，你的手上竟多了一件宝光四射的装备，而那张珍品券早已不知所踪。NOR]],["time"]=31,["title"]=[[HIW珍品装备NOR]]},["481"]={["id"]=481,["introText"]=[[WHT这是一顶朱红色的帽子，用上好的绸缎和皮革缝制而成，华贵喜庆，适合出席一些重要的仪式或场合时穿戴。NOR]],["itemId"]=[[2019jizi003]],["name"]=[[RED吉兆NOR]],["need"]=3,["pic"]=[[Image/UI/StoreUI/wuqi.png]],["thankText"]=[[YEL三尺龙泉剑，匣里无人见。
