待到浓雾散去，你蓦然发现，手上的珍品券已经变成了一本泛黄的武学秘籍，令你错愕不已。NOR]],["time"]=32,["title"]=[[全篇]]},["496"]={["id"]=496,["introText"]=[[HIW天启帮聚义堂绝学之一，由章作之不断完善。秉承聚义堂一贯传统，凡是认可之人便可将武功传给他，无需受帮中规矩限制。NOR]],["itemId"]=[[yuxianjue]],["name"]=[[羽仙诀]],["need"]=5,["pic"]=[[Image/UI/StoreUI/shujuan4.png]],["thankText"]=[[YEL满月临弓影，连星入剑端。
不学燕丹客，徒歌易水寒。
你沉吟不语，将珍品券捧于手上，似在心中思索着什么。
须臾间，空中一股浓雾飘散而来，遮蔽了你的视线。
待到浓雾散去，你蓦然发现，手上的珍品券已经变成了一本泛黄的武学秘籍，令你错愕不已。NOR]],["time"]=32,["title"]=[[全篇]]},["497"]={["id"]=497,["introText"]=[[WHT他身躯凛凛，相貌堂堂。一双眼睛射寒星，两弯剑眉如刷漆。气宇轩昂，大红的舞狮头肩上扛。从容不迫，将脑后束起的一根长辫咬在口中。NOR]],["itemId"]=[[mianju1130]],["name"]=[[HIY黄师傅NOR]],["need"]=17,["pic"]=[[Image/UI/AttrUI/mianju/huangshifu.png]],["thankText"]=[[YEL珍品券送入不久后，走出一位身着黄布衣的男子，拱手道：“黄师傅正在做准备，请少侠稍等。”

你方与男子聊了两句，前边突然开始敲锣打鼓，人群也喧闹了起来。你随着人群往前方走去，便见着一位气宇轩昂的男子，扛着大红的舞狮头随着鼓点起舞。时喜时醉，时惊时怒，在木桩上灵巧跃动，表演得形神合一，生动活泼。

一场舞狮结束，你只觉意犹未尽，正巧此时黄布衣的男子替黄师傅来邀你至武馆中一叙，你欣然同意。武馆中，黄师傅早已命人备好茶水，你们畅谈古今，相谈甚欢，竟忘了时间，待回过神来已是华灯初上，你才依依不舍地告辞离去。
NOR]],["time"]=32,["title"]=[[RED醒狮飞鸿NOR]]},["498"]={["id"]=498,["introText"]=[[WHT须发浓密，和蔼可亲，是民间传说的土地之神，每年播种之际，百姓都会设坛祭祀，以求今年风调雨顺]],["itemId"]=[[mianju1102]],["name"]=[[HIY社神NOR]],["need"]=16,["pic"]=[[Image/UI/AttrUI/mianju/sheshen.png]],["thankText"]=[[YEL你将珍品券递上，随后便被浓雾环绕，下一刻，一幢华丽宏伟的建筑慢慢浮现。周围环境也渐渐在浓雾之中转变，放眼望去，你此时正处在一片云海之上，阳光穿透地面飘起的云雾，折射出耀眼的五彩之光。

片刻后，门匾刻有“社神府”字样的大门缓缓打开，其中隐隐走出一位须发浓密男人。只见此人面带微笑，将你带入社神府，进入府内你顿时被眼前从未见过的仙境美景所震撼。

你跟随社神在如梦如幻的仙境内神游，而社神则给你讲述了很多传说神话。

许久，你辞别社神，就在你沉醉游历美景之中时，周围的环境渐渐转换。

浓雾渐渐散去，眼前的社神府也慢慢隐匿于云雾之中。不多时，那宛如画卷般的仙境便消失不见，周围的一切也随之恢复如初。NOR]],["time"]=32,["title"]=[[HIR海晏河清NOR]]},["499"]={["id"]=499,["introText"]=[[WHT面容俊秀，眉眼多情。穿着一身墨色华贵的绸缎衣袍，袍内露出一道镂空木槿花的镶边。腰系玉带，手持折扇，杏子状的眼睛如灿烂星河。NOR]],["itemId"]=[[mianju1116]],["name"]=[[HIC移花公子NOR]],["need"]=20,["pic"]=[[Image/UI/AttrUI/mianju/huagongzi.png]],["thankText"]=[[YEL你将珍品券递上，随后气派的山门被推开，从中走出一位美艳女子。

你与女子进入移花宫内，不多时，你便被带入会客厅内，厅中一个绝世美人坐在主位之上，此女拥有绝顶美丽的面孔和一双仿佛洞悉一切的美眸，气质出尘，绝代风华。而她身旁的客位上，风神俊朗的少宫主华公子正紧锁眉头看着手中的古卷。

绝世美人离开后，花公子如释重负。随后你二人进入偏厅，片刻一行弟子乘上美味佳肴，来人无一不对花公子的俊朗外表所青睐，偷偷观瞧羞红了俏脸。

皎月如镜，月光如水。花公子将你送出移花宫，临走之时，花公子送予你一把折扇，扇面上苍劲的毫锋书写了一首名为“绝代双骄”的诗词，词中故事可歌可泣，让人泪下。NOR]],["time"]=32,["title"]=[[HIW花落无缺NOR]]},["5"]={["id"]=5,["introText"]=[[相传，一世名将杨五郎得高僧智光大师点化，遂于五台山挂单出家。皈依之后，五郎长枪换作木棍，将一身名震沙场的杨家枪，演化为六十四点八卦棍，名曰“五郎八卦棍”。]],["itemId"]=[[wulangbaguagunbox1]],["name"]=[[    HIB五郎八卦棍NOR]],["need"]=15,["pic"]=[[Image/UI/StoreUI/shujuan6.png]],["thankText"]=[[YEL满月临弓影，连星入剑端。
