待到浓雾散去，你蓦然发现，手上的武学名录已经变成了一本泛黄的武学秘籍，令你错愕不已。NOR]],["time"]=1,["title"]=[[全篇]]},["50"]={["id"]=50,["introText"]=[[WHT流传在江苏一带的偏门刀法，不同于常见刀法的大开大合，此刀法极重暗处出刀，并独创藏刀于袖内之招式，堪称江湖一绝。]],["itemId"]=[[cangfengdaofa]],["name"]=[[藏锋刀法]],["need"]=20,["pic"]=[[Image/UI/StoreUI/shujuan1.png]],["thankText"]=[[YEL满月临弓影，连星入剑端。
