待到浓雾散去，你蓦然发现，手上的珍品券已经变成了一本泛黄的武学秘籍，令你错愕不已。NOR]],["time"]=7,["title"]=[[全篇]]},["500"]={["id"]=500,["introText"]=[[HIW眼眸深邃，鼻梁高挺。他一身钢铁重甲，碧绿的眼睛，金黄的头发，棱角分明的面容显得刚毅不屈。身后的士兵引吭高歌，胸前的徽记烨烨生辉。NOR]],["itemId"]=[[mianju1145]],["name"]=[[HIB骑士莱恩NOR]],["need"]=25,["pic"]=[[Image/UI/AttrUI/mianju/fengbaoqishilaien.png]],["thankText"]=[[YEL你递上拜帖，被仆人们引到古堡深处。见到他时，你有点错愕，眼前的男子身穿异国礼服，尽显雍容华贵，与你印象中那个一身铁甲的身形确实相差太大。莱恩被你错愕的表情逗得开怀一笑，随后便拉着你去到了庭院小歇。


伴着夕阳的余晖，莱恩与你坐在太阳伞下，品尝着他家乡的甜点与红茶。不得不说，异乡的食物确实别有风味，让你心生喜欢。

“来中原那么久，难得有人来我这儿做客。我很喜欢中原，这里很美，很有活力。”莱恩又细品了一口红茶，继续道，“但这里的人们缺乏信仰，我希望重光的光辉有一天能照射到中原各地。”

“愿重光赐予你祝福。”NOR]],["time"]=32,["title"]=[[BLU风暴神使NOR]]},["501"]={["id"]=501,["introText"]=[[WHT他生得娇艳，身穿一身枣红色缎面长袍，眼波流转之间，神态竟要比女子还要妩媚三分。]],["itemId"]=[[mianju1098]],["name"]=[[HIR杨总管NOR]],["need"]=14,["pic"]=[[Image/UI/AttrUI/mianju/yangzongguan.png]],["thankText"]=[[YEL你将珍品券递上，片刻后走出两位长袖青衫，黑纱蒙面的男子，向你拱手道：“总管有请！”

你随两位蒙面男子进入殿内，只见殿内早已备好宴席。一个身着枣红色缎面长袍，身形妖娆的男子坐于桌前。男子起身邀你入座，轻轻一挥手，道了句：“上酒吧。”两位蒙面男子毕恭毕敬的端上好酒，为你们斟上。

你与男子推杯交盏间，相谈甚欢。惊风飘白日，光景西驰流，眼看日头西沉，你也只得告辞离去。]],["time"]=32,["title"]=[[YEL天人化生NOR]]},["502"]={["id"]=502,["introText"]=[[HIW风华绝代，烟视媚行，慵懒雍容中又有几分伟男子的英气，让人一见难忘。NOR]],["itemId"]=[[mianju1053]],["name"]=[[RED神教教主NOR]],["need"]=9,["pic"]=[[Image/UI/AttrUI/mianju/dongfangbubai.png]],["thankText"]=[[YEL你将珍品券递上，片刻后走出两位长袖青衫，黑纱蒙面的男子，向你拱手道：“教主有请！”

你随两位蒙面男子进入殿内，殿内宝座上正坐有一人，那人一身红衣，风华绝代，慵懒雍容之中又带有几分飒爽英姿，叫人一见难忘。他无需言语，只一抬眼，两位蒙面男子便心领神会的带你入座，端上美酒佳肴后就自行退下。

那人斜躺于宝座上，左手拿着一个绣花绷架，右手持着一枚绣花针，手指灵巧的运针引线。炎炎夏日，蚊虫纷扰，就在你们闲聊之间，飞来了一只苍蝇嗡嗡地扰人。你还未有所反应，只见银光一闪，那苍蝇便被一枚绣花针钉在柱上。转眼望去，他仍在穿针引线，似乎从未变过，你不由得赞叹其武功之高绝。NOR]],["time"]=32,["title"]=[[YEL日出东方NOR]]},["503"]={["id"]=503,["introText"]=[[WHT她就是姑射龙女。生得清丽秀雅，白衣飘然，手持一柄乌黑长剑，风姿绝代。NOR]],["itemId"]=[[mianju1050]],["name"]=[[BLU姑射龙女NOR]],["need"]=8,["pic"]=[[Image/UI/AttrUI/mianju/nianqinglongnv.png]],["thankText"]=[[YEL终南山下，古陵幽深。

白繁霜执着你的拜帖，领着你朝古陵深处走去。古陵本就清幽，深处更是带上几分阴冷，与外界大相径庭。你略感不适之余，也不禁心生好奇，到底会是什么样的人才能久居于此。

很快，你便得到了你想要的答案。她一身缟素，容颜绝美，但神色清冷尤胜这古陵。她柳眉微蹙，似乎另有心事，只是与你匆匆会面，便又让白繁霜领着你离开了她的居所。

白繁霜深谙龙姑娘的脾性，向你告罪后，便领着你在古墓中四处游玩起来。寒潭钓鱼、采蜂蜜、捉麻雀，游玩下来倒也别有一番趣味。NOR]],["time"]=32,["title"]=[[PNK古陵传人NOR]]},["504"]={["id"]=504,["introText"]=[[WHT假托《山海经》中异兽之名所铸的兵刃之一。铸造之人喜读异兽怪谈，又有炼制神兵之技，遂铸了一套兵刃，聊慰平生。NOR]],["itemId"]=[[eq2020xslb03]],["name"]=[[HIR鹿蜀NOR]],["need"]=3,["pic"]=[[Image/UI/StoreUI/wuqi.png]],["thankText"]=[[YEL三尺龙泉剑，匣里无人见。
