待店伙计离去，你好奇张望房内，只见房内桌上已经摆满了美食。垂涎之际苟酝赢从你身后走来，你本想离去，怎奈苟酝赢邀请你入座，与他共享美酒佳肴。

你二人推杯换盏，期间曾多次有信使来报，但面对每次的信息，苟酝赢都淡然自若，询问后你得知了大概，你二人虽身居于此，但另一边一个属于商界的斗争正在发生，而苟酝赢的计划能让他的商会取得最终的胜利。

入夜时分传来消息，正如苟酝赢所料，一切进展全部按照他的计划进行，结果显而易见。此时，你对苟酝赢这运筹帷幄，决胜千里的手段赞叹不已，也让你见识到了何为策无遗算。NOR]],["time"]=33,["title"]=[[YEL朝令夕改NOR]]},["519"]={["id"]=519,["introText"]=[[WHT面容清俊，笑脸迎人，让人心生亲切之感NOR]],["itemId"]=[[mianju1158]],["name"]=[[BLU小二NOR]],["need"]=10,["pic"]=[[Image/UI/AttrUI/mianju/dianxiaoer.png]],["thankText"]=[[YEL你来到酒楼随即将珍品券递上，片刻后你来到二楼寻得一处雅座。你点了一些菜品，将壶中清茶倒入杯中静待。

不多时，小二将菜品整齐摆放于桌上。酒足饭饱，你再度踏上旅途离开了酒楼。你行之不久，便听闻身后有一男子高呼少侠二字，声音有些熟悉，又有些陌生。

待人行近你这才看出，此人便是方才落脚的酒楼小二。小二气喘吁吁将一个钱袋递了过来，见此你摸向腰间这才发现自己的钱袋果然不见了。

你接过钱袋并未翻查银两，反而饶有兴致的询问小二为何不将钱财收入囊中，小二对此并未做多解释，只是爽朗一笑：“少侠说笑了，咱虽穷，但志不穷，店中事务繁忙，若银两并未遗失我这便告辞，还望少侠多来酒楼捧场。”小二说完与你辞别转身离去。NOR]],["time"]=33,["title"]=[[HIW人气小二NOR]]},["52"]={["id"]=52,["introText"]=[[WHT以金、木、水、火、土次第与劈、崩、钻、炮、横五种拳法对应。属内家拳，有《内经》之艺的誉称，若练至深处，举手投足之间便可毙人性命。]],["itemId"]=[[wuxingquan1]],["name"]=[[五行拳]],["need"]=10,["pic"]=[[Image/UI/StoreUI/shujuan3.png]],["thankText"]=[[YEL满月临弓影，连星入剑端。
不学燕丹客，徒歌易水寒。
你沉吟不语，将珍品券捧于手上，似在心中思索着什么。
须臾间，空中一股浓雾飘散而来，遮蔽了你的视线。
待到浓雾散去，你蓦然发现，手上的珍品券已经变成了一本泛黄的武学秘籍，令你错愕不已。NOR]],["time"]=7,["title"]=[[全篇]]},["520"]={["id"]=520,["introText"]=[[HIW他就是幻花剑客。眉目疏朗，俊逸非凡。他抱剑立于花树下沉思，似在透过手中的吊坠望见故人，少了些萧杀，多了分落花的忧愁，左肩上绽放的将离让他更添一丝风流。NOR]],["itemId"]=[[mianju1144]],["name"]=[[MAG幻花剑客NOR]],["need"]=20,["pic"]=[[Image/UI/AttrUI/mianju/huanhuajianke.png]],["thankText"]=[[YEL樱花树下，他端详着手中的吊坠，似乎在思念着故人。也许是听到你的脚步声，他猛然回头，手默默的按住刀柄，神情由怀念转为肃杀。你连忙递上手中的珍宝券，见此他的神色才稍微缓和，只是始终一语不发。

也许是环境使然，你也没有开口询问的欲望，你与他便这么静默对视了半盏茶时间。他对着你默默地点了点头，随后从树下土地中挖出两坛酒，将其中一坛丢给了你，然后自顾自的喝了起来。喝罢，便独自离开。

忽而大风吹过，樱花散落，风中传来一阵异乡的歌谣，浪漫却又忧伤，跟他给你的酒一般滋味。NOR]],["time"]=33,["title"]=[[HIW花影随行NOR]]},["521"]={["id"]=521,["introText"]=[[HIW双眸灵动，脉脉含情。相貌似有十六七岁年纪，身形却娇小如十三四岁的小姑娘。在万花的簇拥之下，抬手轻轻折下一枝，细嗅花香，尽显兰心蕙质。NOR]],["itemId"]=[[mianju1128]],["name"]=[[HIC灵姑娘NOR]],["need"]=15,["pic"]=[[Image/UI/AttrUI/mianju/chenglingsu1.png]],["thankText"]=[[YEL自洞庭湖北行三十余里，又穿过山镇，越过深林，你终于来到了庄前。庄内圆屋式样怪异，仿若一座大坟。你心下敬畏，硬着头皮喊门，但过了许久却无人搭理。你也不好硬闯，只能转道庄旁花圃处亭子小歇，静候主人归来。

微风徐徐，你坐在亭中闻着花圃传来的香气，只觉眼皮沉重，昏昏欲睡。“这花圃里的花有古怪！”当你意识到不对的时候，已经太迟，随后便是眼前一黑。

再醒转时，却看见一个双眸灵动的少女手中拿着你的珍宝券，嘴角满是笑意。

    “你的毒已经解了。我还以为是我师兄师姐上门来了，没想到来的人是你。”你心下叹服，随即向她询问了一些辟毒的法子，她也一一向你解答，一来二去，倒也算得上交谈甚欢。NOR]],["time"]=33,["title"]=[[PNK七心海棠NOR]]},["522"]={["id"]=522,["introText"]=[[WHT她就是山鬼。她长身玉立，美撼凡尘，乌羽作冠，赤羽霓裳，宛如山间精魅，不似人间凡物，令人一见难忘。NOR]],["itemId"]=[[mianju1109]],["name"]=[[RED山鬼NOR]],["need"]=5,["pic"]=[[Image/UI/AttrUI/mianju/shangui.png]],["thankText"]=[[YEL你将珍品券递上，片刻后，幽篁林出现一只毛色斑斓的花狸，颈间带有一串草织花环。花狸对着你轻咛示意。

你随花狸进入林中，走入一处山间洞穴，却见其中另有天地。神树擎天，溪水潺潺，仙雾渺渺，恍如仙境。一位清丽绝俗的女子立于神树前，向你微微颔首，淡淡地道：“这里不常有人来。”

待你入座，女子端上一盘鲜果，你浅尝一口，只觉果肉细腻、回甘无穷。女子又拿出一精致小鼓，随后轻语诵吟，击鼓和音。女子的歌声悦耳，曲调悠扬，你不由得闭眼聆听，刹那间你好似卧于云中，世间再无何事能将你牵绊，无拘无束地游于天地间。NOR]],["time"]=33,["title"]=[[HIB岁宴华予NOR]]},["523"]={["id"]=523,["introText"]=[[WHT“孤雪融江银两岸，炽阳当空映天虹。霜寒孤寂夜无声，皎落阑珊显威芒。”这是一个通体银白的战盔，相传是以寒铁与银相融后在经由千锤锻造而出，银光闪闪，霸气威武。NOR]],["itemId"]=[[22anniversaryzb01]],["name"]=[[HIR霜日盔NOR]],["need"]=3,["pic"]=[[Image/UI/StoreUI/wuqi.png]],["thankText"]=[[YEL三尺龙泉剑，匣里无人见。
一张落雁弓，百支金花箭。
