待到浓雾散去，你蓦然发现，你的手上竟多了一件宝光四射的装备，而那张珍品券早已不知所踪。NOR]],["time"]=33,["title"]=[[HIW珍品装备NOR]]},["524"]={["id"]=524,["introText"]=[[WHT战靴内部选取上好的皮革制作而成，外部则用镔铁薄片环绕包裹，镔铁片上雕有风纹飞鸟，靴头则以一整块的镔铁镶嵌。NOR]],["itemId"]=[[22anniversaryzb02]],["name"]=[[HIR战离靴NOR]],["need"]=3,["pic"]=[[Image/UI/StoreUI/wuqi.png]],["thankText"]=[[YEL三尺龙泉剑，匣里无人见。
