待到浓雾散去，你蓦然发现，手上的珍品券已经变成了一本泛黄的武学秘籍，令你错愕不已。NOR]],["time"]=34,["title"]=[[全篇]]},["54"]={["id"]=54,["introText"]=[[WHT他就是石少侠。他剑眉入鬓，眼底无情。一身青灰色的劲装猎猎作响，双臂的缠带和漆黑的乱发随风飘扬，手持利刃，直叫人避其锋芒。]],["itemId"]=[[mianju1124]],["name"]=[[WHT石少侠NOR]],["need"]=20,["pic"]=[[Image/UI/AttrUI/mianju/shishaoxia.png]],["thankText"]=[[YEL你将珍品券递上，不一会就走出有一位身着青灰色劲装的男子，男子手持利刃，锋芒毕露，向你作揖道：“少侠久等了。”

你随男子走进入一片树林中，林中树木身上遍布剑痕，一看便知男子时常在此练剑。男子邀你在一石凳上坐下，拿出几壶好酒，说道：“早闻少侠爱酒，便叫阿绣买了些来，今日我们便不醉不归！”

你们痛饮美酒，相谈甚欢，又借着月光比试了一番，直至夜色阑珊方才告辞离开。]],["time"]=7,["title"]=[[石上行诗]]},["540"]={["id"]=540,["introText"]=[[HIW一种古武学，源远流长，据说最早可追溯自春秋战国时期，有着独到的运功和技击技巧。NOR]],["itemId"]=[[baiyuantongbeiquan]],["name"]=[[BLU白猿通背拳NOR]],["need"]=6,["pic"]=[[Image/UI/StoreUI/shujuan5.png]],["thankText"]=[[YEL满月临弓影，连星入剑端。
不学燕丹客，徒歌易水寒。
你沉吟不语，将珍品券捧于手上，似在心中思索着什么。
须臾间，空中一股浓雾飘散而来，遮蔽了你的视线。
待到浓雾散去，你蓦然发现，手上的珍品券已经变成了一本泛黄的武学秘籍，令你错愕不已。NOR]],["time"]=34,["title"]=[[全篇]]},["541"]={["id"]=541,["introText"]=[[WHT她生得婀娜多姿，盈盈妙目，顾盼间眼波流转。面上常带着花旦妆，更衬得人颜色艳丽，娇媚无双。NOR]],["itemId"]=[[mianju1111]],["name"]=[[YEL天竞门主NOR]],["need"]=25,["pic"]=[[Image/UI/AttrUI/mianju/tianjingmenzhu1.png]],["thankText"]=[[YEL你将珍品券递上，在戏楼门口热情地招呼着客人的小二立刻向你拱手道：“少侠，雅阁已为您备好，请随我来。”
你跟着小二走到二楼的一间雅阁，此间比大厅清净些，从楼台望去，能将戏台尽收眼底。你很快就被台上的戏吸引了去，连小二何时离开都不知。台上的旦角声音婉转动人，身形婀娜多姿，眉眼顾盼间便将你带入戏中人，一曲唱罢也久久不能回神。
几场戏后，小二再次前来带你走至戏院的后花园，园中有一青衣女子在小心擦拭着长琴。与戏台上的艳丽、娇媚相比，女子此时素雅、清冷了许多，就好似她们不是同一人。女子的声音依旧婉转动听，你们一起畅聊戏曲、音律，这一晚相谈甚欢。NOR]],["time"]=34,["title"]=[[GRN粉黛英姿NOR]]},["542"]={["id"]=542,["introText"]=[[WHT容貌极美，秀眉入鬓，清雅高华，难以言喻]],["itemId"]=[[mianju1044]],["name"]=[[PNK落英掌门NOR]],["need"]=4,["pic"]=[[Image/UI/AttrUI/mianju/linchaoying.png]],["thankText"]=[[YEL“惟有归于‘无缘’二字，却不知无缘系‘果’而非‘因’。”
你刚将手中的珍品券递上，便听身后传来一个苍老声音，回头看去，却不见其人。随之一旁的院门缓缓推开，落英掌门身着红裳，施施而行。
见你立于门前，落英掌门绝美容颜上显出一抹微笑：“不知少侠今日来此所为何事？今日我邀请王真人来府中商议要事，只怕要让少侠要等上片刻了。”
你与落英掌门相谈于院亭中，不多时门外跑来一个道童，道童将一封书信交予落英掌门后便匆匆离去。拆开书信，落英掌门的神色由失落渐渐转变为愤怒，直到看完书信中的内容，她的脸上尽显无奈。
道童送来书信被她攥握手中，看着园中飘落的秋叶，落英掌门竟有些木讷，口中呢喃：“好一个家国未定，何以为家。”NOR]],["time"]=34,["title"]=[[PNK古陵祖师NOR]]},["543"]={["id"]=543,["introText"]=[[WHT他生得身形挺拔，左颊一条刀疤，衬得眉目愈发粗犷，怀中抱着的长剑似乎刻满了久经江湖的沧桑之感。NOR]],["itemId"]=[[mianju1083]],["name"]=[[YEL赵武德NOR]],["need"]=24,["pic"]=[[Image/UI/AttrUI/mianju/zhaowude.png]],["thankText"]=[[YEL你将珍品券递上，片刻后出来一位高大威猛，身形挺拔的男子，他左颊一条刀疤，衬得眉目愈发粗犷。男子豪气一笑，叫你随他去。

你随着男子来到一处亭子，这亭子居然建在悬崖边上，涯边凛风呼啸，亭边仅有怪石嶙峋，全然一副萧杀之意。男子不知从何处掏出两壶好酒，将一壶扔予你，自己开了一壶，猛灌了一大口后，向你道：“倒是没想到你会来看我，今日我们不谈其他，只一醉方休！”

你们在涯边亭中开怀畅饮，确是不醉不归，直至繁星满天才有几名小厮前来将你们扶回各自房中休息。NOR]],["time"]=34,["title"]=[[HIR剑底亡魂NOR]]},["544"]={["id"]=544,["introText"]=[[WHT身形伟岸，如不老青松，渊停岳峙间自有一种狷介之气，飘逸孤高，让人一见忘俗。NOR]],["itemId"]=[[mianju1072]],["name"]=[[BLU东岛主NOR]],["need"]=9,["pic"]=[[Image/UI/AttrUI/mianju/huangdaozhu.png]],["thankText"]=[[YEL你将珍品券递上，片刻后一阵轻风忽起，随之无数花瓣漫天飞扬，落英缤纷。

你穿过桃花树一个雅致的亭子由远及近，亭下一个身穿青衣、形相清癯，萧疏轩举、湛然若神的东岛主驻足而立，看着亭子上的对联出神。你凑上前去，只见对联上用异常豪放的笔锋写着：桃花樱落飞神剑，碧海潮生按玉箫。

见你来此东岛主意味深长的看向你，随后便邀你入亭落座，你二人清茶而谈，期间东岛主以故事的形式给你讲诉了一位枭雄无畏且传奇的一生。

黄昏将至，你辞别东岛主。临行之际你回首看向亭子，回想故事中的那位绝世高手再看对联上的字似有金辉闪烁，简单的十四个字却是那位枭雄一生绝学的写照。NOR]],["time"]=34,["title"]=[[HIC名流邪师NOR]]},["545"]={["id"]=545,["introText"]=[[WHT他生得英俊白净，虽然一幅下人打扮，却有一种贵公子的神采风度，让人忍不住为其着迷。NOR]],["itemId"]=[[mianju1089]],["name"]=[[WHT风流家丁NOR]],["need"]=10,["pic"]=[[Image/UI/AttrUI/mianju/jiading1.png]],["thankText"]=[[YEL你将珍品券递上，片刻后出来一名下人装扮的男子，他对你潇洒一笑，道：“小姐今日不在，让我来带你随便逛逛。”
你随男子走到一处花园中，园中各种鲜花争奇斗艳，假山林立，一步一景。男子与你边走边聊，他虽是下人打扮但却贵气十足，谈吐高雅，举手投足间也是风度翩翩。他拾起一朵掉落的娇花，出口便成章，感叹着落花之意。男子本就俊逸潇洒，手中的娇花让他更显风流倜傥。
你们走至另一园中，此园里摆有画桌，其上置有纸张笔墨，男子随手几笔百花的之景就初具其形。男子画得投入，你不忍惊扰只在旁静观，不一会一副百花争艳图便已完成。男子将此图赠予你，你欣然收下，又闲聊了两句后便告辞离开。NOR]],["time"]=34,["title"]=[[HIY风流家丁NOR]]},["546"]={["id"]=546,["introText"]=[[WHT这是一把看起来还不错的弯刀，名字显示了铸造者的恶趣味，抛开名字不谈，似乎可堪一用。NOR]],["itemId"]=[[caidaneq02]],["name"]=[[HIM咸鱼NOR]],["need"]=3,["pic"]=[[Image/UI/StoreUI/wuqi.png]],["thankText"]=[[YEL三尺龙泉剑，匣里无人见。
一张落雁弓，百支金花箭。
你沉吟不语，将珍品券捧于手上，似在心中思索着什么。
