女子将你引入一座偏院，你在一石凳上坐好，便拿出准备好的杏脯送予女子。女子笑逐颜开，吃着杏脯又道：“少侠与我讲些江湖上的趣事和笑话吧，我要转述给殷六哥解闷。”

你与女子讲起江湖上的趣闻，女子听得开心，时不时抚掌欢笑。转眼之间，日落梢头，你便告辞离开。]],["time"]=7,["title"]=[[PNK此情无悔NOR]]},["550"]={["id"]=550,["introText"]=[[WHT重阳节人们登高时爱穿的衣服，在领边、袖边、大襟边、腰部和下摆部位分别采用印金、刺绣、彩绘等工艺，饰以茱萸、菊花等图案，简约而美观。NOR]],["itemId"]=[[20cyqreq2]],["name"]=[[WHT茱萸服NOR]],["need"]=3,["pic"]=[[Image/UI/StoreUI/wuqi.png]],["thankText"]=[[YEL三尺龙泉剑，匣里无人见。
