待到浓雾散去，你蓦然发现，手上的珍品券已经变成了一本泛黄的武学秘籍，令你错愕不已。NOR]],["time"]=35,["title"]=[[全篇]]},["56"]={["id"]=56,["introText"]=[[WHT他就是神教教主。他风华绝代，烟视媚行，慵懒雍容中又有几分伟男子的英气，让人一见难忘。]],["itemId"]=[[mianju1053]],["name"]=[[RED神教教主NOR]],["need"]=10,["pic"]=[[Image/UI/AttrUI/mianju/dongfangbubai.png]],["thankText"]=[[YEL你将珍品券递上，片刻后走出两位长袖青衫，黑纱蒙面的男子，向你拱手道：“教主有请！”

你随两位蒙面男子进入殿内，殿内宝座上正坐有一人，那人一身红衣，风华绝代，慵懒雍容之中又带有几分飒爽英姿，叫人一见难忘。他无需言语，只一抬眼，两位蒙面男子便心领神会的带你入座，端上美酒佳肴后就自行退下。

那人斜躺于宝座上，左手拿着一个绣花绷架，右手持着一枚绣花针，手指灵巧的运针引线。炎炎夏日，蚊虫纷扰，就在你们闲聊之间，飞来了一只苍蝇嗡嗡地扰人。你还未有所反应，只见银光一闪，那苍蝇便被一枚绣花针钉在柱上。转眼望去，他仍在穿针引线，似乎从未变过，你不由得赞叹其武功之高绝。]],["time"]=7,["title"]=[[YEL日出东方NOR]]},["560"]={["id"]=560,["introText"]=[[HIW天启帮聚义堂绝学之一，由章作之不断完善。秉承聚义堂一贯传统，凡是认可之人便可将武功传给他，无需受帮中规矩限制。NOR]],["itemId"]=[[yuxianjue]],["name"]=[[HIM羽仙诀NOR]],["need"]=5,["pic"]=[[Image/UI/StoreUI/shujuan5.png]],["thankText"]=[[YEL满月临弓影，连星入剑端。
不学燕丹客，徒歌易水寒。
你沉吟不语，将珍品券捧于手上，似在心中思索着什么。
须臾间，空中一股浓雾飘散而来，遮蔽了你的视线。
待到浓雾散去，你蓦然发现，手上的珍品券已经变成了一本泛黄的武学秘籍，令你错愕不已。NOR]],["time"]=35,["title"]=[[全篇]]},["561"]={["id"]=561,["introText"]=[[HIW狂傲不羁，桀骜不驯。一头黑发，一袭青衫，一只独眼，更显其傲视群雄之姿。而他伤眼上的铁护，和他掌心磅礴的吸力，似要宣告这天地间只有他一人。NOR]],["itemId"]=[[mianju1143]],["name"]=[[HIW任老魔头NOR]],["need"]=14,["pic"]=[[Image/UI/AttrUI/mianju/renjiaozhu.png]],["thankText"]=[[YEL教徒接过你手中的拜帖，领着你穿过崖间小道，向着山顶的大殿走去。约莫走了半个时辰，你远远地看到了在大殿上圣教主。

还未走近，教众忽而齐声高叫：“圣教主千秋万载，一统江湖！千秋万载，一统江湖！”你被吓了一跳，隐隐觉得有几分怪异，但身为客人终究要讲几分礼数，便执弟子礼远远地向圣教主行礼。

“不必多礼”，他似乎心情大好，“几十年不见天日，刚报了旧仇，便来了新友，不错不错！来人，上酒！”觥筹交错，你们相谈甚欢，他也指点了你一些武学上的问题，你自觉此行收获颇多。

    下得崖来，山间又传出“千秋万载，一统江湖”、“文成武德，仁义英明”的吹捧之语。你皱了皱眉，转身离去，不再回头。NOR]],["time"]=35,["title"]=[[YEL天下任行NOR]]},["562"]={["id"]=562,["introText"]=[[HIW桃腮带晕，美目流盼。她话声轻柔婉转，神态甚是悠闲，若非知她是个杀人不眨眼的魔头，还道是位带发修行的千金小姐。NOR]],["itemId"]=[[mianju1153]],["name"]=[[HIW李魔头NOR]],["need"]=17,["pic"]=[[Image/UI/AttrUI/mianju/limotou.png]],["thankText"]=[[YEL农家中，道姑左手怀抱婴孩，低声哼着童谣，右手中的拂尘轻轻挥动驱赶着蚊虫，似乎正在哄怀中的婴孩入眠。你有些错愕，那道姑分明就是江湖中凶名赫赫的“赤练女魔”，可此时却是一番慈爱模样。
似乎察觉到你来了，李魔头猛地抬头，柳眉横竖。她正欲开口说话时，你连忙递上珍宝券，简单地向她说明了来意。“惊醒了孩子你便死”，李魔头眉头缓缓舒平，轻声说了一句后，便低下头继续哼着童谣哄婴孩睡觉，不再搭理你。
    你看着眼前温柔的道姑和睡熟的婴孩，不禁想道，或许这样温柔的李魔头才是真正的她吧？NOR]],["time"]=35,["title"]=[[HIW赤练魔女NOR]]},["563"]={["id"]=563,["introText"]=[[HIW面似寒霜、不苟言笑，横眉之下眸光清冷，虽双颊微红却不染俗世脂粉，一举一动足显大家风范，无半点媚态，可敬可畏。NOR]],["itemId"]=[[mianju1080]],["name"]=[[HIW师太NOR]],["need"]=6,["pic"]=[[Image/UI/AttrUI/mianju/miejue.png]],["thankText"]=[[YEL据传峨眉山上有一处峰顶终年积雪，风霜如刀刺骨，非常人能往。你递上拜帖，依此凭证进入该地，天地一片白茫的寒气中，一道人影坐在万丈边悬崖边盘腿打坐。
听到脚步声响，她倏然睁开双眼，眸光似两道寒芒向你疾射而来，你立即行礼以晚辈自称，她放缓神色，邀你在此练功，试一试这冰霜险境的威力。
你随即打坐入定，运全身内力抵御寒气入侵，同时抛开杂思保持心如止水，以免不慎坠入悬崖。
你打坐一日，仿佛渡过几年光阴，练功结束后直叹：能面不改色日日这般苦练，前辈实乃意志坚定之人。
你心生佩服，亦有所获，向她答谢后下山，天晚寒意更浓，那道立在山尖风雪里的身影浑然如玉石所铸。NOR]],["time"]=35,["title"]=[[HIW峨眉执剑NOR]]},["564"]={["id"]=564,["introText"]=[[HIW眉目如画，虽穿着一身寻常粗布麻衣，却有种卓尔不群、宠辱不惊的气质，玩味地打量着周围，似乎早已世事洞明、曾经沧海。NOR]],["itemId"]=[[mianju1081]],["name"]=[[HIW车夫NOR]],["need"]=7,["pic"]=[[Image/UI/AttrUI/mianju/chefu.png]],["thankText"]=[[YEL你将珍品券递上，随后一阵马蹄和车轮声由远及近，车前一个身穿粗布麻衣，头戴斗笠的中年男子手握缰绳将车马停在你面前。从他卓尔不群的气质不难看出，此人似乎早已世事洞明。

车夫对着你招了招手，略带玩味的说道：“这位少侠，是否有雅兴跟在下一同远行一番？”你思索片刻便登上了马车，随后骏马一声嘶鸣，车轮飞转，你二人此便疾驰而去。

旅途中，你见了许多自然奇景，也感受了一番从不知晓的风土人情。而车夫依旧是宠辱不惊，玩味般的经历着一切，仿若这般对你如此新鲜的事景对他而言早已麻木一般。

辞别车夫，在骏马嘶鸣和车轮急转声中，这位好似曾经沧海的神秘车夫扬长而去，留下一阵洒脱自在的烟尘。NOR]],["time"]=35,["title"]=[[PNK无所不至NOR]]},["565"]={["id"]=565,["introText"]=[[HIW浪荡洒脱，不修边幅，不似那些满带金银的富公子。样貌算不得英俊，但明眸清澈，笑意盎然。且既为侠盗，从不多取一毫，乃这盗中清官，两袖空空。NOR]],["itemId"]=[[mianju1097]],["name"]=[[HIW萧侠盗NOR]],["need"]=12,["pic"]=[[Image/UI/AttrUI/mianju/xiaoxiadao.png]],["thankText"]=[[YEL你将珍品券递上，忽感微风阵阵，林间枝叶簌簌，一道侠影由远及近，甚是潇洒。

走近身前，萧侠盗略带轻浮般的说道：“这位少侠，虽不知何由，但对你有着一种似曾相识的感觉，不知少侠可愿陪我在这翠林之中走走。”

你二人来到林中空地之上，一张青苔斑驳的石桌被落叶覆盖，露出灰白一角。

你二人对坐于此，夕阳西下。萧侠盗饮尽壶中最后一口烈酒，伴随着他清唱着的一首悲凉唱词，消失在茵茵竹林之中。你坐在石凳上，回忆着方才听来的有关一对侠侣逍遥江湖的故事。

林中唱词远去，微风轻抚，枝叶簌簌作响。石桌不远处，一把锈迹斑驳的铁剑插在地上，剑柄上，一条鲜艳的红色飘带随风舞动，好似故事中的女侠，曼舞于这软玉般的翠绿之间。NOR]],["time"]=35,["title"]=[[HIB狼心独怆NOR]]},["566"]={["id"]=566,["introText"]=[[WHT两端呈尖状的戒指，正中嵌着一颗浅青玉石，玉石中有点点亮光，若细雨漂浮其中。NOR]],["itemId"]=[[eq2020cf01]],["name"]=[[HIC喜雨戒NOR]],["need"]=3,["pic"]=[[Image/UI/StoreUI/wuqi.png]],["thankText"]=[[YEL三尺龙泉剑，匣里无人见。
一张落雁弓，百支金花箭。
你沉吟不语，将珍品券捧于手上，似在心中思索着什么。
须臾间，空中一股浓雾飘散而来，遮蔽了你的视线。
待到浓雾散去，你蓦然发现，你的手上竟多了一件宝光四射的装备，而那张珍品券早已不知所踪。NOR]],["time"]=35,["title"]=[[HIW珍品装备NOR]]},["567"]={["id"]=567,["introText"]=[[WHT黄金细链上坠了一个鸭蛋大的红宝石。宝石闪亮，如若流火。NOR]],["itemId"]=[[eq2020yuanxiao5]],["name"]=[[HIR流火之链NOR]],["need"]=3,["pic"]=[[Image/UI/StoreUI/wuqi.png]],["thankText"]=[[YEL三尺龙泉剑，匣里无人见。
