女子的声如银铃，一双澄澈的眼睛望着你，神情楚楚可怜。你不忍拒绝，只得应下，跟着她来到街上。街上花灯如昼，人们熙来攘往，热闹非凡。女子身形灵巧地穿梭在人群里，不一会手中便多了两盏花灯。

逛累了，你们便寻了一座酒楼歇脚，女子要了四碟精致细点和一壶龙井，而后你们又天南地北地谈了起来。你们玩得尽兴，竟乐而忘返，直至参回斗转才相辞而别。]],["time"]=7,["title"]=[[古灵精怪]]},["570"]={["id"]=570,["introText"]=[[WHT锻造的实用书籍，上面记录了使用镔铁与精铜锻造短剑，大环刀，狼牙棒，软鞭，对剑的技艺。NOR]],["itemId"]=[[duanzaotupu2]],["name"]=[[锻造实录]],["need"]=2,["pic"]=[[Image/UI/StoreUI/shuji.png]],["thankText"]=[[YEL白发无情侵老境，青灯有味似儿时。
