她爱穿戴金银饰器，举止看似天真烂漫，实则常与毒虫为伴，谈笑间杀一人，不费吹灰之力。NOR]],["itemId"]=[[mianju1066]],["name"]=[[HIW丁红蝶NOR]],["need"]=5,["pic"]=[[Image/UI/AttrUI/mianju/dinghongdie.png]],["thankText"]=[[YEL珍品券送入不久后，走出一位侍女，垂首道：“少侠请进，切记不要随意张望。”
你跟随她身后，不时听到远处传来的惨叫声，还有周围毒虫爬行的声响，令人毛骨悚然。
很快你走进一间寨舍，坐在吊床上的丁红蝶见到你，跳下来便问：“你要不要陪我出去转一会？只待这里见客闷死了，你不用过多拘束，我可不像汉族女子那般在乎什么礼啊规矩的。”
你点头应好，于是与她一起在附近走动，倒见识了不少奇异之景，直至天边出现鱼肚白，她才依依不舍地放你离开。NOR]],["time"]=36,["title"]=[[YEL五毒仙子NOR]]},["58"]={["id"]=58,["introText"]=[[WHT这是散人顶级残页，可开出散人顶级残页。]],["itemId"]=[[sanren8]],["name"]=[[HIR散人顶级残页NOR]],["need"]=1,["pic"]=[[Image/UI/StoreUI/canye.png]],["thankText"]=[[YEL满月临弓影，连星入剑端。
