待到浓雾散去，你蓦然发现，手上的珍品券已经变成了一份残页，令你错愕不已。NOR]],["time"]=7,["title"]=[[残页]]},["580"]={["id"]=580,["introText"]=[[WHT她就是素素。她生得明媚清丽，娇艳绝伦，目光直视远方，饱含决然之色，闭眼时，泪珠滚落，似雨后梨花，凄美断人肠。NOR]],["itemId"]=[[mianju1134]],["name"]=[[HIW素素NOR]],["need"]=16,["pic"]=[[Image/UI/AttrUI/mianju/susu.png]],["thankText"]=[[YEL珍品券刚一送上，便走出一位明媚清丽的女子，她莞尔一笑，道：“少侠来了，里面坐吧。”

你随女子进入小院中坐下，女子为你倒了一杯清茶，又端上了一盘甜果。你们坐在院中聊了片刻，就听见一声孩童的呼喊，你循声望去，便见一位男童抱着一条大鱼跑进院内，一位高大俊朗的男子紧随其后，女子忍俊不禁，起身相迎。一家三口，其乐融融，让你不禁心生艳羡。

小院顿时热闹了起来，男子女子一起在厨中忙碌，你在院中给男童讲述江湖上的奇闻异事和美景美食，一时间小院皆是欢声笑语。

夕阳西斜，晚饭过后你们坐于院中闲聊。谈及师门，男子道他们也将要返回师门，言语间皆是对未来的向往，你也向他们送出祝福。直至月上梢头，你才告辞离开。NOR]],["time"]=36,["title"]=[[HIW至情至性NOR]]},["581"]={["id"]=581,["introText"]=[[WHT他就是剑神。他生得眉如利剑、面似白雪。眉心中一点剑痕，眼神明亮深邃却暗藏孤寂。剑刃握于手中，剑华流转不息，剑芒吞吐不定。试问何为剑客之心？原是一曲寂寞之情。NOR]],["itemId"]=[[mianju1136]],["name"]=[[HIW剑神NOR]],["need"]=16,["pic"]=[[Image/UI/AttrUI/mianju/jianshen.png]],["thankText"]=[[YEL你递上珍品券，庭院内从鲜花丛深处走出一位穿着雪白长衫、背着乌鞘长剑的男人。

见到你，他如远山冰雪般飘渺的神情，闪过一丝炽热的光芒，“你习武的天赋不错。”

这话虽语气平静，但你能听出里面的欣赏之意。你忍不住提出要和他切磋的要求，他却摇头拒绝，苍白的脸上有着傲视天下的冷漠：“我的剑招只为杀人。”

似不忍心见你的希望落空，他拔出那柄形势古老的漆黑长剑，在你面前演示了他的剑法，快如闪电，剑气寒意飒飒，令盛夏的晴空仿佛飘起凛冬的大雪。

待他的剑回到剑鞘，你才发觉满庭的花丛竟全部凋谢，仔细看原是被汹涌的剑气斩尽。

“凭你习武的天赋，我很期待日后能和你一较高下。”说罢，他几个闪身间跃至房梁上，施展轻功消失在了远方。NOR]],["time"]=36,["title"]=[[HIW落花吹雪NOR]]},["582"]={["id"]=582,["introText"]=[[HIW她就是神使清秋。乌云秀发，杏脸桃腮。眉如春山浅淡，眼若秋波婉转；酥胸纤腰，盛臀修腿，胜似海棠醉日，梨花带雨。一轮明月映娇颜，两只蝴蝶轻似舞。假以时日，此身容便可祸国殃民。NOR]],["itemId"]=[[mianju1146]],["name"]=[[HIW神使清秋NOR]],["need"]=23,["pic"]=[[Image/UI/AttrUI/mianju/shengshiqingqiu.png]],["thankText"]=[[YEL你方将珍品券递上，便有一位娇俏可人的女子自门后小跑而出，她拉起你的手向一条小径走去，边走边笑道：“殿里有什么好玩的，我带你去一个好地方。”
女子带着你左拐右绕，忽然间一片花海闯入你的眼帘。这里是一处山谷，谷中花开漫野，你们一走进花海就惊起几只闪着幽幽蓝光的蝴蝶。蝴蝶翩跹起舞，女子也随它们一齐起舞。她着一身淡紫长裙，颇具异域风采，舞姿娥娜，美撼凡尘。若此处是仙境，那她应是仙女，回眸一笑胜星华。
你们于花海中席地而坐，观星赏月，谈天论地，说遍天下事，不知时间流转，直至重光教徒寻来将你们带回。NOR]],["time"]=36,["title"]=[[PNK重光之女NOR]]},["583"]={["id"]=583,["introText"]=[[HIW相貌平平，乍看来只是个寻常的白发老翁，但仔细观察，却可见其眼中却流露着一股杀气，锐不可当，动人心魄。NOR]],["itemId"]=[[mianju1101]],["name"]=[[HIW厌胜老祖NOR]],["need"]=8,["pic"]=[[Image/UI/AttrUI/mianju/yanshenglaozu.png]],["thankText"]=[[YEL你方将珍品券递上，一阵妖风突然袭来，片刻后妖风将一旁巨木扳倒露出一个深坑，你决定一探究竟便顺着绳梯滑下。

你沿着坑道来到尽头，一番摸索打开了石门机关，石门之后是一个硕大的石室。

石室中放着无数珍奇异宝，你刚要进入一旁便传出一个声音：奉劝阁下就此离去，否则性命难保。

你有所犹豫还是进了石室，踏入室内只听一声脆响两旁石壁射出无数暗器，你拼命防守险些丢了性命。

届时石室中走出一位老者，你认出此人乃是精通机关术法的厌胜老祖不敢乱动。只见老祖轻推石壁，顿时室内墙壁中传出声声脆响，老祖轻叹：唉，若阁还不止步，我只得舍弃这一室珍宝了。

听闻你看着地上击落的层层暗器眉头紧皱，向讨胜老祖抱拳一礼便转身离去。NOR]],["time"]=36,["title"]=[[HIB器括寰宇NOR]]},["584"]={["id"]=584,["introText"]=[[WHT由多达16颗珍珠和几块玉石串联而成，戴在脖子上，一股沁人的凉爽久久不散。NOR]],["itemId"]=[[duanwuzb2]],["name"]=[[GRN蟾宫折桂NOR]],["need"]=3,["pic"]=[[Image/UI/StoreUI/wuqi.png]],["thankText"]=[[YEL三尺龙泉剑，匣里无人见。
