小二领着你进入酒楼内，这是一家远近闻名的酒楼，这会正值午时，大堂内是座无空席，热闹非凡。你跟着小二走到窗边，这里相比大堂中间要清净一些，而一名高大威猛的男子已坐在桌前。男子生得一张国字脸，虽带有风霜之色但也掩不住他的威严之气。你还未走近，他已起身相迎，你不由得加快了脚步。待你入座后，男子又对小二说道：“先打十斤高粱来。”
就当你们喝得尽兴时，来了两位侠客上前请男子指教，一手拿着酒壶，只用单手便将两人轻松制服。为防再有人来打扰你们的兴致，男子便打了几壶酒与你寻了一处无人的山坡们，席地而坐，喝得不知天时流转。NOR]],["time"]=37,["title"]=[[YEL契丹真龙NOR]]},["598"]={["id"]=598,["introText"]=[[WHT耳朵也尖尖，琼鼻也尖尖。灰白色的毛发比绸缎还要柔顺，圆圆的肚皮比坐垫还要柔软，乖巧巧地静坐在花枝下，似要学那猛虎细嗅蔷薇的花香。NOR]],["itemId"]=[[mianju1156]],["name"]=[[PNK狸奴入梦NOR]],["need"]=20,["pic"]=[[Image/UI/AttrUI/mianju/linu1.png]],["thankText"]=[[YEL你将珍品券递上，忽听几声喵喵直叫，低头望去，脚边竟站着一只灰头白肚的猫儿，正对着你的脚踝磨来蹭去，细长的尾巴卷起来，轻轻地拍打在你的腿肚子上，似乎在指引你往里走。
你随着猫儿向巷子里走了十余步，忽而间猫儿一钻便不见了身影，从巷子内缓缓走出一个手捧书卷的俏姑娘，眼波婉转凝望着你，文静而端庄。
你与姑娘从天上到地下，无所不谈，相谈甚欢。一只猫儿引你识得这红颜知音，只觉是缘分，只道是神奇。不知不觉，你们二人在巷子里谈到月上眉梢，夜色渐浓。NOR]],["time"]=37,["title"]=[[YEL狸奴入梦NOR]]},["599"]={["id"]=599,["introText"]=[[HIW他就是拳霸。筋肉虬结，眼神凌厉。太阳穴高高隆起，颧骨和下巴勾勒出坚毅的线条，心如猛虎，动如脱兔，伟岸的身躯似是钢浇铁铸，一双缠满绷带的铁拳无人可以匹敌。NOR]],["itemId"]=[[mianju1155]],["name"]=[[HIG拳霸NOR]],["need"]=16,["pic"]=[[Image/UI/AttrUI/mianju/quanba.png]],["thankText"]=[[YEL月影下，竹林中，传来破空之声。

你循声而至，眼前的男子果然就是你要找寻的拳霸。你趁着他练拳歇息的片刻，递上珍宝券，向他表明了来意。他虽然对你的到来略感惊异，却没有多说什么，反而拉着你陪他一起练拳。

拳来脚往，切磋之中，你发现他的招式路数与中原拳脚大不相同。比起中原精妙的拳招，他的路数更为简单，招式大开大合，威力足可劈石断碑，每一招虽然少了虚实变化，但胜在拳势刚猛，叫对手退无可退、让无可让。这一次切磋确实让你受益颇多。NOR]],["time"]=37,["title"]=[[GRN拳霸天下NOR]]},["6"]={["id"]=6,["introText"]=[[这是一个千机武盒。盒子上画着许多持刀握剑的小人，每个小人手持兵器摆出不同的姿势，一招一式有板有眼，栩栩如生。]],["itemId"]=[[2020bingqiwuxuecanpian1]],["name"]=[[    HIR千机武盒NOR]],["need"]=1,["pic"]=[[Image/UI/StoreUI/xiangzi1.png]],["thankText"]=[[YEL满月临弓影，连星入剑端。
不学燕丹客，徒歌易水寒。
你沉吟不语，将武学名录捧于手上，似在心中思索着什么。
须臾间，空中一股浓雾飘散而来，遮蔽了你的视线。
待到浓雾散去，你蓦然发现，手上的武学名录已经变成了一陈旧的宝箱，令你错愕不已。NOR]],["time"]=1,["title"]=[[宝箱]]},["60"]={["id"]=60,["introText"]=[[WHT江南七怪之一柯大侠的代表武功，传闻为达摩祖师所创，在江湖上久负盛名。NOR]],["itemId"]=[[xiangmozhangfa]],["name"]=[[降魔杖法]],["need"]=15,["pic"]=[[Image/UI/StoreUI/shujuan2.png]],["thankText"]=[[YEL满月临弓影，连星入剑端。
不学燕丹客，徒歌易水寒。
你沉吟不语，将珍品券捧于手上，似在心中思索着什么。
须臾间，空中一股浓雾飘散而来，遮蔽了你的视线。
待到浓雾散去，你蓦然发现，手上的珍品券已经变成了一本泛黄的武学秘籍，令你错愕不已。NOR]],["time"]=8,["title"]=[[全篇]]},["600"]={["id"]=600,["introText"]=[[WHT他就是韦爵爷。本是扬州人，偶然一次机会进入京城，结康熙，擒鳌拜，成为天地会香主。
此后更是平定神龙岛，妙取罗刹国，最终携七位美貌妻子，归隐于市。NOR]],["itemId"]=[[mianju1131]],["name"]=[[HIW宝爷NOR]],["need"]=15,["pic"]=[[Image/UI/AttrUI/mianju/weijueye.png]],["thankText"]=[[YEL珍品券刚送入不久，便见七位美妇款款走来。七位美妇姿容各异，好似天上的七位仙女，一时间只觉群芳争艳，香气扑鼻。见你略有呆滞，其中一位妇人轻声唤你：“爵爷正在厅内等候多时，少侠莫要让爵爷久等了，快请进来吧。”

你跟着七位美妇走进一间华贵的客厅，客厅内古董字画琳琅满目，而一位奇装异服的男子正坐在上首，你知道，此人便是韦爵爷了。

韦爵爷翘着二郎腿，歪歪斜斜靠在椅子上，嘴角露出坏笑，目视你入座后，拍着扶手问道：“少侠，我的夫人们可是各个貌美如花？”

你大笑三声，与他谈论起江湖中遇到的各个美女佳人，他听得拍手叫好，却被几位夫人醋意大发，一顿粉拳伺候。

一夜尽兴闲谈，聊得你口干舌燥方才告辞离去。NOR]],["time"]=37,["title"]=[[PNK小白龙NOR]]},["601"]={["id"]=601,["introText"]=[[HIW粉雕玉琢、灵气十足，仿佛集世间各种宠爱于一身，自有一种天不怕、地不怕的洒脱劲，整一个混世小魔头。NOR]],["itemId"]=[[mianju1059]],["name"]=[[HIW宋清秋NOR]],["need"]=5,["pic"]=[[Image/UI/AttrUI/mianju/songqingqiu.png]],["thankText"]=[[YEL你将拜帖递上，随后大门被推开，走出一位身着异域服饰的女眷。此女嫣然一笑：“少侠，久等了，小姐此时正在院亭之中，你随我来便是。”

你跟随女眷穿过前庭楼宇来到后方山脚的亭台，寒酥飘落，腊雪寒梅。亭台中，一位粉雕玉琢宛如寒雪精灵的少女正玩弄着盛开梅花的折枝，见你来此，少女微红的脸上竟露出少有的天真笑容。

你与少女在亭台中相谈良久，此刻，这个昔日的混世魔王好似换了一个人，从她的身上你能感受到一丝惆怅。可能对她而言昔日调皮活泼玩世不恭的态度，正如严冬中盛开的寒梅一般，更能表现出自己强大的内心。但在这些背后，也不过是一个年龄尚小的女孩而已。NOR]],["time"]=37,["title"]=[[HIB重光右神使NOR]]},["602"]={["id"]=602,["introText"]=[[WHT“词牌造物”之一。坊间传闻，词牌系列是干将莫邪技艺大成后的第一套作品，匠心独运浑然天成，有着巨大的收藏价值。NOR]],["itemId"]=[[2018shuang11q2]],["name"]=[[WHT八声甘州NOR]],["need"]=3,["pic"]=[[Image/UI/StoreUI/wuqi.png]],["thankText"]=[[YEL三尺龙泉剑，匣里无人见。
