两位白袍男子将你领至一悬崖边，便拱手告退。崖边有亭，亭中有人，一名青衣男子在向你招手，唤你过去。男子面如冠玉，目若朗星，卓越不凡，你刚于亭中坐好，男子便为你斟上一杯茶，笑道：“少侠来得正是时候，刚得一盒好茶。”

坐于亭中，上可触云天，下可览山河，斟上一杯清茶，你只觉心旷神怡。男子对武功见解独到，你们相谈甚欢，聊至兴起时还对上两招。NOR]],["time"]=8,["title"]=[[GRN似是而非NOR]]},["630"]={["id"]=630,["introText"]=[[WHT一面金丝螺钿镜，镜面光滑如水，漆背螺钿乃为“琴翁话酒”之图，且这月白色的螺钿自不同角度泛出七彩，精美非常，故在寻常人家难得一见。NOR]],["itemId"]=[[dyjiaju040]],["name"]=[[金丝螺钿镜]],["need"]=3,["pic"]=[[Image/UI/StoreUI/jiaju.png]],["thankText"]=[[YEL赤点朱饰韵味飘远,真才天工赏心悦目。
