待到浓雾散去，你蓦然发现，手上的珍品券已经变成了一本泛黄的武学秘籍，令你错愕不已。NOR]],["time"]=40,["title"]=[[全篇]]},["64"]={["id"]=64,["introText"]=[[WHT他就是陆千候。他身姿挺拔如苍松，气势刚健似骄阳，剑眉之下目光如炬，不怒自威，令人不敢与之直视。NOR]],["itemId"]=[[mianju1071]],["name"]=[[MAG陆千侯NOR]],["need"]=15,["pic"]=[[Image/UI/AttrUI/mianju/luqianhou.png]],["thankText"]=[[YEL正值佳节好景，你将珍品券递上陆府，片刻后出来一名黑衣护卫将你领进陆府正厅。

厅中摆设不多，正中墙上挂有字画——“清慎勤”，字的笔锋刚劲，恢弘大气。字画之下便站着一名男子，他身着黑色官府，身姿挺拔，目光如炬，不怒自威。你将手中的两壶好酒送上，但男子随手置于桌上，说到：“少侠有心了，几日不见少侠武功又有精进，不如陪我去院里松松筋骨。”

你与男子在练武场酣畅淋漓地比试了一番，看得周边的护卫们连连叫好。待炊烟四起时，男子邀你一齐用膳。摆上一桌好菜，端上你的好酒，你们开怀畅饮，直至月明星稀。NOR]],["time"]=8,["title"]=[[PNK陆大统领NOR]]},["640"]={["id"]=640,["introText"]=[[HIW白云城主所创之剑法，如青天白云无瑕无垢，剑招变化随心所欲，天下无双的剑法。NOR]],["itemId"]=[[feixianjianfa]],["name"]=[[飞仙剑法]],["need"]=5,["pic"]=[[Image/UI/StoreUI/shujuan5.png]],["thankText"]=[[YEL满月临弓影，连星入剑端。
不学燕丹客，徒歌易水寒。
你沉吟不语，将珍品券捧于手上，似在心中思索着什么。
须臾间，空中一股浓雾飘散而来，遮蔽了你的视线。
待到浓雾散去，你蓦然发现，手上的珍品券已经变成了一本泛黄的武学秘籍，令你错愕不已。NOR]],["time"]=40,["title"]=[[全篇]]},["641"]={["id"]=641,["introText"]=[[HIW面容俊秀，眉眼多情。穿着一身墨色华贵的绸缎衣袍，袍内露出一道镂空木槿花的镶边。腰系玉带，手持折扇，杏子状的眼睛如灿烂星河。NOR]],["itemId"]=[[mianju1116]],["name"]=[[HIC移花公子NOR]],["need"]=20,["pic"]=[[Image/UI/AttrUI/mianju/huagongzi.png]],["thankText"]=[[YEL你将珍品券递上，随后气派的山门被推开，从中走出一位美艳女子。

你与女子进入移花宫内，不多时，你便被带入会客厅内，厅中一个绝世美人坐在主位之上，此女拥有绝顶美丽的面孔和一双仿佛洞悉一切的美眸，气质出尘，绝代风华。而她身旁的客位上，风神俊朗的少宫主华公子正紧锁眉头看着手中的古卷。

绝世美人离开后，花公子如释重负。随后你二人进入偏厅，片刻一行弟子乘上美味佳肴，来人无一不对花公子的俊朗外表所青睐，偷偷观瞧羞红了俏脸。

皎月如镜，月光如水。花公子将你送出移花宫，临走之时，花公子送予你一把折扇，扇面上苍劲的毫锋书写了一首名为“绝代双骄”的诗词，词中故事可歌可泣，让人泪下。NOR]],["time"]=40,["title"]=[[HIW花落无缺NOR]]},["642"]={["id"]=642,["introText"]=[[WHT她就是紫衣姑娘。她颜若朝霞，双眸灿烂。眼神总有狡黠之色，眉宇之间似笑非笑。乌溜溜的眼中透着古灵精怪，亦正亦邪的气质，让人难识其本性。NOR]],["itemId"]=[[mianju1129]],["name"]=[[MAG紫衣姑娘NOR]],["need"]=17,["pic"]=[[Image/UI/AttrUI/mianju/ziguniang.png]],["thankText"]=[[YEL你刚将珍品券送上，便听见林间瑟瑟作响，一团漆黑的东西忽地向你袭来，你身形一闪，灵巧躲过。而那团漆黑的东西落在地上瞬时舒展开来，原是一条漆黑的长蛇，蛇头呈三角状，身有手腕粗，吐出的蛇信子红中带黑，你一瞧便知它剧毒无比。
一枚银针忽地扎入蛇身，方要游走的黑蛇扭动了几下便瘫软在地一动不动了。“你躲得倒是挺快。”话音刚落，一位身着松花绿衣裙的女子自花树间钻出，看着你笑道：“我在这捉了一天的蛇，甚是无聊，你陪我至山下转转。”
你点头应好，与她前往山下镇子，市井热闹，摊贩林立，你们好一阵玩耍，直至夜深才告辞分别。NOR]],["time"]=40,["title"]=[[HIR恶紫夺朱NOR]]},["643"]={["id"]=643,["introText"]=[[HIW孤高冷艳，凛然动人。长发飘逸，上插玉簪两枚。额前留着几缕碎发，眼泛红晕，耳戴碧玉环，红唇浓抹，目光冷绝，常人不敢与之对视。NOR]],["itemId"]=[[mianju1123]],["name"]=[[HIW周姑娘NOR]],["need"]=21,["pic"]=[[Image/UI/AttrUI/mianju/zhouzhangmen.png]],["thankText"]=[[YEL你将珍品券递上，随后金碧辉煌的大门缓缓打开走出一位身姿曼妙的女子，女子对你欠身一笑：少侠里面请，掌门就在殿中。
  你随女子漫步于金殿之中，殿外虽白雪皑皑寒风刺骨，但在这金殿之内却温暖舒适，院中潺潺流水升腾着若隐若现的雾气，池水旁一片绿意盎然，生长着许多从未见过的奇珍异草。
  你随女子穿过院子来到中庭，只见庭内一位身着黑红长衣的绝美女子倚靠在椅上看着手中书籍，待你来此的女子对其微微躬身道了句：掌门，少侠已带到。后便转身离去。
  你与周姑娘相谈良久，她虽孤高冷艳，凛然动人，但相谈间每逢提到先师遗愿眼中便满是坚毅向往之色，离别之时周姑娘站在金殿门前，望着周围的白雪她轻叹一声：问心无愧便好。NOR]],["time"]=40,["title"]=[[HIW汉水之缘NOR]]},["644"]={["id"]=644,["introText"]=[[HIW面如冠玉，剑眉星目，丰神俊朗。他闭目凝神，轻拍折扇，若有所思；陡然间他睁开双眼，嘴角微微上扬，你一瞬间便已明了，他必是想出了赚钱的门路，只是不知道哪个倒霉鬼又要遭殃了。NOR]],["itemId"]=[[mianju1159]],["name"]=[[HIY陈撰乾NOR]],["need"]=11,["pic"]=[[Image/UI/AttrUI/mianju/chenzhuanqian1.png]],["thankText"]=[[YEL你将珍品券递上，随后跟随伙计进入店中。你刚落座便听到旁桌陈撰乾与一独眼男人攀谈。

独眼男人取出一物，此物形为卧虎，通体黝黑，是一只纯铁打造的虎雕。但虎眼处残缺，仅有两个空洞。

陈撰乾收起折扇，掂量铁虎随后伸出一指。在二人随后的交谈中，你得知独眼男人想将铁虎高价卖给陈撰乾，而陈撰乾则以铁虎材质和残缺为由给出了极低的价格。

二人交谈半晌，独眼男人最终同意了陈撰乾给出的价格匆匆离去。你见此凑上身来与陈撰乾攀谈，闲聊之中你把玩着手中的铁虎，好奇之下刮了刮铁虎一侧，随着刮动铁虎表面的黑色一点点褪去，露出了耀眼的金色。

你一脸震惊看向陈撰乾，他则是一脸得意的坐在对面慢条斯理品味着杯中浓茶，笑而不语。NOR]],["time"]=40,["title"]=[[YEL生财有方NOR]]},["645"]={["id"]=645,["introText"]=[[WHT她就是沐临烟。她生得玉骨冰肌，古人若说起闺阁小姐、大家闺秀总归便是她这般的姿态。她虽能惊艳一堂，却少了与其他美人区分开来的特点。倘若真要说出个什么不同，便是她眼下泪痣，目中情深。但江湖，似乎并不需要这样娇滴滴的美人。NOR]],["itemId"]=[[mianju1094]],["name"]=[[HIC沐临烟NOR]],["need"]=6,["pic"]=[[Image/UI/AttrUI/mianju/mulingyan.png]],["thankText"]=[[YEL你将珍品券递上，片刻后走出一位青衣侍女，恭敬道：“小姐有请。”
你随侍女穿过长廊，走到后院的花园中。你一眼便瞧见了那颗树冠红似火的红枫，脑海里不禁冒出那句“停车坐爱枫林晚，霜叶红于二月花。”
更引人注目的是红枫树下的那一抹蓝色身影，一位女子抱琴立于树下，她只略施粉黛，着靛青长裙，纤腰婀娜，宛若仙姝，不减神女。虽似莲花般清雅，但也带有寒梅的傲骨。
你们坐于红枫下，她问起你近况如何？在江湖闯荡可有受伤？又道你是她少有的朋友，随后她弹起一首新学的曲子。琴声婉转，似山泉自幽谷缓缓流淌而来，在你心头萦绕不去。NOR]],["time"]=40,["title"]=[[HIW江湖三友NOR]]},["646"]={["id"]=646,["introText"]=[[WHT一件棉袄长衫，上绣春柳，有停留盼春之意，寓在抵御严寒，同时会让人想起游子离家，慈母连夜缝衣之景，倍感温暖。NOR]],["itemId"]=[[2019hyjeq02]],["name"]=[[BLU春晖袄NOR]],["need"]=3,["pic"]=[[Image/UI/StoreUI/wuqi.png]],["thankText"]=[[YEL三尺龙泉剑，匣里无人见。
一张落雁弓，百支金花箭。
你沉吟不语，将珍品券捧于手上，似在心中思索着什么。
须臾间，空中一股浓雾飘散而来，遮蔽了你的视线。
待到浓雾散去，你蓦然发现，你的手上竟多了一件宝光四射的装备，而那张珍品券早已不知所踪。NOR]],["time"]=40,["title"]=[[HIW珍品装备NOR]]},["647"]={["id"]=647,["introText"]=[[WHT白色锦缎制成的长袍，其后绣着一个太阳和两只羽毛，有凌空飞羽之意。此刺绣极为精细，为苏州第一女红精心绣成。NOR]],["itemId"]=[[eq2020spring3]],["name"]=[[YEL羽日袍NOR]],["need"]=3,["pic"]=[[Image/UI/StoreUI/wuqi.png]],["thankText"]=[[YEL三尺龙泉剑，匣里无人见。
