待到浓雾散去，你蓦然发现，你的手上竟多了一件宝光四射的装备，而那张珍品券早已不知所踪。NOR]],["time"]=40,["title"]=[[HIW珍品装备NOR]]},["648"]={["id"]=648,["introText"]=[[WHT这是一件朝春裳，淡红色的布料，背面绣着一个黑线描边的‘春’字。正面绣着一棵挂着红色小灯笼的大梅花树，底下一群小孩子正穿着新装，放着鞭炮。NOR]],["itemId"]=[[gnzitem8]],["name"]=[[HIR朝春裳NOR]],["need"]=3,["pic"]=[[Image/UI/StoreUI/wuqi.png]],["thankText"]=[[YEL三尺龙泉剑，匣里无人见。
