待到浓雾散去，你蓦然发现，你的手上竟多了一件宝光四射的装备，而那张珍品券早已不知所踪。NOR]],["time"]=40,["title"]=[[HIW珍品装备NOR]]},["649"]={["id"]=649,["introText"]=[[WHT一件名贵的貂裘，通体漆黑， 更无一根杂毛。据说出自塞北某位大汗的宝库。NOR]],["itemId"]=[[2018zqeq001]],["name"]=[[HIW貂裘NOR]],["need"]=3,["pic"]=[[Image/UI/StoreUI/wuqi.png]],["thankText"]=[[YEL三尺龙泉剑，匣里无人见。
