你沉吟不语，将珍品券捧于手上，似在心中思索着什么。
须臾间，空中一股浓雾飘散而来，遮蔽了你的视线。
待到浓雾散去，你蓦然发现，你的手上竟多了一件宝光四射的装备，而那张珍品券早已不知所踪。NOR]],["time"]=40,["title"]=[[HIW珍品装备NOR]]},["65"]={["id"]=65,["introText"]=[[WHT他就是沈元龙，金钱帮经营酒楼生意的行首。
他本是秀才出身，多年前受老会首之恩，放弃科考，转而报答金钱帮。
有人笑说他不是个商人，但随着金钱帮酒楼生意日益兴盛，再没有人提及过此事。NOR]],["itemId"]=[[mianju1074]],["name"]=[[HIW沈元龙NOR]],["need"]=10,["pic"]=[[Image/UI/AttrUI/mianju/shenyuanlong.png]],["thankText"]=[[YEL你将珍品券递上后，金钱帮的小厮将你迎了进去。
不过一盏茶的功夫，一个略微清瘦的男子半敛着衣袖走了出来，朝你拱手道：“有失远迎。”
你正欲开口，却发现他的衣袖间沾染了点点墨痕，沈元龙顺着你的目光抬袖一看，羞赧笑道：“失礼失礼，匆忙见客连沾了墨痕也不自知。”
江湖传闻中的沈元龙，既是索债催命的恶鬼，亦是乐善好施的贤者，但此刻于你而言，他不过是好客的账房先生，兴许平日里还会吟上几句诗书。
你们随后谈了很多江湖中的趣事，兴尽方归。NOR]],["time"]=8,["title"]=[[RED铁算行首NOR]]},["650"]={["id"]=650,["introText"]=[[WHT这是曾巩的书法作品。书法结字修长，笔画清劲，寥寥百字，道尽心中的沉郁孤愤，是难得的传世之作。NOR]],["itemId"]=[[dyjiaju010]],["name"]=[[局事帖]],["need"]=3,["pic"]=[[Image/UI/StoreUI/jiaju.png]],["thankText"]=[[YEL赤点朱饰韵味飘远,真才天工赏心悦目。
一坐立感气宇轩昂,轻拭再叹鬼斧天工。
你沉吟不语，将珍品券捧于手上，似在心中思索着什么。
须臾间，空中一股浓雾飘散而来，遮蔽了你的视线。
待到浓雾散去，你蓦然发现，地上竟摆着一件古朴的家具，令你错愕不已。NOR]],["time"]=40,["title"]=[[HIW珍品家具NOR]]},["651"]={["id"]=651,["introText"]=[[WHT浮生若梦，为欢几何？此书由沈复所著，讲述其生平见闻以及与妻子陈芸平凡而充满情趣的生活。NOR]],["itemId"]=[[yeshushuji76]],["name"]=[[HIY浮生六记NOR]],["need"]=3,["pic"]=[[Image/UI/StoreUI/shuji.png]],["thankText"]=[[YEL白发无情侵老境，青灯有味似儿时。
