待到浓雾散去，你蓦然发现，手上的珍品券已经变成了一本泛黄的武学秘籍，令你错愕不已。NOR]],["time"]=41,["title"]=[[全篇]]},["659"]={["id"]=659,["introText"]=[[WHT他就是令狐掌门。他长方脸蛋，剑眉薄唇，此时抱剑而立，尽显豪侠之气。NOR]],["itemId"]=[[mianju1047]],["name"]=[[YEL令狐掌门NOR]],["need"]=25,["pic"]=[[Image/UI/AttrUI/mianju/linghuzhangmen.png]],["thankText"]=[[YEL珍品券刚一送上，大门登时被人推开，走出一位步履飘逸，举止潇洒的英俊男子。男子爽朗一笑，向你说了句：“来吧！少侠！”

你随男子进到后院，不料此院竟然建在高山峰顶之上，四周云雾缭绕，劲风猎猎作响，真乃人间仙境。只见男子拔剑一挑，一坛美酒便从架子上一跃而起，钻入你怀中。待你错愕之时，男子出剑再挑，又将一坛美酒挑起，稳稳落到剑尖之上。只听男子爽朗一笑：“少侠，请！”却不知他如何破开泥封，竟舞剑而饮。

剑出游龙，剑尖美酒分毫不差落入男子口中，惹得你拍案叫绝，只得也拍开泥封，二人一醉方休，不知东方之既白。]],["time"]=41,["title"]=[[PNK独孤笑傲NOR]]},["66"]={["id"]=66,["introText"]=[[WHT他就是凌云，他生得气宇轩昂，谦和有礼，为人处世时皆秉公执法，不苟言笑。一身的官服将他紧紧束缚，但这种束缚不过是求仁得仁，他心甘为民，若然揭去铁面，亦是一个普通的江湖人。NOR]],["itemId"]=[[mianju1095]],["name"]=[[WHT凌云NOR]],["need"]=5,["pic"]=[[Image/UI/AttrUI/mianju/linyun.png]],["thankText"]=[[YEL你将珍品券递上，大门登时被人推开，走出一位气宇轩昂的捕头，他官服贴身，铁面半掩，腰别长剑，英姿焕发。见你来访，他亦惊喜万分，但恰不逢时，他正要去办案。

你正好闲来无事，便提出与他同去，关键时刻也可帮上一二，凌捕头闻言欣然同意。你与他四处走访查探，一天的时间就这样悄然而逝，月落梢头才将将结束。

为答谢你出手相助，他邀你至春在楼饮酒，但只闲聊片刻，他便赶回衙门继续处理案情。你独坐楼台自饮，感慨凌捕头的一心为民。NOR]],["time"]=8,["title"]=[[HIY铁面无私NOR]]},["660"]={["id"]=660,["introText"]=[[WHT她就是丁香。她秀丽绝俗，身姿丰盈，樱桃小口灵巧端正，双眸清亮，坚毅的眼神中带着一丝勇往直前的锐利，偶尔也会露出狡黠之光，展现清纯活泼一面，叫人心生喜爱，又痴又叹。NOR]],["itemId"]=[[mianju1118]],["name"]=[[MAG丁香NOR]],["need"]=20,["pic"]=[[Image/UI/AttrUI/mianju/dingxiang1.png]],["thankText"]=[[YEL你刚将珍品券递上，便走出一名天山派的女弟子，向你作了一揖道：“四师姐让我带你过去，请随我来。”
你与女弟子走到一处山崖边，一位秀丽绝俗，身姿丰盈的女子正在此习武。虽只是基础的招式，但女子不曾有丝毫怠慢，整个人沉稳、坚毅，还带有一丝勇往无前的锐利。你与她一起讨论武学，期间还比试了一番，待日暮时分正准备告辞离开时，女子忽然开口道：“山下镇子的夜市热闹得很，不如一起去逛逛？”
夜市灯火通明，人影攒动，果真热闹非凡。女子换了一套蓝色的衣裙，头戴狐狸面具，手拿一根糖葫芦穿行在摊贩间。双眸清亮如星，樱桃小口未曾停下过，似黄鹂一般，清纯活泼，叫人心生喜爱。NOR]],["time"]=41,["title"]=[[PNK江湖三友NOR]]},["661"]={["id"]=661,["introText"]=[[WHT她就是落英女侠。何彼秾矣，华如桃李。一双脉脉含情的眼眸，一条缀满铜铃的发带，一件艳红明丽的衣裳，好似一位身着嫁衣的女子，正在翘首盼望意中人的到来。NOR]],["itemId"]=[[mianju1137]],["name"]=[[RED落英女侠NOR]],["need"]=15,["pic"]=[[Image/UI/AttrUI/mianju/chaoyingnvxia.png]],["thankText"]=[[YEL你通过拜帖进到终南山山顶，梅林间一红衣女子正在月下用指拭剑。

“久闻少侠大名，可有兴趣和我比划几招？”

你知前辈武功高深，有心见识一番，故而欣然应允。

比试中，她剑影如蛟龙戏水，又有百般变化，你一招刚起，她破解之法顷刻随出，游刃有余，简直毫无破绽。

你越发心惊，但更觉佩服，结束后向前辈郑重施了一礼，她嫣然笑道：“我该好好谢你才是。”

你尚且不解，只听她笑声畅快，“我正在创一套克制全真武功的剑法，遇到几处难点，和你切磋完竟有了些眉目，少侠觉得我这剑法能否大成？”

练一番惊世武功已是难事，何况自创，但你见她眸光烨烨，那般神采飞扬，不由肯定地点头。NOR]],["time"]=41,["title"]=[[MAG古陵深情NOR]]},["662"]={["id"]=662,["introText"]=[[WHT温文尔雅，眉清目秀。手执一柄折扇，身穿淡黄锦缎长袍，眉目和善，极尽温柔。温润如玉，却又带三分潇洒。NOR]],["itemId"]=[[mianju1120]],["name"]=[[HIW段潇NOR]],["need"]=5,["pic"]=[[Image/UI/AttrUI/mianju/duanxiao.png]],["thankText"]=[[YEL你日夜兼程，忽觉口舌干燥，便在路边茶摊叫了一碗茶水，坐下歇脚。

正喝着茶，你望见一人影很是熟悉，其着淡黄锦袍、银冠束发，温文尔雅又不失潇洒。你瞧着人影像是段潇，忙上前叫住了他，只见人影回过身来，是个陌生的公子。

你认错了人，也觉尴尬，一番道歉后正要回到茶摊，却听闻身后传来一声轻叹道：“江湖路远，相见争如不见……”

你转身回望，只见天高云淡，渺渺曲径上，一人一马徐徐前行。

你思量了一会，将茶钱和珍品劵放于桌上，往来时的方向离开了。NOR]],["time"]=41,["title"]=[[PNK江湖三友NOR]]},["663"]={["id"]=663,["introText"]=[[WHT身材甚高，风姿飒爽，英气勃勃，飘逸绝伦。NOR]],["itemId"]=[[mianju1043]],["name"]=[[HIW王真人NOR]],["need"]=4,["pic"]=[[Image/UI/AttrUI/mianju/wangchongyang.png]],["thankText"]=[[YEL你将珍品券递上，片刻后门内走出一个道童对你抱拳一礼道：“少侠请进，真人在后山福地等你。”
      你随道童来到后山，此地百花争艳，林中更是莺歌阵阵。一旁山泉顺势而下，升腾的水雾让此地如梦如幻。
      你与王真人在此美景之中彻谈功法大道，良久，茶尽杯空，王真人执剑于手，舞出一套无比精妙的剑法，其剑招玄妙，每一式中都蕴含着无数微妙之变，让你叹为观止，心生敬畏。
就在套剑法最后一式击出之时，落英掌门执剑由你身后飞跃而出，其剑势狠厉剑法精妙，瞬间将王真人这最后一式化解。王真人见落英掌门淡淡一笑，随后专攻为守，化解了落英掌门紧随的几招。这二人亦攻亦守，长剑相接发出清脆之音，好生自在。你见二人兴致正浓便不再打扰转身伴霞而去。NOR]],["time"]=41,["title"]=[[BLU全真祖师NOR]]},["664"]={["id"]=664,["introText"]=[[一条海青色长裤，布料结实，染色均匀。裤型宽松，穿着舒适。]],["itemId"]=[[2020zhounian04]],["name"]=[[趋海裤]],["need"]=3,["pic"]=[[Image/UI/StoreUI/wuqi.png]],["thankText"]=[[YEL三尺龙泉剑，匣里无人见。
