待到浓雾散去，你蓦然发现，手上的珍品券已经变成了一本泛黄的武学秘籍，令你错愕不已。NOR]],["time"]=42,["title"]=[[全篇]]},["677"]={["id"]=677,["introText"]=[[HIW他就是骑士莱恩。眼眸深邃，鼻梁高挺。他一身钢铁重甲，碧绿的眼睛，金黄的头发，棱角分明的面容显得刚毅不屈。身后的士兵引吭高歌，胸前的徽记烨烨生辉。NOR]],["itemId"]=[[mianju1145]],["name"]=[[骑士莱恩]],["need"]=25,["pic"]=[[Image/UI/AttrUI/mianju/fengbaoqishilaien.png]],["thankText"]=[[YEL你递上拜帖，被仆人们引到古堡深处。见到他时，你有点错愕，眼前的男子身穿异国礼服，尽显雍容华贵，与你印象中那个一身铁甲的身形确实相差太大。莱恩被你错愕的表情逗得开怀一笑，随后便拉着你去到了庭院小歇。

伴着夕阳的余晖，莱恩与你坐在太阳伞下，品尝着他家乡的甜点与红茶。不得不说，异乡的食物确实别有风味，让你心生喜欢。

“来中原那么久，难得有人来我这儿做客。我很喜欢中原，这里很美，很有活力。”莱恩又细品了一口红茶，继续道，“但这里的人们缺乏信仰，我希望重光的光辉有一天能照射到中原各地。”

    “愿重光赐予你祝福。”NOR]],["time"]=42,["title"]=[[风暴神使]]},["678"]={["id"]=678,["introText"]=[[WHT他就是胡大侠。面似寒霜，冷傲逼人。一对墨眉有如柳叶般纤细，一双眼眸好似狐狸般狭长，他手握单刀，冰冷的眼神散发出似有若无的杀意，令人胆寒。NOR]],["itemId"]=[[mianju1127]],["name"]=[[胡大侠]],["need"]=24,["pic"]=[[Image/UI/AttrUI/mianju/hufei.png]],["thankText"]=[[YEL寒冬腊月，飞雪纷纷，你根据百晓生的指引独自北上，前往长白山深处去寻找那道侠影。

雪地中，男子舞着手中的长刀，他身形腾挪，刀影翻飞，灵动迅捷，犹如雪狐般机敏。舞至精彩处，你忍不住叫了声“好”，他循声向你望来，或许是你手中的珍宝券，让他冷峻的神色稍稍缓和。只见他身影几下闪动便到了你跟前，他手中黑刀径直向你横削而来，只是出刀的速度比上先前却是慢了几分，你心下了然，拔出长剑向他攻去。

拆招五百余合，不分胜负，你们哈哈一笑罢手停战，拿出酒壶痛饮一番。你醉倒之前，依稀还记得他轻唱的歌谣，“来日大难，口燥舌干。今日相乐，皆当喜欢。”NOR]],["time"]=42,["title"]=[[MAG雪山侠行NOR]]},["679"]={["id"]=679,["introText"]=[[HIW她就是奎丽尔。金发碧眼，轻盼曼顾。那美丽的头发披散在身上，像一股金色的瀑布．波浪起伏，金光闪闪。来自大秦的红绸穿过锁骨，盖过细腰，勾勒出惊心动魄的美艳弧线。NOR]],["itemId"]=[[mianju1157]],["name"]=[[奎丽尔]],["need"]=20,["pic"]=[[Image/UI/AttrUI/mianju/kuilier.png]],["thankText"]=[[YEL尽管早已做好了心理准备，但是在她脱去黑袍，展现真身时，你双颊通红，心还是忍不住跳慢了一拍。

金发碧眼，曼妙无双，她对你浅笑的刹那，你下意识地想起了一句诗，“回眸一笑百媚生，六宫粉黛无颜色。”

“嘻嘻，我们那边的女子很多都是我这样的穿着。你用不着那么惊奇。”也许是夜晚时分身边的人并不多，又或许是她突然兴起，她径直挽起你的手向秦淮河畔走去，“秦淮河的风景很美，我真的很喜欢。”说罢，她对着你又是浅浅一笑。
你们挑了个能观赏江景小亭，便坐下举杯相饮。

晚风吹拂，秦淮河上流光溢彩，画舫相连灯火通明，耳畔传来歌女清唱，才子吟诵，酒客痛饮之声，身边的少女脸带微笑沉浸其中。你看着眼前的景象只觉似醉非醉，却不愿醒来。NOR]],["time"]=42,["title"]=[[大秦少女]]},["68"]={["id"]=68,["introText"]=[[WHT流传于东南一代的内功，不同于其它内功注重阴阳调和，此功只重刚猛阳劲的修炼，且常逆行阳劲用以伤敌。NOR]],["itemId"]=[[niyangong]],["name"]=[[逆焰功]],["need"]=31,["pic"]=[[Image/UI/StoreUI/shujuan1.png]],["thankText"]=[[YEL满月临弓影，连星入剑端。
不学燕丹客，徒歌易水寒。
你沉吟不语，将珍品券捧于手上，似在心中思索着什么。
