待到浓雾散去，你蓦然发现，手上的珍品券已经变成了一本泛黄的武学秘籍，令你错愕不已。NOR]],["time"]=9,["title"]=[[全篇]]},["680"]={["id"]=680,["introText"]=[[WHT他身躯凛凛，相貌堂堂。一双眼睛射寒星，两弯剑眉如刷漆。气宇轩昂，大红的舞狮头肩上扛。从容不迫，将脑后束起的一根长辫咬在口中。NOR]],["itemId"]=[[mianju1130]],["name"]=[[黄师傅]],["need"]=17,["pic"]=[[Image/UI/AttrUI/mianju/huangshifu.png]],["thankText"]=[[YEL珍品券送入不久后，走出一位身着黄布衣的男子，拱手道：“黄师傅正在做准备，请少侠稍等。”

你方与男子聊了两句，前边突然开始敲锣打鼓，人群也喧闹了起来。你随着人群往前方走去，便见着一位气宇轩昂的男子，扛着大红的舞狮头随着鼓点起舞。时喜时醉，时惊时怒，在木桩上灵巧跃动，表演得形神合一，生动活泼。

一场舞狮结束，你只觉意犹未尽，正巧此时黄布衣的男子替黄师傅来邀你至武馆中一叙，你欣然同意。武馆中，黄师傅早已命人备好茶水，你们畅谈古今，相谈甚欢，竟忘了时间，待回过神来已是华灯初上，你才依依不舍地告辞离去。
NOR]],["time"]=42,["title"]=[[RED醒狮飞鸿NOR]]},["681"]={["id"]=681,["introText"]=[[WHT她就是雩。她生得娉婷秀雅，头戴青冠赤羽，身穿青袍，面上涂了几抹红妆，神情肃穆，在为祈雨仪式准备着。]],["itemId"]=[[mianju1103]],["name"]=[[PNK雩NOR]],["need"]=5,["pic"]=[[Image/UI/AttrUI/mianju/yu.png]],["thankText"]=[[YEL你将珍品券递上，片刻后走出一位青衣女子，青衣女子笑靥如花，向你道：“少侠，请随我来。”

你随青衣女子走进一座高楼，高楼里人声鼎沸，高楼外人头攒动，都是前来参加祈雨仪式的百姓。你随青衣女子走进一间雅座，刚一落座便有人端上了茶水、糕点。青衣女子笑着道：“烦请少侠静候片刻，祈雨仪式即将开始。”

你才饮下一杯清茶，只觉楼外忽然寂然无声，片刻又听见鼓乐震天，抬眼望去原是祈雨仪式开始了。只见一位头戴青冠赤羽，身穿青袍，面上涂了几抹红妆，神情肃穆的女子站在祭坛上诵词起舞，你忽然觉得周边清凉了许多。你静心观看，一场仪式结束，仍觉意犹未尽。]],["time"]=42,["title"]=[[YEL执羽舞器NOR]]},["682"]={["id"]=682,["introText"]=[[假托《山海经》中异兽之名所铸的兵刃之一。铸造之人喜读异兽怪谈，又有炼制神兵之技，遂铸了一套兵刃，聊慰平生。]],["itemId"]=[[eq2020xslb15]],["name"]=[[HIG数斯NOR]],["need"]=3,["pic"]=[[Image/UI/StoreUI/wuqi.png]],["thankText"]=[[YEL三尺龙泉剑，匣里无人见。
