待到浓雾散去，你蓦然发现，手上的珍品券已经变成了一本泛黄的武学秘籍，令你错愕不已。NOR]],["time"]=43,["title"]=[[全篇]]},["695"]={["id"]=695,["introText"]=[[WHT传闻他武功极高，曾与唐家唐不平交手三百回合不落下风。他面如冠玉，眉宇间英气十足，不怒自威，举手投足之间散发着一股慵懒之意。传言说其本是女儿身，但对外宣称为男人，以便行走江湖，统治帮派。NOR]],["itemId"]=[[mianju1099]],["name"]=[[HIM幽冥教主NOR]],["need"]=20,["pic"]=[[Image/UI/AttrUI/mianju/youmingjiaozhu1.png]],["thankText"]=[[YEL珍品券刚一递上，蓦然间你只听见一声低沉地耳语：“随我来。”声音如冷冽的寒潭，却让人分辨不出男女。你只觉腰间肋下被人裹挟住，随后身子一轻，整个人竟然腾空而起，向着某个方向凌空飞去。

迷迷糊糊间，你身后之人托着你飘然落地，你睁眼一看，竟来到一座阴森死寂的佛殿之中，殿中左右两侧各站着五尊巨大佛像，正是十殿阎罗王。

“无常善勾恶人命，七宝可避万般劫。既然少侠愿投拜帖于本座，本座便与少侠说一说这十殿阎罗的故事。”冷冽的声音从你背后响起，将每位阎罗的故事娓娓道来。

你虽然觉得有些惊怕，但却沉浸在这些鲜为人知的故事中，直至东方之际白。NOR]],["time"]=43,["title"]=[[MAG十殿阎罗NOR]]},["696"]={["id"]=696,["introText"]=[[WHT她肤嫩如雪，眉眼如画。水蓝色的发饰，淡红色的束带，衬上一头栗色的长发。柔情无限，眼波盈盈，羞红的脸上挂着浅笑，贝齿轻咬着发带，只觉分外可爱。NOR]],["itemId"]=[[mianju1138]],["name"]=[[PNK无悔妹妹NOR]],["need"]=14,["pic"]=[[Image/UI/AttrUI/mianju/buhuimeimei.png]],["thankText"]=[[YEL跛足小鬟接过你的拜帖，嘶声道：“小姐人在前面。”

花园中，一位娉娉袅袅的少女足点花心，穿梭彩蝶间扑蝶，回眸多娇，“少侠快来帮我。”

你施展轻功，将飞舞的蝴蝶赶入蝶网，不知为何，她又将蝴蝶放出，神色黯然地邀你一起坐在石桌边，“爹最近愁眉苦脸，可我却帮不了他什么，也不便出去玩耍。”
你见她面带愁容，便与她说起江湖上的趣事，终于令她露出笑颜，待天色昏暗，你提出告辞，走出一段距离后，似有所感地回头一望，只见她手扶圆供门侧，仍在依依不舍地目送你。NOR]],["time"]=43,["title"]=[[PNK此情无悔NOR]]},["697"]={["id"]=697,["introText"]=[[WHT温文尔雅，秀外慧中，目若秋水，动人传情。长发迎风飘动，好似甘泉玉露倾泻而下，一袭浅衣彰显清雅。身嵌丛花之中飘然灵动，薄唇微动气若幽兰，颈前佩戴金丝花坠，平添了一份淡雅之气。NOR]],["itemId"]=[[mianju1179]],["name"]=[[柳芊芊]],["need"]=11,["pic"]=[[Image/UI/AttrUI/mianju/liuqianqian.png]],["thankText"]=[[YEL你来到一间小院，将珍品卷递上，未待多时，院门被人推开，一位女子轻移莲步向你走来。

女子微施一礼，道：“少侠，许久不见，近来可好？”

你与女子寒暄片刻，随后跟其来到一处湖边凉亭。亭外玉兰若雪，亭内清茶飘香，你在亭中入座，与女子一起赏花品茶，安闲自得。NOR]],["time"]=43,["title"]=[[PNK似水柔情NOR]]},["698"]={["id"]=698,["introText"]=[[WHT脸长面方，颏下微有须，颇有些豪放不羁的气质，此时正抱着个烧鸡，吃得正香。NOR]],["itemId"]=[[mianju1058]],["name"]=[[HIW老叫花NOR]],["need"]=7,["pic"]=[[Image/UI/AttrUI/mianju/hongqigong.png]],["thankText"]=[[YEL你递上珍品券，便见有一身着干净粗布衣的老者向你走来，老者豪迈一笑，向你说：“少侠，跟我来。”
你随老者绕过茅草屋向树林中走去，谈笑间，走到了一处流水潺潺的小溪边。老者招呼你在一块方石坐下，方石前是早已架好的柴堆。老者走向溪边，手中木棍挥舞间击起水花朵朵，几条河鱼就自水花中跃出落于地上。老者满意收棍，拾起河鱼手法熟练的处理好驾于火堆上。
诱人的香气飘出，待鱼肉焦黄，老者取下一条烤鱼给你，你迫不及待的咬了一口，鱼肉焦香，鲜美不已。老者又递予你一坛酒，你们开怀畅饮，不知时间流度。NOR]],["time"]=43,["title"]=[[MAG丐帮帮主NOR]]},["699"]={["id"]=699,["introText"]=[[WHT容貌极美，秀眉入鬓，清雅高华，难以言喻]],["itemId"]=[[mianju1044]],["name"]=[[落英掌门]],["need"]=4,["pic"]=[[Image/UI/AttrUI/mianju/linchaoying.png]],["thankText"]=[[YEL“惟有归于‘无缘’二字，却不知无缘系‘果’而非‘因’。”
你刚将手中的珍品券递上，便听身后传来一个苍老声音，回头看去，却不见其人。随之一旁的院门缓缓推开，落英掌门身着红裳，施施而行。
见你立于门前，落英掌门绝美容颜上显出一抹微笑：“不知少侠今日来此所为何事？今日我邀请王真人来府中商议要事，只怕要让少侠要等上片刻了。”
你与落英掌门相谈于院亭中，不多时门外跑来一个道童，道童将一封书信交予落英掌门后便匆匆离去。拆开书信，落英掌门的神色由失落渐渐转变为愤怒，直到看完书信中的内容，她的脸上尽显无奈。
道童送来书信被她攥握手中，看着园中飘落的秋叶，落英掌门竟有些木讷，口中呢喃：“好一个家国未定，何以为家。”NOR]],["time"]=43,["title"]=[[PNK古陵祖师NOR]]},["7"]={["id"]=7,["introText"]=[[一步一杀，七步七杀，七杀刀法以攻势凌厉，招数迅猛而闻名江湖。]],["itemId"]=[[qishadaofa1]],["name"]=[[    HIR七杀刀法NOR]],["need"]=16,["pic"]=[[Image/UI/StoreUI/shujuan2.png]],["thankText"]=[[YEL满月临弓影，连星入剑端。
