待到浓雾散去，你蓦然发现，手上的珍品券已经变成了一本泛黄的武学秘籍，令你错愕不已。NOR]],["time"]=44,["title"]=[[全篇]]},["711"]={["id"]=711,["introText"]=[[WHT她神色冷冽、目光如炬，发束金冠，金丝黑纱遮面，看起来让人不可靠近，似乎下一刻就会杀人于无形。NOR]],["itemId"]=[[mianju1085]],["name"]=[[HIB余夫人NOR]],["need"]=25,["pic"]=[[Image/UI/AttrUI/mianju/yufuren.png]],["thankText"]=[[YEL你走近一座气势恢宏的高楼，侍从接过你的珍品券，带你穿过幽深的长廊，每间客房的纸窗上皆映有人影，传出各种听不真切的窃窃声。而尽头的房门则从内打开，穿黑色绸衫的余夫人自屏风后走出，她容貌俏丽，只是眼神冰冷，笑起来也无丝毫暖意，“少侠来此有何事？”你想问她在无间林的往事，或者余志枭的死因，但你接触到她晦暗深沉的目光，只怕这些话问出口要惹来麻烦。

于是你默然无言，略坐片刻起身时，终还是问了一句：“那件事，你可有过后悔？”

她吃吃发笑，眼底有几分疯狂之色：“我用千年寒玉保住志枭尸身不腐，随时都能和我在一起，又有何悔？”

你摇头叹息，走出客房顿觉走廊左右每扇门后面像有贪婪的眼睛在窥视，令你毛骨悚然，不由大步离去。NOR]],["time"]=44,["title"]=[[BLU永夜夫人NOR]]},["712"]={["id"]=712,["introText"]=[[WHT她孤傲清冷，姿容绝代，着一身朱红色的骑士服，持剑而立，如同荆棘丛中的玫瑰，令人着迷又难以接近。NOR]],["itemId"]=[[mianju1093]],["name"]=[[YEL卡米尔NOR]],["need"]=15,["pic"]=[[Image/UI/AttrUI/mianju/kamierbaitian.png]],["thankText"]=[[YEL你将珍品券递上，片刻后，大门被人推开，走出一位身着朱红骑士服，步履轻快、清艳脱俗的异国女子。女子莞尔一笑，向你说了句：“少侠，久等。”

你随女子走进后院，发现后院是以玫瑰花丛作墙，院中立有一座白色石亭，此时正值花开之际，院里花香清幽。女子邀你到亭中入座，随后唤仆人端上花茶糕点。花茶清香甘甜，糕点入口即化，细腻甜津，难得尝此异国美食，你不禁多食了些。

女子与你饮茶赏花，畅谈天地。当谈及武学经历之时，你二人兴致所起，在院中比划起来。棋逢对手，将遇良才，你二人放开了手脚，酣畅淋漓的比试了一番。]],["time"]=44,["title"]=[[HIY月光蔷薇NOR]]},["713"]={["id"]=713,["introText"]=[[WHT浪荡洒脱，不修边幅，不似那些满带金银的富公子。样貌算不得英俊，但明眸清澈，笑意盎然。且既为侠盗，从不多取一毫，乃这盗中清官，两袖空空。NOR]],["itemId"]=[[mianju1097]],["name"]=[[HIW萧侠盗NOR]],["need"]=12,["pic"]=[[Image/UI/AttrUI/mianju/xiaoxiadao.png]],["thankText"]=[[YEL你将珍品券递上，忽感微风阵阵，林间枝叶簌簌，一道侠影由远及近，甚是潇洒。

走近身前，萧侠盗略带轻浮般的说道：“这位少侠，虽不知何由，但对你有着一种似曾相识的感觉，不知少侠可愿陪我在这翠林之中走走。”

你二人来到林中空地之上，一张青苔斑驳的石桌被落叶覆盖，露出灰白一角。

你二人对坐于此，夕阳西下。萧侠盗饮尽壶中最后一口烈酒，伴随着他清唱着的一首悲凉唱词，消失在茵茵竹林之中。你坐在石凳上，回忆着方才听来的有关一对侠侣逍遥江湖的故事。

林中唱词远去，微风轻抚，枝叶簌簌作响。石桌不远处，一把锈迹斑驳的铁剑插在地上，剑柄上，一条鲜艳的红色飘带随风舞动，好似故事中的女侠，曼舞于这软玉般的翠绿之间。NOR]],["time"]=44,["title"]=[[HIB狼心独怆NOR]]},["714"]={["id"]=714,["introText"]=[[WHT刚正不阿，一脸正气。须发皆白，身穿墨黑金缕长袍，手执马尾拂尘。正气凛然，眼神坚毅，让人不敢直视其目光。NOR]],["itemId"]=[[mianju1121]],["name"]=[[RED张天师NOR]],["need"]=5,["pic"]=[[Image/UI/AttrUI/mianju/zhangtianshi.png]],["thankText"]=[[YEL你将珍品券递上，片刻后自山门中走出一名小道童。小道童并未引你入山门，只为你指路往鹄鸣山中去。

你不知所往，只于山中闲步。见林木苍翠，既有巨树擎天，亦有枯木新芽。听鸟啼雀鸣，闻山涧泠泠，清耳悦心。所见皆如画，所闻皆似乐，悠然自得。

正于山中流憩，忽见一老者，须发皆白，鹤骨松姿，坐于山石上，好似山中仙人。你与老者以水代茶，赏景论道，直至暮色苍茫。]],["time"]=44,["title"]=[[MAG道宗天师NOR]]},["715"]={["id"]=715,["introText"]=[[WHT面目可怖，一对乌黑的牛角泛着冷光，一双铜铃般的大眼睛，眼神森寒不带一丝情绪，看所有人都像看将死之人一般NOR]],["itemId"]=[[mianju1069]],["name"]=[[HIR牛头NOR]],["need"]=5,["pic"]=[[Image/UI/AttrUI/mianju/niutou.png]],["thankText"]=[[YEL你将拜帖递上，随后酆都幽城城门打开，阴寒之气由内涌出让你不禁打了个冷颤。
     你提着白纸灯笼穿行于街道之间，忽然随着一阵锁链响动，你被撞倒在地。待你回过神来这才发现，面前一个长着牛头身着官服的家伙正满脸焦急的看着你，牛头将你扶到一旁的茶馆，浓茶入喉，刚才焦急不堪的牛头也逐渐缓下心来。
     牛头告诉你自己是忙于追捕逃出的恶鬼这才如此莽撞，而此事和自己那嗜酒如命的搭档有关。如今他喝酒误事，人又不见踪影，当下牛头也不知如何是好。
     听闻你便决定帮助此人捉拿恶鬼，牛头见你愿意帮忙脸上的愁容也少了几分。就在你起身要走出茶馆之时，身边的景物竟然突然开始模糊，随后你迷迷糊糊从桌上醒来，一旁还放着打翻美酒和一副牛头面具。NOR]],["time"]=44,["title"]=[[RED牛头马面NOR]]},["716"]={["id"]=716,["introText"]=[[WHT一条纯银项链，链坠是一白色象牙雕刻而成小白熊。白熊枕住手掌，侧卧酣眠，一副憨态可掬的模样。NOR]],["itemId"]=[[21xhlqeq2]],["name"]=[[白眠链]],["need"]=3,["pic"]=[[Image/UI/StoreUI/wuqi.png]],["thankText"]=[[YEL三尺龙泉剑，匣里无人见。
