待到浓雾散去，你蓦然发现，手上的珍品券已经变成了一本泛黄的武学秘籍，令你错愕不已。NOR]],["time"]=45,["title"]=[[全篇]]},["727"]={["id"]=727,["introText"]=[[HIW江湖上传闻她是峨眉叛徒，与柳玄风同为一伙。她一身青衫，容貌甚美，因幼时一段坎坷的经历，致使她变得冷漠寡言，唯独信任依赖于情人韩一枫。她行踪不定，其背后势力复杂难明，因她的存在，武林常起波澜]],["itemId"]=[[mianju1078]],["name"]=[[HIY狄水清NOR]],["need"]=25,["pic"]=[[Image/UI/AttrUI/mianju/dishuiqing.png]],["thankText"]=[[YEL你将珍品券递上，忽听见里面打斗叱喝之声，你正感疑惑时，一阵风夹裹着几张薄纸吹落至你脚边。

你粗略看见上面的“门派秘典”四字，狄水清已从竹林中走出，打斗声也随之停止，原来刚才是她在演练武功。

见你对这些纸张并无抢夺之意，她目光复杂，将薄纸拾起后，颔首请你进屋。

一番拜访结束，你回想起今日与她共处的时光，恍然发现她对你倒比从前话多了那么一点。]],["time"]=45,["title"]=[[MAG冰兰霜华NOR]]},["728"]={["id"]=728,["introText"]=[[HIW不怒自威，威风凛凛。眼神犀利，散发着一股浓重的杀气。体格精瘦，举手投足之间散发着一股宗师气质NOR]],["itemId"]=[[mianju1105]],["name"]=[[HIY唐不平NOR]],["need"]=15,["pic"]=[[Image/UI/AttrUI/mianju/tangbuping.png]],["thankText"]=[[YEL你将拜帖递上，随后便跟随唐门弟子进入山庄。随着唐门弟子引路，你二人穿行于山庄内，一路上你见到了不少奇珍异草和精妙机关。
     你随唐门弟子来到山庄内一处僻静的庄园，随后弟子告退。你轻敲门环，应声走出一位蕴含风情的女人，她对着你轻笑颔首，将你带入门中。
     庭院内，百花繁茂，竹林翠影。唐不平身穿青灰长衫，手中暗器寒芒利利。在他对面的年轻男子全神贯注看着唐不平的一招一式，而一旁的亭台内，一位如花似玉的妙龄少女拨弄琴弦，古琴声悠扬婉转，悠游自在。
     傍晚时分，唐不平将你送出山庄。夕阳之下，你二人踏步晚霞，可唐不平的脸上尽显惆怅。此刻无话，只因同为置身江湖的你明了此刻唐不平心中的怅惘。NOR]],["time"]=45,["title"]=[[HIC飒沓流星NOR]]},["729"]={["id"]=729,["introText"]=[[HIW他生得浓眉大眼，面如冠玉，头戴青巾。眉目之间给人一种值得信赖的感觉，天生散发着一股领袖气质。NOR]],["itemId"]=[[mianju1100]],["name"]=[[YEL张教主NOR]],["need"]=12,["pic"]=[[Image/UI/AttrUI/mianju/zhangjiaozhu.png]],["thankText"]=[[YEL你将珍品券递上，片刻后走出两位白袍男子，向你拱手道：“教主有请！”

两位白袍男子将你领至一悬崖边，便拱手告退。崖边有亭，亭中有人，一名青衣男子在向你招手，唤你过去。男子面如冠玉，目若朗星，卓越不凡，你刚于亭中坐好，男子便为你斟上一杯茶，笑道：“少侠来得正是时候，刚得一盒好茶。”

坐于亭中，上可触云天，下可览山河，斟上一杯清茶，你只觉心旷神怡。男子对武功见解独到，你们相谈甚欢，聊至兴起时还对上两招。NOR]],["time"]=45,["title"]=[[BLU似是而非NOR]]},["73"]={["id"]=73,["introText"]=[[WHT她就是神使清秋。她乌云秀发，杏脸桃腮，眉如春山浅淡，眼若秋波婉转；酥胸纤腰，盛臀修腿，胜似海棠醉日，梨花带雨。一轮明月映娇颜，两只蝴蝶轻似舞。假以时日，此身容便可祸国殃民。NOR]],["itemId"]=[[mianju1146]],["name"]=[[HIW神使清秋NOR]],["need"]=30,["pic"]=[[Image/UI/AttrUI/mianju/shengshiqingqiu.png]],["thankText"]=[[YEL你方将珍品券递上，便有一位娇俏可人的女子自门后小跑而出，她拉起你的手向一条小径走去，边走边笑道：“殿里有什么好玩的，我带你去一个好地方。”
女子带着你左拐右绕，忽然间一片花海闯入你的眼帘。这里是一处山谷，谷中花开漫野，你们一走进花海就惊起几只闪着幽幽蓝光的蝴蝶。蝴蝶翩跹起舞，女子也随它们一齐起舞。她着一身淡紫长裙，颇具异域风采，舞姿娥娜，美撼凡尘。若此处是仙境，那她应是仙女，回眸一笑胜星华。
你们于花海中席地而坐，观星赏月，谈天论地，说遍天下事，不知时间流转，直至重光教徒寻来将你们带回。NOR]],["time"]=9,["title"]=[[RED重光之女NOR]]},["730"]={["id"]=730,["introText"]=[[HIW他生得灵俊秀美，形神飘逸，手拿折扇，风流倜傥。NOR]],["itemId"]=[[mianju1045]],["name"]=[[HIC风流盗帅NOR]],["need"]=5,["pic"]=[[Image/UI/AttrUI/mianju/chuliuxiang.png]],["thankText"]=[[YEL你将珍品券递上，门前便走出一位手持折扇、英俊潇洒的公子，对你微微一笑，拉着你便往宅子内走去。
公子与你走到一座流水庭院，席地而坐，合起宝扇一抚掌，便有数位绫罗锦织的女子，手中捧着果盘款款走来，将数枚精致的果盘放到你们面前。你二人赏着这美景与蔬果，听着这流水与莺歌，不知不觉便有些乏了。
见你困乏，公子随手提来一盏香炉，将香炉置于身边，也无讲究，与你就地而眠。酣然入梦，一夜好眠，直至第二日天亮，你二人方才悠然而起。NOR]],["time"]=45,["title"]=[[CYN偷心盗帅NOR]]},["731"]={["id"]=731,["introText"]=[[HIW长发飘然，面无血色，阴森恐怖。NOR]],["itemId"]=[[mianju1038]],["name"]=[[BLU长发鬼NOR]],["need"]=3,["pic"]=[[Image/UI/AttrUI/mianju/changfagui.png]],["thankText"]=[[YEL你行至荒山，见天色阴沉，似有大雨将袭，你欲在山中寻一山洞避雨，四下张望只寻见一破败老宅。
老宅荒废多时，木门一开，灰尘便扑面而来。荒草遍地，蛛网尘封，纵使你心中不愿，但此时形势所困，你只得再此将就。
大雨倾盆而下，你守在火堆前正昏昏欲睡，忽闻雨声中有窃窃私语，你听了片刻，发觉私语声是自你身后传来。
你心中一紧，连忙回头望去，只见一人影蹲坐角落。
那人长发飘然，面无血色，见你望来便轻声笑起。
你恐极反怒，拾起火棍向他掷去，然那人却凭空消失。
你顿时毛骨悚然，顾不得大雨，慌忙离开，待逃至客栈你才发现有几张珍品卷丢在了老宅中。NOR]],["time"]=45,["title"]=[[GRN长发幽魂NOR]]},["732"]={["id"]=732,["introText"]=[[HIW链身以数个细长柳叶状银环相连紧扣而成，挂坠则以蓝宝石精琢成三燕环飞之态，并以金环相结合。飞燕下，由软玉精琢而成的迎春花生机盎然，三燕环飞，栩栩如生。NOR]],["itemId"]=[[22springnewzb1]],["name"]=[[暮春链]],["need"]=3,["pic"]=[[Image/UI/StoreUI/wuqi.png]],["thankText"]=[[YEL三尺龙泉剑，匣里无人见。
