待到浓雾散去，你蓦然发现，你的手上竟多了一件宝光四射的装备，而那张珍品券早已不知所踪。NOR]],["time"]=45,["title"]=[[HIW珍品装备NOR]]},["733"]={["id"]=733,["introText"]=[[HIW衣装多以黑色锦缎纺织而成，交领和袖口则用白色绸缎相接。裾处白色绸缎上以金丝银线织绘柳林飞燕之景，动之，枝叶摆动，燕群纷飞，似有呼之欲出之感。NOR]],["itemId"]=[[22springnewzb2]],["name"]=[[昼夜均]],["need"]=3,["pic"]=[[Image/UI/StoreUI/wuqi.png]],["thankText"]=[[YEL三尺龙泉剑，匣里无人见。
