待到浓雾散去，你蓦然发现，你的手上竟多了一件宝光四射的装备，而那张珍品券早已不知所踪。NOR]],["time"]=45,["title"]=[[HIW珍品装备NOR]]},["735"]={["id"]=735,["introText"]=[[HIW用天然蚕丝与上好绸缎共同纺织而成的长裤，但它并未因用料的轻薄而受寒暑之区，穿之，轻柔舒顺，冬暖夏凉，外加纺织之人手艺精妙，此物实乃是寒暑必备的佳品。NOR]],["itemId"]=[[22springnewzb4]],["name"]=[[寒暑平]],["need"]=3,["pic"]=[[Image/UI/StoreUI/wuqi.png]],["thankText"]=[[YEL三尺龙泉剑，匣里无人见。
