待到浓雾散去，你蓦然发现，手上的珍品券已经变成了一份残页，令你错愕不已。NOR]],["time"]=45,["title"]=[[残页]]},["74"]={["id"]=74,["introText"]=[[WHT她就是天竞门主。她生得婀娜多姿，盈盈妙目，顾盼间眼波流转。面上常带着花旦妆，更衬得人颜色艳丽，娇媚无双。NOR]],["itemId"]=[[mianju1111]],["name"]=[[YEL天竞门主NOR]],["need"]=25,["pic"]=[[Image/UI/AttrUI/mianju/tianjingmenzhu1.png]],["thankText"]=[[YEL你将珍品券递上，在戏楼门口热情地招呼着客人的小二立刻向你拱手道：“少侠，雅阁已为您备好，请随我来。”
你跟着小二走到二楼的一间雅阁，此间比大厅清净些，从楼台望去，能将戏台尽收眼底。你很快就被台上的戏吸引了去，连小二何时离开都不知。台上的旦角声音婉转动人，身形婀娜多姿，眉眼顾盼间便将你带入戏中人，一曲唱罢也久久不能回神。
几场戏后，小二再次前来带你走至戏院的后花园，园中有一青衣女子在小心擦拭着长琴。与戏台上的艳丽、娇媚相比，女子此时素雅、清冷了许多，就好似她们不是同一人。女子的声音依旧婉转动听，你们一起畅聊戏曲、音律，这一晚相谈甚欢。NOR]],["time"]=9,["title"]=[[GRN粉黛英姿NOR]]},["740"]={["id"]=740,["introText"]=[[HIW从春秋时期流传下来的刀法，在江湖上有多个分支流派，最著名的是萧氏和沈氏两大世家，据说他们得到了最完整的传承。NOR]],["itemId"]=[[geludaofa]],["name"]=[[问鼎刀法]],["need"]=20,["pic"]=[[Image/UI/StoreUI/shujuan1.png]],["thankText"]=[[YEL满月临弓影，连星入剑端。
不学燕丹客，徒歌易水寒。
你沉吟不语，将珍品券捧于手上，似在心中思索着什么。
须臾间，空中一股浓雾飘散而来，遮蔽了你的视线。
待到浓雾散去，你蓦然发现，手上的珍品券已经变成了一本泛黄的武学秘籍，令你错愕不已。NOR]],["time"]=46,["title"]=[[全篇]]},["741"]={["id"]=741,["introText"]=[[HIW相传，一世名将杨五郎得高僧智光大师点化，遂于五台山挂单出家。皈依之后，五郎长枪换作木棍，将一身名震沙场的杨家枪，演化为六十四点八卦棍，名曰“五郎八卦棍”。NOR]],["itemId"]=[[wulangbaguagunbox1]],["name"]=[[五郎八卦棍]],["need"]=15,["pic"]=[[Image/UI/StoreUI/shujuan2.png]],["thankText"]=[[YEL满月临弓影，连星入剑端。
不学燕丹客，徒歌易水寒。
你沉吟不语，将珍品券捧于手上，似在心中思索着什么。
须臾间，空中一股浓雾飘散而来，遮蔽了你的视线。
待到浓雾散去，你蓦然发现，手上的珍品券已经变成了一本泛黄的武学秘籍，令你错愕不已。NOR]],["time"]=46,["title"]=[[全篇]]},["742"]={["id"]=742,["introText"]=[[HIW桃腮杏脸、国色天香，既有少女的娇憨，又有几分妇人的媚态，不知世间多少俗人为之神魂颠倒、求而不得。NOR]],["itemId"]=[[mianju1077]],["name"]=[[HIY招财童子NOR]],["need"]=25,["pic"]=[[Image/UI/AttrUI/mianju/caishen.png]],["thankText"]=[[YEL珍品券刚送入不久，两只金蟾跳到你面前，其中一只口吐人言道：“少侠请进，我们主人在大厅等你，呱呱。”
你跟着金蟾走进一间金屋，招财童子正趴在玉桌上打盹，被金蟾唤醒后连忙邀你入座。
她斟上两盏热茶，满含期待地问：“最近这里太无聊了，外面可有发生什么有趣的事？”
你便与她说起自己在江湖上的所见所闻，她听得时不时拍手大笑，一夜尽兴闲谈，直到天亮你方离开。NOR]],["time"]=46,["title"]=[[MAG财运到NOR]]},["743"]={["id"]=743,["introText"]=[[HIW身形瘦长，发鬓须髯皆白，脸上双颊凹陷，神色肃穆，目光中透着一股让人不敢与之对视的锋芒。NOR]],["itemId"]=[[mianju1113]],["name"]=[[HIW欧冶子NOR]],["need"]=15,["pic"]=[[Image/UI/AttrUI/mianju/ouyezi.png]],["thankText"]=[[YEL你持珍品券上门，叩门许久却未有人应答，犹豫片刻你便推门而入。
屋内无人，一旁的炼器房传来了清脆的锻铁声，于是你提着好酒好菜走进了炼器房。
炼器房内温暖如春，欧冶子聚精会神地锻打着手中长剑，对你的不予理会。
你习以为常，也未出声打扰，在桌上摆好酒菜后静坐等候。
锻剑声清脆悠扬，竟也似乐声悦耳，随着最后一步淬火完成，一把宝剑就此出世。这时你才起身上前，迎欧冶子入座。
但欧冶子入座后却未着急饮酒，先是考校了你的锻造之法，待你将问题一一回上，方才举杯畅饮，直至天明。NOR]],["time"]=46,["title"]=[[BLU剑池遗风NOR]]},["744"]={["id"]=744,["introText"]=[[HIW眉清目秀，丰神如玉。白日里温雅谦逊，淡然沉静，抱剑而立只道是个文弱的美少年。而不知何故，一到夜里竟满身疮痍，面目疯狂而绝望，叫人望而生畏。NOR]],["itemId"]=[[mianju1154]],["name"]=[[HIC林少侠NOR]],["need"]=15,["pic"]=[[Image/UI/AttrUI/mianju/linshaoxia1.png]],["thankText"]=[[YEL西湖湖畔，你寻觅许久，终于是见到了他。

与往常的丰神如玉不同，此时，他双眼处蒙着红纱，浑身血污，右手死死攥着宝剑，不时向四周挥舞着，显得有些癫狂。

你向他表明来由，并将珍宝券远远地丢在他的跟前，一番警惕地摸索过后，他似乎对你暂时打消了敌意。

他与你谈起这些年来的经历，从救人被灭门，到拜师被骗秘籍，从练功报仇，到最终双目被毁。你听了他的故事，心中既怜又恨，但却不知道该如何开口，最终也只是选择了微微一叹。

临别之际，你还是问出了心中的疑惑，“你对得起岳小妹吗？”

他如遭雷击，却始终缄默。

你摇了摇头，转身便走，不再留恋。NOR]],["time"]=46,["title"]=[[BLU夜里悲狂NOR]]},["745"]={["id"]=745,["introText"]=[[HIW剑眉入鬓，凤眼生威，清癯俊秀，英气逼人。NOR]],["itemId"]=[[mianju1012]],["name"]=[[BLU杨大侠NOR]],["need"]=6,["pic"]=[[Image/UI/AttrUI/mianju/yangguo.png]],["thankText"]=[[YEL你闲来无事，听闻今晚街上有庙会便前往闲逛。
华灯初上，月色晴朗，街上人影绰绰，热闹非凡。你看了会祭神歌舞，又看了看街边卖艺，再去茶馆喝杯茶，最后逛到了河边。
河中水灯如流萤，在月色映衬下又似明星，此番景色如诗如画，而你在这画遇到了一位故人。
他剑眉入鬓，英气逼人，却不复当年意气。事过景迁，你们再次相遇，心中感慨颇多，然话至嘴边却又觉无可说。去换得几壶美酒，你们今夜一醉方休。NOR]],["time"]=46,["title"]=[[GRN独臂大侠NOR]]},["746"]={["id"]=746,["introText"]=[[HIW此衣通体黑色，袖口、领口处以红绸为底，用金丝绣有十二种形态各异的猛虎，山君之态微风凛然，显有王者风范。NOR]],["itemId"]=[[22tigerypao]],["name"]=[[山君袍]],["need"]=3,["pic"]=[[Image/UI/StoreUI/wuqi.png]],["thankText"]=[[YEL三尺龙泉剑，匣里无人见。
