你与女弟子走到一处山崖边，一位秀丽绝俗，身姿丰盈的女子正在此习武。虽只是基础的招式，但女子不曾有丝毫怠慢，整个人沉稳、坚毅，还带有一丝勇往无前的锐利。你与她一起讨论武学，期间还比试了一番，待日暮时分正准备告辞离开时，女子忽然开口道：“山下镇子的夜市热闹得很，不如一起去逛逛？”
夜市灯火通明，人影攒动，果真热闹非凡。女子换了一套蓝色的衣裙，头戴狐狸面具，手拿一根糖葫芦穿行在摊贩间。双眸清亮如星，樱桃小口未曾停下过，似黄鹂一般，清纯活泼，叫人心生喜爱。NOR]],["time"]=9,["title"]=[[PNK江湖三友NOR]]},["750"]={["id"]=750,["introText"]=[[HIW这是一部系统论述兵器制作的鸿篇巨著，作者闻人氏据说是朝廷军器监的大匠师。（此书博大精深，研读需要拥有一定锻造之术基础。）NOR]],["itemId"]=[[yeshushuji39]],["name"]=[[玄兵稗志]],["need"]=3,["pic"]=[[Image/UI/StoreUI/shuji.png]],["thankText"]=[[YEL白发无情侵老境，青灯有味似儿时。
