你难得无事，在茶馆闲坐，见此喜闹之景也不由得心觉欢悦。
忽然你心血来潮，用珍品券与一孩童换了两挂爆竹，为新春添了些人间烟火.
待你三更酣眠时，一只凶兽入梦，只见它头生尖角、牙尖嘴利，庞大的身躯自云间穿出。
忽然城中四处响起爆竹声声，凶兽惧不敢入，无奈退回云间离去，你也自酣梦苏醒。NOR]],["time"]=47,["title"]=[[BLU爆竹熄祟NOR]]},["757"]={["id"]=757,["introText"]=[[WHT幽冥教的无尘公子。
他是幽冥教教主的嫡传弟子，生性多疑，倨傲不已，天下间能让他甘愿结交之人少之又少。
他颜如舜华，宛若女子一般，不少江湖高手初见他时只笑他是阴柔之辈，直至剑出血横，方明白他的厉害。NOR]],["itemId"]=[[mianju1084]],["name"]=[[GRN叶妄生NOR]],["need"]=15,["pic"]=[[Image/UI/AttrUI/mianju/yewangsheng.png]],["thankText"]=[[YEL珍品券送入不久后，忽听得一声惨叫，你正欲抬脚入门一探究竟之时，一个人影从层层黑纱帐中走了出来。
叶妄生本就生得阴柔，着一袭暗红玄色敞袍与他所持匕首上沾染的血色正好相衬。
他朝你看了一眼，微闭双目，冷笑一声：“我当是谁......既然来了，请。”
事后，你浑然记不起黑纱帐中的情景，只依稀觉得今日的叶妄生并非如江湖传闻所说的那般冷绝。NOR]],["time"]=47,["title"]=[[PNK三途来客NOR]]},["758"]={["id"]=758,["introText"]=[[WHT风姿绰约，仪态万方，头束金冠，身披玄甲，本为一朝公主，长枪在手却不让须眉，当真称得上英姿飒爽，绝代风华，有诗云：一别深宫罢红妆，风飞扬，耀荣光。NOR]],["itemId"]=[[mianju1092]],["name"]=[[HIM戎装公主NOR]],["need"]=15,["pic"]=[[Image/UI/AttrUI/mianju/rongzhuanggongzhu.png]],["thankText"]=[[YEL月上梢头，习武场上却仍有一道身影在执着地练习着枪法。

红缨抖动，枪影如龙。你仔细观察了盏茶的时间，发现那人的身形瘦削，脚步虚浮，而且招式衔接略显生疏，显然那人并非勤习武艺也非久经沙场之人。

正在你疑惑之际，场上那人似乎也发现了你的踪迹。

“你还打算看上多久？”声若黄莺，场上之人竟然是个女子。

你走上跟前，递上拜帖，女子接过时，顺手将遮面面具揭下。眉目如画，却有雍容气度，你忽而想起坊间所传的公主入伍一事。

“女子就不可以上战场吗？”她似乎猜出了你心中所想，也不待你回答，便一枪向你刺来。只是枪速稍缓，明显给了你反应的时间。你心下明悟，当下运起兵器，与她斗作一团。NOR]],["time"]=47,["title"]=[[MAG戎装公主NOR]]},["759"]={["id"]=759,["introText"]=[[WHT她生得清雅绝俗，秀丽无比，已不再是凡间人物。NOR]],["itemId"]=[[mianju1013]],["name"]=[[YEL龙姑娘NOR]],["need"]=6,["pic"]=[[Image/UI/AttrUI/mianju/xiaolongnv.png]],["thankText"]=[[YEL你将珍品券递上，许久后，沉重的石门缓缓下降，露出石门后的墓穴和一位白衣飘然的女子。女子清雅绝俗，不似凡间人物，她虽还是面若秋霜，但比之曾经要柔和些，她淡淡地道：“许久不见。”

你随女子进到墓穴中，墓穴内依旧是别有洞天，似一方世外桃源般，未曾有何改变。待你坐下，女子道了句“稍等。”后翩然离去，片刻后，女子捧了个石碗走来，与她同来的还有一个英气逼人的男子，男子只有独臂，手上端着一个石盘，石盘中盛着些果子。

石碗中便是蜂王玉露，胜似琼浆玉露，分外甘甜。石盘中是你叫不出名字的果子，入口细腻，清润甘美。墓穴虽清冷，别无乐处，但你们三人畅聊一番武学经历，倒也是其乐融融。NOR]],["time"]=47,["title"]=[[ORA古墓掌门NOR]]},["76"]={["id"]=76,["introText"]=[[WHT他就是风流家丁。他生得英俊白净，虽然一幅下人打扮，却有一种贵公子的神采风度，让人忍不住为其着迷。NOR]],["itemId"]=[[mianju1089]],["name"]=[[WHT风流家丁NOR]],["need"]=10,["pic"]=[[Image/UI/AttrUI/mianju/jiading1.png]],["thankText"]=[[YEL你将珍品券递上，片刻后出来一名下人装扮的男子，他对你潇洒一笑，道：“小姐今日不在，让我来带你随便逛逛。”
你随男子走到一处花园中，园中各种鲜花争奇斗艳，假山林立，一步一景。男子与你边走边聊，他虽是下人打扮但却贵气十足，谈吐高雅，举手投足间也是风度翩翩。他拾起一朵掉落的娇花，出口便成章，感叹着落花之意。男子本就俊逸潇洒，手中的娇花让他更显风流倜傥。
你们走至另一园中，此园里摆有画桌，其上置有纸张笔墨，男子随手几笔百花的之景就初具其形。男子画得投入，你不忍惊扰只在旁静观，不一会一副百花争艳图便已完成。男子将此图赠予你，你欣然收下，又闲聊了两句后便告辞离开。NOR]],["time"]=9,["title"]=[[HIY风流家丁NOR]]},["760"]={["id"]=760,["introText"]=[[HIW鞋底边雕有水纹龙舟，鞋身绣有飞龙腾云纹样，飞龙由水纹盘旋而上直冲天际，喻有吉祥飞腾之意。NOR]],["itemId"]=[[22dwnewweapon1]],["name"]=[[HIB地腊NOR]],["need"]=3,["pic"]=[[Image/UI/StoreUI/wuqi.png]],["thankText"]=[[YEL你将珍品券递上，门前便走出一位手持折扇、英俊潇洒的公子，对你微微一笑，拉着你便往宅子内走去。
公子与你走到一座流水庭院，席地而坐，合起宝扇一抚掌，便有数位绫罗锦织的女子，手中捧着果盘款款走来，将数枚精致的果盘放到你们面前。你二人赏着这美景与蔬果，听着这流水与莺歌，不知不觉便有些乏了。
见你困乏，公子随手提来一盏香炉，将香炉置于身边，也无讲究，与你就地而眠。酣然入梦，一夜好眠，直至第二日天亮，你二人方才悠然而起。NOR]],["time"]=47,["title"]=[[HIW珍品装备NOR]]},["761"]={["id"]=761,["introText"]=[[HIW戒身以一块完整的翠玉精制而成，上雕飞龙踏舟，逐浪而行。龙颜不怒自威，舟行水溅好似身临其境，恍惚间耳畔似有阵阵龙吟，可见雕刻之人实乃鬼斧神工。NOR]],["itemId"]=[[22dwnewweapon2]],["name"]=[[HIG龙纹舟戒NOR]],["need"]=3,["pic"]=[[Image/UI/StoreUI/wuqi.png]],["thankText"]=[[YEL你行至荒山，见天色阴沉，似有大雨将袭，你欲在山中寻一山洞避雨，四下张望只寻见一破败老宅。
老宅荒废多时，木门一开，灰尘便扑面而来。荒草遍地，蛛网尘封，纵使你心中不愿，但此时形势所困，你只得再此将就。
大雨倾盆而下，你守在火堆前正昏昏欲睡，忽闻雨声中有窃窃私语，你听了片刻，发觉私语声是自你身后传来。
你心中一紧，连忙回头望去，只见一人影蹲坐角落。
那人长发飘然，面无血色，见你望来便轻声笑起。
你恐极反怒，拾起火棍向他掷去，然那人却凭空消失。
你顿时毛骨悚然，顾不得大雨，慌忙离开，待逃至客栈你才发现有几张珍品卷丢在了老宅中。NOR]],["time"]=47,["title"]=[[HIW珍品装备NOR]]},["762"]={["id"]=762,["introText"]=[[HIW由五根颜色不同的丝绳编织而成，其中坠有翠色香囊。相传五色丝绳象征着东、西、南、北、中五个方位，蕴涵着五方神力，可以驱邪除魔，祛病强身，使人健康长寿。NOR]],["itemId"]=[[22dwnewweapon3]],["name"]=[[HIG长命缕NOR]],["need"]=3,["pic"]=[[Image/UI/StoreUI/wuqi.png]],["thankText"]=[[YEL三尺龙泉剑，匣里无人见。
一张落雁弓，百支金花箭。
你沉吟不语，将珍品券捧于手上，似在心中思索着什么。
须臾间，空中一股浓雾飘散而来，遮蔽了你的视线。
待到浓雾散去，你蓦然发现，你的手上竟多了一件宝光四射的装备，而那张珍品券早已不知所踪。NOR]],["time"]=47,["title"]=[[HIW珍品装备NOR]]},["763"]={["id"]=763,["introText"]=[[HIW此带用上好的丝绸制成，带面以金丝绣有菖蒲纹样，姿态各异，活灵活现。NOR]],["itemId"]=[[22dwnewweapon4]],["name"]=[[HIY菖蒲带NOR]],["need"]=3,["pic"]=[[Image/UI/StoreUI/wuqi.png]],["thankText"]=[[YEL三尺龙泉剑，匣里无人见。
