待到浓雾散去，你蓦然发现，你的手上竟多了一件宝光四射的装备，而那张珍品券早已不知所踪。NOR]],["time"]=47,["title"]=[[HIW珍品装备NOR]]},["764"]={["id"]=764,["introText"]=[[HIW由沈括所著，是一部涉及多门学科的综合性笔记体著作，刊行天下后，影响深远，享誉海内外。NOR]],["itemId"]=[[yeshushuji69]],["name"]=[[梦溪笔谈]],["need"]=3,["pic"]=[[Image/UI/StoreUI/shuji.png]],["thankText"]=[[YEL白发无情侵老境，青灯有味似儿时。
