待到浓雾散去，你蓦然发现，手上的珍品券已经变成了一本书籍，令你错愕不已。NOR]],["time"]=47,["title"]=[[HIW书籍NOR]]},["765"]={["id"]=765,["introText"]=[[HIW此书是王掌门的诗词集，内容多为题咏、述怀感事、赠答应酬之作，以诗词言志并宣传道教思想。NOR]],["itemId"]=[[yeshushuji55]],["name"]=[[重阳全真集]],["need"]=3,["pic"]=[[Image/UI/StoreUI/shuji.png]],["thankText"]=[[YEL白发无情侵老境，青灯有味似儿时。
