待到浓雾散去，你蓦然发现，手上的珍品券已经变成了一本书籍，令你错愕不已。NOR]],["time"]=47,["title"]=[[HIW书籍NOR]]},["766"]={["id"]=766,["introText"]=[[WHT是一部记载春秋时期晏婴言行的历史典籍，经刘向整理，共内、外八篇，二百一十五章。NOR]],["itemId"]=[[tiangongshi1]],["name"]=[[天工石]],["need"]=2,["pic"]=[[Image/UI/StoreUI/zhuzi.png]],["thankText"]=[[YEL赤点朱饰韵味飘远,真才天工赏心悦目。
一坐立感气宇轩昂,轻拭再叹鬼斧天工。
你沉吟不语，将珍品券捧于手上，似在心中思索着什么。
