待到浓雾散去，你蓦然发现，手上的珍品券已经变成了一本泛黄的武学秘籍，令你错愕不已。NOR]],["time"]=48,["title"]=[[全篇]]},["769"]={["id"]=769,["introText"]=[[HIW据称是一蓬莱高手所创的独门轻功，不注重飞檐走壁，而是注重交手之际的极速腾挪。施展之时，来去如风，极为飘逸。NOR]],["itemId"]=[[feiyingshisanshi]],["name"]=[[飞影十三逝]],["need"]=12,["pic"]=[[Image/UI/StoreUI/shujuan2.png]],["thankText"]=[[YEL满月临弓影，连星入剑端。
