待到浓雾散去，你蓦然发现，手上的珍品券已经变成了一本泛黄的武学秘籍，令你错愕不已。NOR]],["time"]=48,["title"]=[[全篇]]},["77"]={["id"]=77,["introText"]=[[WHT他就是杨公子。他生得脸如冠玉，唇若涂丹，容貌俊美。NOR]],["itemId"]=[[mianju1005]],["name"]=[[RED杨公子NOR]],["need"]=5,["pic"]=[[Image/UI/AttrUI/mianju/yangkang.png]],["thankText"]=[[YEL你递上珍品券，朱门后面走出一位仆人恭敬道：“少侠里面请，我们小王爷正在花厅会客。”
你随他进入王府，踏过玉石阶，又一路穿回廊，绕画楼，但见雕梁绣栋，一派豪华。到了花厅，厅内已有五六人相候，皆对着上首那位头戴束发金冠，身穿锦绣衣袍的俊美少年恭维至至，那少年只饮茶不语，见到你却是连忙起身相迎。
“久闻少侠大名，今日一见果真名不虚传。”他引你上座，将在座各位一一与你介绍，其中就有三头蛟候通海、长白山梁子翁等人。知你武功不俗，他接连向你讨教，追问有无捷径之法，你摇头否定，他虽失望但对你热情不减，天色稍晚，你提出告辞，他竟一路相送，约你日后常来。NOR]],["time"]=9,["title"]=[[YEL金国世子NOR]]},["770"]={["id"]=770,["introText"]=[[WHT他就是胡大侠。面似寒霜，冷傲逼人。一对墨眉有如柳叶般纤细，一双眼眸好似狐狸般狭长，他手握单刀，冰冷的眼神散发出似有若无的杀意，令人胆寒。NOR]],["itemId"]=[[mianju1127]],["name"]=[[HIB胡大侠NOR]],["need"]=25,["pic"]=[[Image/UI/AttrUI/mianju/hufei.png]],["thankText"]=[[YEL寒冬腊月，飞雪纷纷，你根据百晓生的指引独自北上，前往长白山深处去寻找那道侠影。

雪地中，男子舞着手中的长刀，他身形腾挪，刀影翻飞，灵动迅捷，犹如雪狐般机敏。舞至精彩处，你忍不住叫了声“好”，他循声向你望来，或许是你手中的珍宝券，让他冷峻的神色稍稍缓和。只见他身影几下闪动便到了你跟前，他手中黑刀径直向你横削而来，只是出刀的速度比上先前却是慢了几分，你心下了然，拔出长剑向他攻去。

拆招五百余合，不分胜负，你们哈哈一笑罢手停战，拿出酒壶痛饮一番。你醉倒之前，依稀还记得他轻唱的歌谣，“来日大难，口燥舌干。今日相乐，皆当喜欢。”NOR]],["time"]=48,["title"]=[[MAG雪山侠行NOR]]},["771"]={["id"]=771,["introText"]=[[WHT她孤傲清冷，姿容绝代，着一身朱红色的骑士服，持剑而立，如同荆棘丛中的玫瑰，令人着迷又难以接近。NOR]],["itemId"]=[[mianju1093]],["name"]=[[YEL卡米尔NOR]],["need"]=15,["pic"]=[[Image/UI/AttrUI/mianju/kamierbaitian.png]],["thankText"]=[[YEL你将珍品券递上，片刻后，大门被人推开，走出一位身着朱红骑士服，步履轻快、清艳脱俗的异国女子。女子莞尔一笑，向你说了句：“少侠，久等。”

你随女子走进后院，发现后院是以玫瑰花丛作墙，院中立有一座白色石亭，此时正值花开之际，院里花香清幽。女子邀你到亭中入座，随后唤仆人端上花茶糕点。花茶清香甘甜，糕点入口即化，细腻甜津，难得尝此异国美食，你不禁多食了些。

女子与你饮茶赏花，畅谈天地。当谈及武学经历之时，你二人兴致所起，在院中比划起来。棋逢对手，将遇良才，你二人放开了手脚，酣畅淋漓的比试了一番。]],["time"]=48,["title"]=[[HIY月光蔷薇NOR]]},["772"]={["id"]=772,["introText"]=[[WHT他生得娇艳，身穿一身枣红色缎面长袍，眼波流转之间，神态竟要比女子还要妩媚三分。]],["itemId"]=[[mianju1098]],["name"]=[[HIR杨总管NOR]],["need"]=15,["pic"]=[[Image/UI/AttrUI/mianju/yangzongguan.png]],["thankText"]=[[YEL你将珍品券递上，片刻后走出两位长袖青衫，黑纱蒙面的男子，向你拱手道：“总管有请！”

你随两位蒙面男子进入殿内，只见殿内早已备好宴席。一个身着枣红色缎面长袍，身形妖娆的男子坐于桌前。男子起身邀你入座，轻轻一挥手，道了句：“上酒吧。”两位蒙面男子毕恭毕敬的端上好酒，为你们斟上。

你与男子推杯交盏间，相谈甚欢。惊风飘白日，光景西驰流，眼看日头西沉，你也只得告辞离去。]],["time"]=48,["title"]=[[YEL天人化生NOR]]},["773"]={["id"]=773,["introText"]=[[HIW剑眉星目，玉冠锦袍，眼中充满着凶煞之气，一副俯视苍生的姿态，让人倍感压力NOR]],["itemId"]=[[mianju1032]],["name"]=[[HIY柳玄风NOR]],["need"]=6,["pic"]=[[Image/UI/AttrUI/mianju/liuxuanfeng.png]],["thankText"]=[[YEL你将珍品券递上，片刻后一旁的戏楼锣鼓声起，一位身穿华贵侠袍面戴鬼怪面具的优伶由后台走出，口中戏腔尖细悠扬，让人沉醉其中。
“少侠可知这曲中所唱之人是谁？”
你沉醉于戏曲之中，突然被身后一声问话惊醒。寻声望去，面前之人竟身穿与台上优伶相同的衣着，面具之下剑眉星目。
你随柳玄风落座于戏楼二层，见你对此戏兴趣浓厚，柳玄风则按照戏文给你讲述了一段戏中似有似无的故事。戏曲悠扬，戏文跌宕，在柳玄风的讲述下，你逐渐沉浸其中，仿佛你便是那戏文中的孤侠，只身对抗武林。
许久，鸡鸣响起，眼前的戏楼、优伶乃至柳玄风渐渐化为乌有。
看着东方的初阳，你的内心依然沉浸在那一段跌宕澎湃的故事中，久久不能平复。
NOR]],["time"]=48,["title"]=[[YEL命运多舛NOR]]},["774"]={["id"]=774,["introText"]=[[HIW白色绸缎制成的长袍，缎面绣有祥云暗纹，领、襟、袖中别有五色线，素而不简，简而不凡。NOR]],["itemId"]=[[22dwnewweapon5]],["name"]=[[HIW五色线袍NOR]],["need"]=3,["pic"]=[[Image/UI/StoreUI/wuqi.png]],["thankText"]=[[YEL三尺龙泉剑，匣里无人见。
