待到浓雾散去，你蓦然发现，手上的珍品券已经变成了一份残页，令你错愕不已。NOR]],["time"]=48,["title"]=[[残页]]},["782"]={["id"]=782,["introText"]=[[HIW据说为一双手残废的世外高人所创。那高手不得习掌，遂精研腿法，终成大器。此路腿法以刚猛为主，使用时需以极强内力为辅。NOR]],["itemId"]=[[jiutianxianglongtui]],["name"]=[[九天翔龙腿]],["need"]=16,["pic"]=[[Image/UI/StoreUI/shujuan2.png]],["thankText"]=[[YEL满月临弓影，连星入剑端。
