待到浓雾散去，你蓦然发现，手上的珍品券已经变成了一本泛黄的武学秘籍，令你错愕不已。NOR]],["time"]=49,["title"]=[[全篇]]},["784"]={["id"]=784,["introText"]=[[HIW他就是幻花剑客。眉目疏朗，俊逸非凡。他抱剑立于花树下沉思，似在透过手中的吊坠望见故人，少了些萧杀，多了分落花的忧愁，左肩上绽放的将离让他更添一丝风流。NOR]],["itemId"]=[[mianju1144]],["name"]=[[MAG幻花剑客NOR]],["need"]=23,["pic"]=[[Image/UI/AttrUI/mianju/huanhuajianke.png]],["thankText"]=[[YEL樱花树下，他端详着手中的吊坠，似乎在思念着故人。也许是听到你的脚步声，他猛然回头，手默默的按住刀柄，神情由怀念转为肃杀。你连忙递上手中的珍宝券，见此他的神色才稍微缓和，只是始终一语不发。

也许是环境使然，你也没有开口询问的欲望，你与他便这么静默对视了半盏茶时间。他对着你默默地点了点头，随后从树下土地中挖出两坛酒，将其中一坛丢给了你，然后自顾自的喝了起来。喝罢，便独自离开。

忽而大风吹过，樱花散落，风中传来一阵异乡的歌谣，浪漫却又忧伤，跟他给你的酒一般滋味。NOR]],["time"]=49,["title"]=[[HIW花影随行NOR]]},["785"]={["id"]=785,["introText"]=[[HIW整整截截，偢然不乐。一袭袈裟尽显庄重，他总是紧闭双目，高深莫测，没人知道他在思考什么，而在其他弟子眼中，他不怒自威，让人生畏。NOR]],["itemId"]=[[mianju1188]],["name"]=[[BLU真荣NOR]],["need"]=15,["pic"]=[[Image/UI/AttrUI/mianju/zhenrongbai.png]],["thankText"]=[[YEL你将珍品券递给沙弥，沙弥向你合掌道：“施主请随我来。”

你随沙弥来到荷塘中间的凉亭，真荣早已沏好茶在此等候。

还未等你开口，真荣似乎已经知晓你要问什么，率先开口道：“铁掌、海鲸一事各执一词，是非曲直明日自当分晓，如今还是不便多说。”

真荣这般说，你也没有继续追问，只饮茶闲聊，待天色擦黑，你便告辞离去了。NOR]],["time"]=49,["title"]=[[ORA就虚避实NOR]]},["786"]={["id"]=786,["introText"]=[[HIW玉骨冰肌，顾盼媚流，一袭鲜红舞衣，凤鸾飞绣，玉珠垂髻，只衬得她面若桃花，于烛曳摇光间尽显风姿灼华。世闻，纵盈光皎月，仙宫美娥，亦不足她倾城一笑。NOR]],["itemId"]=[[mianju1115]],["name"]=[[HIR貂蝉NOR]],["need"]=12,["pic"]=[[Image/UI/AttrUI/mianju/diaochan.png]],["thankText"]=[[YEL你将拜帖递进一座江南宅院的正门，随即被一位垂髫女童引进院内凉亭，见花摇树影间的石桌旁坐着一素手调琴的美人，生得肌白赛雪，一袭红衫似红梅映月，果然是倾城绝色。
传闻当年貂蝉受主家王允所托，为护汉室江山以身作饵周旋于董卓与吕布之间，后来奸臣董卓被灭，吕布亦成三家姓奴令天下人耻笑，不得善终，而貂蝉从此消失，没想到竟是在这隐居。
她许久不接待生人，与你相见时脸颊飞红一片，以袖掩面，露出的美目波光流转。
看着这样一双妩媚动人的眼睛，无论男女皆会受之蛊惑。只听她声音婉转如莺啼，笑言：“若不嫌弃，貂蝉有一曲献给少侠。”
说罢，她双指在琴弦上翩飞，世闻其舞月见羞，原来美人弹琴也如仙宫之乐，令你痴醉不已。NOR]],["time"]=49,["title"]=[[RED月见羞NOR]]},["787"]={["id"]=787,["introText"]=[[HIW一条精美的腰带。腰带由一枚枚银环前后相扣组成，腰带中间的银环外翻，形成一个银丝托，托上嵌有一颗硕大的碧玺，彰显腰带之珍贵。NOR]],["itemId"]=[[2021sanyueyunyingeq1]],["name"]=[[碧玺带扣]],["need"]=3,["pic"]=[[Image/UI/StoreUI/wuqi.png]],["thankText"]=[[YEL三尺龙泉剑，匣里无人见。
