一众弟子将你带到大殿内，左右手站成两排，躬身齐唱：“名宿毒仙，法驾中原，神通广大，法力无边！”你见上首坐着位灰发老者，气度非凡，似是神仙人物。老者坐定，大手一挥，两旁弟子立即噤若寒蝉。老者笑声洪浑，对你笑道：“哈哈哈！少侠特来拜访，老夫为你备了碗仙汤，包你喝了长生不老，日月同辉！”
你端过汤来，汤汁黑稠，腥臭无比。你硬着头皮，在众人的注视下一饮而尽，随后一股寒热从你腹部直上头皮，令你昏厥了过去……NOR]],["time"]=50,["title"]=[[HIM名宿毒仙NOR]]},["799"]={["id"]=799,["introText"]=[[HIW她孤傲清冷，姿容绝代，着一身朱红色的骑士服，持剑而立，如同荆棘丛中的玫瑰，令人着迷又难以接近。NOR]],["itemId"]=[[mianju1093]],["name"]=[[YEL卡米尔NOR]],["need"]=15,["pic"]=[[Image/UI/AttrUI/mianju/kamierbaitian.png]],["thankText"]=[[YEL你将珍品券递上，片刻后，大门被人推开，走出一位身着朱红骑士服，步履轻快、清艳脱俗的异国女子。女子莞尔一笑，向你说了句：“少侠，久等。”

你随女子走进后院，发现后院是以玫瑰花丛作墙，院中立有一座白色石亭，此时正值花开之际，院里花香清幽。女子邀你到亭中入座，随后唤仆人端上花茶糕点。花茶清香甘甜，糕点入口即化，细腻甜津，难得尝此异国美食，你不禁多食了些。

女子与你饮茶赏花，畅谈天地。当谈及武学经历之时，你二人兴致所起，在院中比划起来。棋逢对手，将遇良才，你二人放开了手脚，酣畅淋漓的比试了一番。]],["time"]=50,["title"]=[[HIY月光蔷薇NOR]]},["8"]={["id"]=8,["introText"]=[[相传，一世名将杨五郎得高僧智光大师点化，遂于五台山挂单出家。皈依之后，五郎长枪换作木棍，将一身名震沙场的杨家枪，演化为六十四点八卦棍，名曰“五郎八卦棍”。]],["itemId"]=[[wulangbaguagunbox1]],["name"]=[[    HIB五郎八卦棍NOR]],["need"]=15,["pic"]=[[Image/UI/StoreUI/shujuan6.png]],["thankText"]=[[YEL满月临弓影，连星入剑端。
