你跟着峨眉弟子走入山门，转转绕绕来到了后山上。一眼便瞧见一蓝衣女子于古松下习剑，一招一式皆清爽凌厉。见你来到，女子收剑入鞘，邀你至一旁的亭子入座。
女子不过花信年华，眉眼间却以带有几分宝相神尼的威仪，让你不由得心生敬佩。你们品茶论道，直至山间染上红光才知时光流逝。见此时已是日落时分，你便告辞离去。NOR]],["time"]=50,["title"]=[[HIC江湖三友（四）NOR]]},["801"]={["id"]=801,["introText"]=[[HIW这是一条皇华长裤。长裤由珍贵无比的绫罗绸缎制成，上面缀有无数的华贵珠宝，彩光流转，珠光宝气。将这条长裤穿上，能彰显出自己高贵的身份。NOR]],["itemId"]=[[2021xclqeq1]],["name"]=[[HIW皇华长裤NOR]],["need"]=3,["pic"]=[[Image/UI/StoreUI/wuqi.png]],["thankText"]=[[YEL三尺龙泉剑，匣里无人见。
