待到浓雾散去，你蓦然发现，手上的珍品券已经变成了一本泛黄的武学秘籍，令你错愕不已。NOR]],["time"]=51,["title"]=[[全篇]]},["812"]={["id"]=812,["introText"]=[[WHT她生得雍容华美，自有一副端严之致，令人肃然起敬不敢逼视。]],["itemId"]=[[mianju1110]],["name"]=[[HIY蒙古郡主NOR]],["need"]=23,["pic"]=[[Image/UI/AttrUI/mianju/menggujunzhu.png]],["thankText"]=[[YEL你将珍品券递上，片刻后，一名身着红裙，容色艳丽不可方物的女子便向你走来，她莞尔一笑，说了句：“少侠，随我来。”

你随女子来到草原上。草原辽阔，无边无际，雄鹰在蓝空翱翔，牛羊在闲散漫步。见此美景，你心中也不禁涌起壮阔之感。女子牵拉两匹骏马，将一匹骏马的缰绳递给你。女子利落的翻身上马，问到：“少侠敢不敢与我一比？”你自信一笑，也翻身上马，回了句：“有何不敢!”

你们骑着骏马在草原驰骋，如雄鹰在天上展翅翱翔般，自由自在，无拘无束，好似天地间再无何物可以拦住你们的脚步。]],["time"]=51,["title"]=[[RED绚若红玫NOR]]},["813"]={["id"]=813,["introText"]=[[WHT双眸灵动，脉脉含情。相貌似有十六七岁年纪，身形却娇小如十三四岁的小姑娘。在万花的簇拥之下，抬手轻轻折下一枝，细嗅花香，尽显兰心蕙质。NOR]],["itemId"]=[[mianju1128]],["name"]=[[HIC灵姑娘NOR]],["need"]=15,["pic"]=[[Image/UI/AttrUI/mianju/chenglingsu1.png]],["thankText"]=[[YEL自洞庭湖北行三十余里，又穿过山镇，越过深林，你终于来到了庄前。庄内圆屋式样怪异，仿若一座大坟。你心下敬畏，硬着头皮喊门，但过了许久却无人搭理。你也不好硬闯，只能转道庄旁花圃处亭子小歇，静候主人归来。

微风徐徐，你坐在亭中闻着花圃传来的香气，只觉眼皮沉重，昏昏欲睡。“这花圃里的花有古怪！”当你意识到不对的时候，已经太迟，随后便是眼前一黑。

再醒转时，却看见一个双眸灵动的少女手中拿着你的珍宝券，嘴角满是笑意。

    “你的毒已经解了。我还以为是我师兄师姐上门来了，没想到来的人是你。”你心下叹服，随即向她询问了一些辟毒的法子，她也一一向你解答，一来二去，倒也算得上交谈甚欢。NOR]],["time"]=51,["title"]=[[PNK七心海棠NOR]]},["814"]={["id"]=814,["introText"]=[[WHT杏眼桃腮，明眸善睐。脸上总带着温婉的笑意，颇为惹人怜爱。NOR]],["itemId"]=[[mianju1174]],["name"]=[[YEL秋月NOR]],["need"]=12,["pic"]=[[Image/UI/AttrUI/mianju/qiuyuebai.png]],["thankText"]=[[YEL你方将珍品券递上，一个老管家便迎了上来。你随他来到前厅，在那与朱馆主寒暄了一会，正欲告辞离开却见天色忽暗，一副风雨欲来之景。朱馆主叹了口气道：“最近这天总是如此，变化无常。少侠不如在此歇息一晚，待明日天晴再启程改路吧。”
刚进客房便见桌脚边落有一白色帕子，帕上绣着“秋月”二字。秋月是朱府丫鬟，这许是她不小心遗落的。你叫住老管家问起秋月所在，谁知老管家脸色一变，只含糊了两句便离开了。
夜深，后院忽传出一声惊叫，你发觉一人影从窗外跑过。你即刻起身，追着人影来到池边。池边阴凉，只见一娇小女子立于水面。她长发披散，十指尖利，黑仁红瞳，邪气森然。“少侠，可还记得我？”NOR]],["time"]=51,["title"]=[[HIW江湖三友（四）NOR]]},["815"]={["id"]=815,["introText"]=[[WHT一件华贵的长袍。长袍用精细的蚕丝织成，上有金绶勾边，有改换轩辕，万象更新之意。只有宫中贵族方可穿此披袍。NOR]],["itemId"]=[[2021xclqeq5]],["name"]=[[HIW轩掖披袍NOR]],["need"]=3,["pic"]=[[Image/UI/StoreUI/wuqi.png]],["thankText"]=[[YEL三尺龙泉剑，匣里无人见。
