待到浓雾散去，你蓦然发现，手上的珍品券已经变成了一本泛黄的武学秘籍，令你错愕不已。NOR]],["time"]=52,["title"]=[[全篇]]},["826"]={["id"]=826,["introText"]=[[HIW她就是奎丽尔。金发碧眼，轻盼曼顾。那美丽的头发披散在身上，像一股金色的瀑布．波浪起伏，金光闪闪。来自大秦的红绸穿过锁骨，盖过细腰，勾勒出惊心动魄的美艳弧线。NOR]],["itemId"]=[[mianju1157]],["name"]=[[PNK奎丽尔NOR]],["need"]=23,["pic"]=[[Image/UI/AttrUI/mianju/kuilier.png]],["thankText"]=[[YEL尽管早已做好了心理准备，但是在她脱去黑袍，展现真身时，你双颊通红，心还是忍不住跳慢了一拍。

金发碧眼，曼妙无双，她对你浅笑的刹那，你下意识地想起了一句诗，“回眸一笑百媚生，六宫粉黛无颜色。”

“嘻嘻，我们那边的女子很多都是我这样的穿着。你用不着那么惊奇。”也许是夜晚时分身边的人并不多，又或许是她突然兴起，她径直挽起你的手向秦淮河畔走去，“秦淮河的风景很美，我真的很喜欢。”说罢，她对着你又是浅浅一笑。
你们挑了个能观赏江景小亭，便坐下举杯相饮。

晚风吹拂，秦淮河上流光溢彩，画舫相连灯火通明，耳畔传来歌女清唱，才子吟诵，酒客痛饮之声，身边的少女脸带微笑沉浸其中。你看着眼前的景象只觉似醉非醉，却不愿醒来。NOR]],["time"]=52,["title"]=[[ORA大秦少女NOR]]},["827"]={["id"]=827,["introText"]=[[HIW清雅秀丽，楚楚动人。少女盈盈十六七岁年华，身穿花红，肌肤雪白，眼底似有泪痕。眉毛微蹙，令人暗生情愫，如泣如诉，直叫人牵肠挂肚NOR]],["itemId"]=[[mianju1126]],["name"]=[[GRN朱姑娘NOR]],["need"]=15,["pic"]=[[Image/UI/AttrUI/mianju/azhu.png]],["thankText"]=[[YEL接过珍宝帖之时，她双目含泪，满面凄苦，似乎遇上了什么难事。你心有不忍，转而向她问询之时，她却闪烁其词。你方才想起，这些时日她跟丐帮的那位英雄人物逃亡天下闹得江湖皆知，眼下情景可能就是跟那位英雄有关，便试探地问了一句，“是因为萧英雄吗？”
“不，大哥他对我很好，是我......我不能再陪着他了。”一语说罢，似乎耗尽了她全部的气力，不管你再如何安慰，她始终是黯然垂首不发一言。你陪她静默良久，最终选择告辞离去。
出门之际，你依稀听到了她的低语，“只能下辈子再陪你塞上牧牛放羊了。”NOR]],["time"]=52,["title"]=[[BLU朱颜碧玉NOR]]},["828"]={["id"]=828,["introText"]=[[WHT面容清俊，笑脸迎人，让人心生亲切之感NOR]],["itemId"]=[[mianju1158]],["name"]=[[BLU小二NOR]],["need"]=12,["pic"]=[[Image/UI/AttrUI/mianju/dianxiaoer.png]],["thankText"]=[[YEL你来到酒楼随即将珍品券递上，片刻后你来到二楼寻得一处雅座。你点了一些菜品，将壶中清茶倒入杯中静待。

不多时，小二将菜品整齐摆放于桌上。酒足饭饱，你再度踏上旅途离开了酒楼。你行之不久，便听闻身后有一男子高呼少侠二字，声音有些熟悉，又有些陌生。

待人行近你这才看出，此人便是方才落脚的酒楼小二。小二气喘吁吁将一个钱袋递了过来，见此你摸向腰间这才发现自己的钱袋果然不见了。

你接过钱袋并未翻查银两，反而饶有兴致的询问小二为何不将钱财收入囊中，小二对此并未做多解释，只是爽朗一笑：“少侠说笑了，咱虽穷，但志不穷，店中事务繁忙，若银两并未遗失我这便告辞，还望少侠多来酒楼捧场。”小二说完与你辞别转身离去。NOR]],["time"]=52,["title"]=[[HIW人气小二NOR]]},["829"]={["id"]=829,["introText"]=[[WHT此靴为厚底尖头式。全靴以丝缎为面，使用了大量金线、米珠和珊瑚作装饰，两只靴子上分别绘有雌雄鸳鸯一只，寓意春江水暖，双喜临门。NOR]],["itemId"]=[[2021xclqeq9]],["name"]=[[HIW鸳鸯暖水NOR]],["need"]=3,["pic"]=[[Image/UI/StoreUI/wuqi.png]],["thankText"]=[[YEL三尺龙泉剑，匣里无人见。
