待到浓雾散去，你蓦然发现，手上的珍品券已经变成了一本泛黄的武学秘籍，令你错愕不已。NOR]],["time"]=10,["title"]=[[全篇]]},["89"]={["id"]=89,["introText"]=[[WHT他就是神使劳伦斯。他发棕微卷，眉目深邃，一双如琥珀般剔透晶莹的双眼闪烁着摄人心魄的光芒。身着便服时，是个狡诈冷酷的商人，身披铠甲时，亦是号令三军的统帅。NOR]],["itemId"]=[[mianju1147]],["name"]=[[BLU左神使NOR]],["need"]=30,["pic"]=[[Image/UI/AttrUI/mianju/zuoshenshi.png]],["thankText"]=[[YEL你将拜帖递上，片刻后出来二位金发美姬，对你盈盈一拜，笑道：“神使有请！”
你随之走进一幢西式小楼，只见大厅内富丽堂皇，壁炉设于墙边，钟表挂于墙上，一张长达数丈的餐桌立于大厅中央，上面摆满各种漆器银皿。
劳伦斯坐于上首，对你轻轻点头，示意你入座，随后两掌一拍，只见数位金发美姬鱼贯而入，将手上的菜肴端放在餐桌上。你与劳伦斯二人拿起银制刀叉，将盘子里的牛排切成块状，送入口中，牛肉入口即化，这种西方独特的烹制手法，令你大开眼界。
餐毕，劳伦斯手捧餐巾轻轻擦拭着嘴角，对你说道：“虽然我们共进晚餐，但终究道路不同，也许彼此仍是敌人。是敌是友，谁对谁错，这都不重要了。愿重光赐予你祝福。”NOR]],["time"]=10,["title"]=[[BLU重光左使NOR]]},["9"]={["id"]=9,["introText"]=[[据称是一蓬莱高手所创的独门轻功，不注重飞檐走壁，而是注重交手之际的极速腾挪。施展之时，来去如风，极为飘逸。]],["itemId"]=[[feiyingshisanshi]],["name"]=[[    MAG飞影十三逝NOR]],["need"]=12,["pic"]=[[Image/UI/StoreUI/shujuan2.png]],["thankText"]=[[YEL满月临弓影，连星入剑端。
不学燕丹客，徒歌易水寒。
你沉吟不语，将武学名录捧于手上，似在心中思索着什么。
须臾间，空中一股浓雾飘散而来，遮蔽了你的视线。
待到浓雾散去，你蓦然发现，手上的武学名录已经变成了一本泛黄的武学秘籍，令你错愕不已。NOR]],["time"]=2,["title"]=[[全篇]]},["90"]={["id"]=90,["introText"]=[[WHT他就是乔大侠。他生得苍眉劲眼，高鼻阔口。三十来岁年纪，身材甚是伟岸，一张四方的国字脸，颇有风霜之色，顾盼睥睨之际，极具威严。随便一站，似是一条黑须苍龙傲立而起。NOR]],["itemId"]=[[mianju1125]],["name"]=[[YEL乔大侠NOR]],["need"]=25,["pic"]=[[Image/UI/AttrUI/mianju/qiaofeng.png]],["thankText"]=[[YEL你将珍品券递上，一名小二自酒楼中小跑而出，恭敬道：“少侠里边请。”
小二领着你进入酒楼内，这是一家远近闻名的酒楼，这会正值午时，大堂内是座无空席，热闹非凡。你跟着小二走到窗边，这里相比大堂中间要清净一些，而一名高大威猛的男子已坐在桌前。男子生得一张国字脸，虽带有风霜之色但也掩不住他的威严之气。你还未走近，他已起身相迎，你不由得加快了脚步。待你入座后，男子又对小二说道：“先打十斤高粱来。”
就当你们喝得尽兴时，来了两位侠客上前请男子指教，一手拿着酒壶，只用单手便将两人轻松制服。为防再有人来打扰你们的兴致，男子便打了几壶酒与你寻了一处无人的山坡们，席地而坐，喝得不知天时流转。NOR]],["time"]=10,["title"]=[[YEL契丹真龙NOR]]},["91"]={["id"]=91,["introText"]=[[WHT他就是黄师傅。他身躯凛凛，相貌堂堂。一双眼睛射寒星，两弯剑眉如刷漆。气宇轩昂，大红的舞狮头肩上扛。从容不迫，将脑后束起的一根长辫咬在口中。NOR]],["itemId"]=[[mianju1130]],["name"]=[[HIY黄师傅NOR]],["need"]=20,["pic"]=[[Image/UI/AttrUI/mianju/huangshifu.png]],["thankText"]=[[YEL珍品券送入不久后，走出一位身着黄布衣的男子，拱手道：“黄师傅正在做准备，请少侠稍等。”
你方与男子聊了两句，前边突然开始敲锣打鼓，人群也喧闹了起来。你随着人群往前方走去，便见着一位气宇轩昂的男子，扛着大红的舞狮头随着鼓点起舞。时喜时醉，时惊时怒，在木桩上灵巧跃动，表演得形神合一，生动活泼。
一场舞狮结束，你只觉意犹未尽，正巧此时黄布衣的男子替黄师傅来邀你至武馆中一叙，你欣然同意。武馆中，黄师傅早已命人备好茶水，你们畅谈古今，相谈甚欢，竟忘了时间，待回过神来已是华灯初上，你才依依不舍地告辞离去。
NOR]],["time"]=10,["title"]=[[RED醒狮飞鸿NOR]]},["92"]={["id"]=92,["introText"]=[[WHT她就是紫姑娘。她颜若朝霞，双眸灿烂。眼神总有狡黠之色，眉宇之间似笑非笑。乌溜溜的眼中透着古灵精怪，亦正亦邪的气质，让人难识其本性。NOR]],["itemId"]=[[mianju1129]],["name"]=[[MAG紫姑娘NOR]],["need"]=14,["pic"]=[[Image/UI/AttrUI/mianju/ziguniang.png]],["thankText"]=[[YEL你刚将珍品券送上，便听见林间瑟瑟作响，一团漆黑的东西忽地向你袭来，你身形一闪，灵巧躲过。而那团漆黑的东西落在地上瞬时舒展开来，原是一条漆黑的长蛇，蛇头呈三角状，身有手腕粗，吐出的蛇信子红中带黑，你一瞧便知它剧毒无比。
一枚银针忽地扎入蛇身，方要游走的黑蛇扭动了几下便瘫软在地一动不动了。“你躲得倒是挺快。”话音刚落，一位身着松花绿衣裙的女子自花树间钻出，看着你笑道：“我在这捉了一天的蛇，甚是无聊，你陪我至山下转转。”
你点头应好，与她前往山下镇子，市井热闹，摊贩林立，你们好一阵玩耍，直至夜深才告辞分别。
NOR]],["time"]=10,["title"]=[[HIR恶紫夺朱NOR]]},["93"]={["id"]=93,["introText"]=[[WHT她就是沐临烟。她生得玉骨冰肌，古人若说起闺阁小姐、大家闺秀总归便是她这般的姿态。她虽能惊艳一堂，却少了与其他美人区分开来的特点。倘若真要说出个什么不同，便是她眼下泪痣，目中情深。但江湖，似乎并不需要这样娇滴滴的美人。NOR]],["itemId"]=[[mianju1094]],["name"]=[[HIC沐临烟NOR]],["need"]=6,["pic"]=[[Image/UI/AttrUI/mianju/mulingyan.png]],["thankText"]=[[YEL你将珍品券递上，片刻后走出一位青衣侍女，恭敬道：“小姐有请。”
你随侍女穿过长廊，走到后院的花园中。你一眼便瞧见了那颗树冠红似火的红枫，脑海里不禁冒出那句“停车坐爱枫林晚，霜叶红于二月花。”
更引人注目的是红枫树下的那一抹蓝色身影，一位女子抱琴立于树下，她只略施粉黛，着靛青长裙，纤腰婀娜，宛若仙姝，不减神女。虽似莲花般清雅，但也带有寒梅的傲骨。
你们坐于红枫下，她问起你近况如何？在江湖闯荡可有受伤？又道你是她少有的朋友，随后她弹起一首新学的曲子。琴声婉转，似山泉自幽谷缓缓流淌而来，在你心头萦绕不去。NOR]],["time"]=10,["title"]=[[HIW江湖三友NOR]]},["94"]={["id"]=94,["introText"]=[[WHT这就是青山悦云。一件广袖竖领对襟长袍，质地轻滑，颜色犹如山顶朝暮间云雾的变幻，由浓转淡，泠然善也，独具风骨。NOR]],["itemId"]=[[20hyeq1]],["name"]=[[HUB青山悦云NOR]],["need"]=2,["pic"]=[[Image/UI/StoreUI/wuqi.png]],["thankText"]=[[YEL三尺龙泉剑，匣里无人见。
一张落雁弓，百支金花箭。
你沉吟不语，将珍品券捧于手上，似在心中思索着什么。
须臾间，空中一股浓雾飘散而来，遮蔽了你的视线。
待到浓雾散去，你蓦然发现，你的手上竟多了一件宝光四射的装备，而那张珍品券早已不知所踪。NOR]],["time"]=10,["title"]=[[HIW珍品装备NOR]]},["95"]={["id"]=95,["introText"]=[[WHT这就是长情不负。传说孟姜女为丈夫千里送寒衣时，曾用神木的雪色树叶编制出坚韧无双的手套，后来无数人效仿其形，取名为“长情不负”。NOR]],["itemId"]=[[20hyeq2]],["name"]=[[HUB长情不负NOR]],["need"]=2,["pic"]=[[Image/UI/StoreUI/wuqi.png]],["thankText"]=[[YEL三尺龙泉剑，匣里无人见。
